	// Account Settings.
	public static function account_settings($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M::get_student($user_id);

			if ($student) {
				$data['user_type'] = self::STUDENT_PREFIX;
			} else {
				$unique_student_ids = WLSM_M_Parent::get_parent_student_ids($user_id);
				if (count($unique_student_ids)) {
					$data['user_type'] = self::PARENT_PREFIX;
				} else {
					return self::no_account();
				}
			}

			$params = $request->get_params();

			$name = !empty($params['name']) ? sanitize_text_field($params['name']) : $student->student_name;
			$email = !empty($params['email']) ? sanitize_text_field($params['email']) : $student->email;
			$phone = !empty($params['phone']) ? sanitize_text_field($params['phone']) : $student->phone;
			$address = !empty($params['address']) ? sanitize_text_field($params['address']) : $student->address;
			$city = !empty($params['city']) ? sanitize_text_field($params['city']) : $student->city;
			$state = !empty($params['state']) ? sanitize_text_field($params['state']) : $student->state;
			$country = !empty($params['country']) ? sanitize_text_field($params['country']) : $student->country;
			$father_name = !empty($params['father_name']) ? sanitize_text_field($params['father_name']) : $student->father_name;
			$father_phone = !empty($params['father_phone']) ? sanitize_text_field($params['father_phone']) : $student->father_phone;
			$father_occupation = !empty($params['father_occupation']) ? sanitize_text_field($params['father_occupation']) : $student->father_occupation;
			$mother_name = !empty($params['mother_name']) ? sanitize_text_field($params['mother_name']) : $student->mother_name;
			$mother_phone = !empty($params['mother_phone']) ? sanitize_text_field($params['mother_phone']) : $student->mother_phone;
			$mother_occupation = !empty($params['mother_occupation']) ? sanitize_text_field($params['mother_occupation']) : $student->mother_occupation;
			$user_email = !empty($params['user_email']) ? sanitize_email($params['user_email']) : $student->user_email;
			$password = isset($params['password']) ? $params['password'] : '';
			$password_confirm = isset($params['password_confirm']) ? $params['password_confirm'] : '';

			if (empty($user_email)) {
				throw new Exception(esc_html__('Please provide email address.', 'school-management'));
			}

			if (!filter_var($user_email, FILTER_VALIDATE_EMAIL)) {
				throw new Exception(esc_html__('Please provide a valid email.', 'school-management'));
			}

			if (empty($password)) {
				throw new Exception(esc_html__('Please provide password.', 'school-management'));
			}

			if (empty($password_confirm)) {
				throw new Exception(esc_html__('Please confirm password.', 'school-management'));
			}

			if ($password !== $password_confirm) {
				throw new Exception(esc_html__('Passwords do not match.', 'school-management'));
			}

			$student_data = array(
				'name' 				=> $name,
				'email' 			=> $email,
				'phone' 			=> $phone,
				'address' 			=> $address,
				'city' 				=> $city,
				'state' 			=> $state,
				'country' 			=> $country,
				'father_name' 		=> $father_name,
				'father_phone' 		=> $father_phone,
				'father_occupation' => $father_occupation,
				'mother_name' 		=> $mother_name,
				'mother_phone' 		=> $mother_phone,
				'mother_occupation' => $mother_occupation,
			);

			$success = $wpdb->update(WLSM_STUDENT_RECORDS, $student_data, array('user_id' => $user_id));
			$message = esc_html__('Account settings updated.', 'school-management');

			$user = wp_get_current_user();

			$data = array(
				'ID' => $user->ID,
				'user_email' => $user_email,
				'user_pass' => $password,
			);

			$user_id = wp_update_user($data);

			if (is_wp_error($user_id)) {
				throw new Exception($user_id->get_error_message());
			}

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

