	// Student - Dashboard.
	public static function student_dashboard($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M::get_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$school_id = $student->school_id;
			$session_id = $student->session_id;
			$class_school_id = $student->class_school_id;

			// Student photo
			$student_logo = WLSM_M::get_student_profile($user_id);
			$student_photo = wp_get_attachment_url($student_logo->photo_id) ?: '';

			// Student details
			$common_details = self::student_common_details($student);
			$other_details = array(
				'name' => esc_html(WLSM_M_Staff_Class::get_name_text($student->student_name)),
				'enrollment_number' => esc_html($student->enrollment_number),
				'session' => esc_html(WLSM_M_Session::get_label_text($student->session_label)),
				'class' => esc_html(WLSM_M_Class::get_label_text($student->class_label)),
				'section' => esc_html(WLSM_M_Class::get_label_text($student->section_label)),
				'roll_number' => esc_html(WLSM_M_Staff_Class::get_roll_no_text($student->roll_number)),
				'father_name' => esc_html(WLSM_M_Staff_Class::get_name_text($student->father_name)),
				'photo' => esc_url($student_photo),
			);
			$response_data['student'] = array_merge($common_details, $other_details);

			// Attendance stats
			$response_data['attendance'] = WLSM_M_Staff_General::get_student_attendance_stats_consolidated($student->ID);

			$params = $request->get_params();

			// Notices query
			$notices_query = WLSM_M::notices_query();

			// Total notices
			$notices_total = $wpdb->get_var(
				$wpdb->prepare(
					"SELECT COUNT(1) FROM ({$notices_query}) AS combined_table",
					$class_school_id,
					$class_school_id,
					$school_id
				)
			);

			// Pagination
			$notices_page = isset($params['notices_page']) ? absint($params['notices_page']) : 1;
			$notices_per_page = isset($params['notices_per_page']) ? absint($params['notices_per_page']) : WLSM_M::notices_per_page();
			$notices_offset = ($notices_page - 1) * $notices_per_page;

			// Paginated data
			$notices = $wpdb->get_results(
				$wpdb->prepare(
					$notices_query . ' ORDER BY n.ID DESC LIMIT %d, %d',
					$notices_offset,
					$notices_per_page
				)
			);

			// Filter notices by class only
			$filtered_notices = array();
			foreach ($notices as $notice) {
				$notice_data = @unserialize($notice->notice_data);

				// Default to 'all' if no valid notice_data
				if ($notice_data === false || !isset($notice_data['classes'])) {
					$notice_data = array('classes' => array('all'));
				}

				$notice_data['classes'] = (array) $notice_data['classes'];

				// Class match check
				if (in_array($student->class_id, $notice_data['classes'], true) || in_array('all', $notice_data['classes'], true)) {
					$filtered_notices[] = $notice;
				}
			}

			// Prepare notices data
			$notices_data = array();
			$notices_pagination = array(
				'current_page' => $notices_page,
				'per_page' => $notices_per_page,
			);

			if (count($filtered_notices)) {
				$today = new DateTime();
				$today->setTime(0, 0, 0);

				foreach ($filtered_notices as $notice) {
					$link = '#';

					if ('url' === $notice->link_to && !empty($notice->url)) {
						$link = $notice->url;
					} elseif ('attachment' === $notice->link_to && !empty($notice->attachment)) {
						$link = wp_get_attachment_url($notice->attachment);
					}

					$notice_date = DateTime::createFromFormat('Y-m-d H:i:s', $notice->created_at);
					$notice_date->setTime(0, 0, 0);

					$is_new = ($today->diff($notice_date)->days < 7);

					$notices_data[] = array(
						'id' => $notice->ID,
						'title' => esc_html(stripslashes($notice->title)),
						'description' => esc_html(stripslashes($notice->description)),
						'link' => esc_url($link),
						'date' => esc_html(WLSM_Config::get_date_text($notice->created_at)),
						'is_new' => $is_new,
						'notice_filter_data' => $notice->notice_data,
					);
				}

				$notices_pagination['total_pages'] = ceil($notices_total / $notices_per_page);
				$notices_pagination['total_records'] = $notices_total;
			}

			// Response success
			$success = true;
			$message = esc_html__('Student dashboard retrieved successfully.', 'school-management');

			$response_data['noticeboard'] = array(
				'new_notice_icon' => esc_url(WLSM_PLUGIN_URL . 'assets/images/newicon.gif'),
				'data' => $notices_data
				// Pagination intentionally removed like in original code
			);

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Transport
	public static function student_transport($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M::get_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id 	= $student->school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			// Get transportation details
			$vehicle_id = $student->route_vehicle_id;
			$transportation_data = null;

			if ($vehicle_id) {
				$query = $wpdb->prepare(
					'SELECT ro.name, ro.fare, v.vehicle_number, v.driver_name, v.driver_phone
					FROM ' . WLSM_ROUTE_VEHICLE . ' as rov
					JOIN ' . WLSM_ROUTES . ' as ro ON ro.ID = rov.route_id
					JOIN ' . WLSM_VEHICLES . ' as v ON v.ID = rov.vehicle_id
					WHERE rov.ID = %d',
					$vehicle_id
				);
				$transportation_details = $wpdb->get_results($query);

				if (!empty($transportation_details)) {
					$transport = $transportation_details[0];
					$transportation_data = array(
						'route_name' => esc_html($transport->name),
						'vehicle_number' => esc_html($transport->vehicle_number),
						'fare' => esc_html(WLSM_Config::get_money_text($transport->fare, $school_id)),
						'driver_name' => esc_html($transport->driver_name) ?: '',
						'driver_phone' => esc_html($transport->driver_phone) ?: '',
					);
				}
			}

			$response_data['transportation'] = $transportation_data;

			$success = true;
			$message = esc_html__('Transportation details retrieved successfully.', 'school-management');

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Fee Structure.
	public static function student_fee_structure($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$start_date  = $student->start_date;
			$end_date    = $student->end_date;

			// get start_date and end_date difference in months
			$start_date        = new DateTime($start_date);
			$end_date          = new DateTime($end_date);
			$interval          = $start_date->diff($end_date);
			$months_in_session = $interval->format('%m');

			$interval = $start_date->diff($end_date);
			// Calculate total months including years
			$months_in_session = ($interval->y * 12) + $interval->m;

			// If you want to consider partial months (days)
			if ($interval->d > 0) {
				++$months_in_session; // Add one more month if there are remaining days
			}

			$params = $request->get_params();

			$fees   = WLSM_M_Staff_Accountant::fetch_student_fees($school_id, $student->ID);

			$fee_structure_data = array();

			if (count($fees)) {
				$session_onetime_total      = 0;
				$session_quarterly_total    = 0;
				$session_quadrimester_total = 0;
				$session_half_yearly_total  = 0;
				$session_monthly_total      = 0;
				$session_yearly_total       = 0;

				foreach ($fees as $key => $fee) {
					if ($fee->period == 'monthly') {
						$payment_occuration = $months_in_session;
						$session_monthly_total += intval($fee->amount) * $months_in_session;
						$session_total = WLSM_Config::get_money_text(intval($fee->amount) * $months_in_session, $school_id);
					} elseif ($fee->period == 'one-time') {
						$payment_occuration = 1;
						$session_onetime_total += intval($fee->amount);
						$session_total = WLSM_Config::get_money_text($fee->amount, $school_id);
					} elseif ($fee->period == 'quarterly') {
						$payment_occuration = ceil($months_in_session / 3); // Fixed: quarterly is 3 months, not 4
						$session_quarterly_total += intval($fee->amount) * $payment_occuration;
						$session_total = WLSM_Config::get_money_text(($fee->amount) * $payment_occuration, $school_id);
					} elseif ($fee->period == 'quadrimester') {
						$payment_occuration = ceil($months_in_session / 4); // Fixed: quadrimester is 4 months
						$session_quadrimester_total += intval($fee->amount) * $payment_occuration;
						$session_total = WLSM_Config::get_money_text(($fee->amount) * $payment_occuration, $school_id);
					} elseif ($fee->period == 'half-yearly') {
						$payment_occuration = ceil($months_in_session / 6);
						$session_half_yearly_total += intval($fee->amount) * $payment_occuration;
						$session_total = WLSM_Config::get_money_text(($fee->amount) * $payment_occuration, $school_id);
					} elseif ($fee->period == 'annually') {
						$payment_occuration = ceil($months_in_session / 12);
						$yearly_amount = intval($fee->amount) * $payment_occuration;
						$session_yearly_total += $yearly_amount; // Fixed: calculating correctly by years
						$session_total = WLSM_Config::get_money_text($yearly_amount, $school_id);
					} else {
						$payment_occuration = '-';
					}

					$fee_structure_data[] = array(
						'id' 					=> isset($fee->ID) ? absint($fee->ID) : 0,
						'fee_type' 				=> isset($fee->label) ? WLSM_M_Staff_Accountant::get_label_text($fee->label) : '',
						'amount' 				=> isset($fee->amount) ? WLSM_Config::get_money_text($fee->amount, $school_id) : '',
						'period' 				=> isset($fee->period) ? WLSM_M_Staff_Accountant::get_fee_period_text($fee->period) : '',
						'payment_occuration' 	=> $payment_occuration,
						'session_total' 		=> $session_total
					);
				}

				$total_session_fee = $session_monthly_total + $session_onetime_total + $session_quarterly_total + $session_quadrimester_total + $session_half_yearly_total + $session_yearly_total;
				$student_concession = WLSM_M_Staff_General::fetch_student_concession($student->ID, $student->session_id, $school_id);
				$concession_amount = 0;
				$concession_label = '';
				$payable_amount = $total_session_fee;

				if ($student_concession && 'approved' === $student_concession->status) {
					if ('percentage' === $student_concession->concession_type) {
						$concession_amount = ($total_session_fee * $student_concession->percentage_value) / 100;
						$concession_label = sprintf(
							'%s (%s)',
							$student_concession->concession_name,
							$student_concession->percentage_value . '%'
						);
					} elseif ('fixed_amount' === $student_concession->concession_type) {
						$concession_amount = min($student_concession->fixed_amount, $total_session_fee);
						$concession_label = sprintf(
							'%s (%s)',
							$student_concession->concession_name,
							__('Fixed', 'school-management')
						);
					}

					$payable_amount = max($total_session_fee - $concession_amount, 0);
				}

				$fee_type_total = WLSM_Config::get_money_text($total_session_fee, $school_id);
				$consession_fee = WLSM_Config::get_money_text($concession_amount, $school_id);
				$amount_payable = WLSM_Config::get_money_text($payable_amount, $school_id);

				$fee_data = array(
					'fee_type_total' => $fee_type_total,
					$concession_label => $consession_fee,
					'payable_amount' => $amount_payable
				);
			}

			$success = true;
			$message = esc_html__('Fee structure retrieved successfully.', 'school-management');

			$response_data['fee_structure_data'] = array(
				'fee_types' => $fee_structure_data,
				'fee_data'  => $fee_data
			);
			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Noticeboard.
	public static function student_noticeboard($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$school_id = $student->school_id;
			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;
			$params = $request->get_params();

			// Query
			$notices_query = WLSM_M::notices_query();

			// Total count
			$notices_total = $wpdb->get_var(
				$wpdb->prepare(
					"SELECT COUNT(1) FROM ({$notices_query}) AS combined_table",
					$class_school_id,
					$class_school_id,
					$school_id
				)
			);

			// Pagination
			$notices_page = isset($params['notices_page']) ? (int) $params['notices_page'] : 1;
			$notices_per_page = isset($params['notices_per_page']) ? (int) $params['notices_per_page'] : WLSM_M::notices_per_page();
			$notices_offset = ($notices_page - 1) * $notices_per_page;

			// Paginated results
			$notices = $wpdb->get_results(
				$wpdb->prepare(
					$notices_query . ' ORDER BY n.ID DESC LIMIT %d, %d',
					$notices_offset,
					$notices_per_page
				)
			);

			$filtered_notices = array();

			// Only filter by class
			foreach ($notices as $notice) {
				$notice_data = @unserialize($notice->notice_data);
				if ($notice_data === false) {
					$notice_data = array('classes' => array('all'));
				}

				// Ensure classes array exists
				$notice_data['classes'] = isset($notice_data['classes']) ? (array) $notice_data['classes'] : array('all');

				// Match by class_id or "all"
				if (in_array($student->class_id, $notice_data['classes'], true) || in_array('all', $notice_data['classes'], true)) {
					$filtered_notices[] = $notice;
				}
			}

			// Format response
			$notices_data = array();
			$notices_pagination = array(
				'current_page' => $notices_page,
				'per_page' => $notices_per_page,
			);

			if (count($filtered_notices)) {
				$today = new DateTime();
				$today->setTime(0, 0, 0);

				foreach ($filtered_notices as $notice) {
					$link = '#';

					if ('url' === $notice->link_to && !empty($notice->url)) {
						$link = $notice->url;
					} elseif ('attachment' === $notice->link_to && !empty($notice->attachment)) {
						$link = wp_get_attachment_url($notice->attachment);
					}

					$notice_date = DateTime::createFromFormat('Y-m-d H:i:s', $notice->created_at);
					$notice_date->setTime(0, 0, 0);

					$is_new = ($today->diff($notice_date)->days < 7);

					$notices_data[] = array(
						'id' => $notice->ID,
						'title' => esc_html(stripslashes($notice->title)),
						'description' => esc_html(stripslashes($notice->description)),
						'link' => esc_url($link),
						'date' => esc_html(WLSM_Config::get_date_text($notice->created_at)),
						'is_new' => $is_new,
						'notice_filter_data' => $notice->notice_data,
					);
				}

				$notices_pagination['total_pages'] = ceil($notices_total / $notices_per_page);
				$notices_pagination['total_records'] = $notices_total;
			}

			$success = true;
			$message = esc_html__('Noticeboard retrieved successfully.', 'school-management');

			$response_data['noticeboard'] = array(
				'new_notice_icon' => esc_url(trailingslashit(WLSM_PLUGIN_URL) . 'assets/images/new-notice-icon.gif'),
				'data' => $notices_data,
				'pagination' => $notices_pagination
			);

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

