	// Student - Live classes.
	public static function student_live_classes($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$school_id = $student->school_id;

			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$params = $request->get_params();

			// Query.
			$meetings_query = WLSM_M::meetings_query();

			// Total.
			$meetings_total = $wpdb->get_var($wpdb->prepare("SELECT COUNT(1) FROM ({$meetings_query}) AS combined_table", $school_id, $class_school_id));

			// Current page and per page.
			$meetings_page = isset($params['live_classes_page']) ? absint($params['live_classes_page']) : 1;
			$meetings_per_page = isset($params['live_classes_per_page']) ? absint($params['live_classes_per_page']) : WLSM_M::meetings_per_page();

			// Page offset.
			$meetings_page_offset = ($meetings_page * $meetings_per_page) - $meetings_per_page;

			// Paginated data.
			$meetings = $wpdb->get_results($wpdb->prepare($meetings_query . ' ORDER BY mt.start_at DESC, mt.ID DESC LIMIT %d, %d', $school_id, $class_school_id, $meetings_page_offset, $meetings_per_page));

			// Paginated response.
			$meetings_data = array();
			$meetings_pagination = array(
				'current_page' => $meetings_page,
				'per_page' => $meetings_per_page,
			);

			// Format response.
			if (count($meetings)) {
				foreach ($meetings as $key => $row) {

					$sdk_key = get_the_author_meta('sdk_key', $row->user_id);
					$sdk_secret = get_the_author_meta('sdk_secret', $row->user_id);
					$api_key = get_the_author_meta('api_key', $row->user_id);
					$api_secret = get_the_author_meta('api_secret', $row->user_id);

					// For BigBlueButton meetings, generate join URL dynamically if not set
					$join_url = $row->join_url;
					if ($row->class_type === 'bbb_class' && empty($join_url)) {
						// Check if BigBlueButton API class exists
						if (class_exists('SM_Bigbluebutton_Api')) {
							// Get current user for username
							$current_user = wp_get_current_user();
							$username = $current_user->display_name ? $current_user->display_name : 'Student';

							// Generate join URL for BigBlueButton
							// Using viewer mode (0) for students
							$join_url = SM_Bigbluebutton_Api::get_join_meeting_url(
								$username,
								'moderator_' . $row->meeting_id, // moderator code
								$row->password, // viewer code (password)
								$row->recordable ? $row->recordable : 0,
								$row->meeting_id,
								null, // logout URL
								0 // 0 = viewer mode for students
							);
						}
					}

					$meetings_data[] = array(
						'id' => $row->ID,
						'meeting_id' => $row->meeting_id,
						'topic' => esc_html($row->topic),
						'duration' => esc_html($row->duration),
						'start_date_time' => esc_html(WLSM_Config::get_at_text($row->start_at)),
						'type' => esc_html(WLSM_Helper::get_meeting_type($row->type)),
						'join_url' => $join_url, // Raw URL for API (not HTML-encoded)
						'password' => esc_html($row->password),
						'subject' => esc_html($row->subject_name),
						'teacher' => esc_html($row->name),
						'sdk_key' => esc_html($sdk_key),
						'sdk_secret' => esc_html($sdk_secret),
						'api_key' => esc_html($api_key),
						'api_secret' => esc_html($api_secret),
						'class_type' => esc_html($row->class_type), // Added to identify BBB vs Zoom
					);
				}

				$meetings_pagination['total_pages'] = ceil($meetings_total / $meetings_per_page);
				$meetings_pagination['total_records'] = $meetings_total;
			}

			$success = true;
			$message = esc_html__('Live classes retrieved successfully.', 'school-management');

			$response_data['live_classes'] = array(
				'data' => $meetings_data,
				'pagination' => $meetings_pagination
			);

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Submit staff rating
	public static function submit_staff_rating($request)
	{
		$user_id = get_current_user_id();

		try {
			$student = WLSM_M::get_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			global $wpdb;

			$school_id 	= $student->school_id;
			$session_id = $student->session_id;

			$params 		= $request->get_params();
			$live_class_id 	= isset($params['live_class_id']) ? absint($params['live_class_id']) : 0;
			$rating 		= isset($params['rating']) ? absint($params['rating']) : 0;
			$message 		= isset($params['message']) ? sanitize_text_field($params['message']) : '';

			if (empty($live_class_id)) {
				throw new Exception(esc_html__('Please select a live class.', 'school-management'));
			}

			if (empty($rating) || $rating < 1 || $rating > 5) {
				throw new Exception(esc_html__('Please provide a rating between 1 and 5.', 'school-management'));
			}

			// Check if live class exists
			$live_class = $wpdb->get_row($wpdb->prepare(
				'SELECT ID FROM ' . WLSM_MEETINGS . ' WHERE ID = %d',
				$live_class_id
			));

			if (!$live_class) {
				throw new Exception(esc_html__('Live class not found.', 'school-management'));
			}

			// Check if student already rated this live class
			$existing_rating = $wpdb->get_row($wpdb->prepare(
				'SELECT ID FROM ' . WLSM_RATTING . ' WHERE student_id = %d AND live_class_id = %d',
				$student->ID,
				$live_class_id
			));

			$wpdb->query('BEGIN;');

			$data = array(
				'student_id' 	=> $student->ID,
				'live_class_id' => $live_class_id,
				'ratting' 		=> $rating,
				'message' 		=> $message
			);

			if (! $existing_rating) {
				// Insert new rating
				$data['created_at'] = current_time('Y-m-d H:i:s');
				$success = $wpdb->insert(WLSM_RATTING, $data);
				$message = esc_html__('Staff rating added successfully.', 'school-management');
				$message_text = $message;
			}

			WLSM_Helper::check_buffer();

			if (false === $success) {
				throw new Exception($wpdb->last_error);
			}

			$wpdb->query('COMMIT;');

			$success = true;

			$response_data = array(
				'rating_id' => $existing_rating ? $existing_rating->ID : $wpdb->insert_id
			);
		} catch (Exception $exception) {
			$success = false;
			$message_text = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message_text,
		);

		if (!empty($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Attendance.
	public static function student_attendance($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id = $student->class_school_id;

			$section_id = $student->section_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			// Fetch consolidated overall attendance (subject_id IS NOT NULL handled correctly).
			$attendance = WLSM_M_Staff_General::get_student_attendance_overall_consolidated($student_id);

			$data = array();

			$total_attendance = 0;
			$total_present = 0;
			$total_absent = 0;
			$total_late = 0;
			$total_holiday = 0;

			$attendance_monthly = array();
			foreach ($attendance as $monthly) {
				$month = new DateTime();
				$month->setDate($monthly->year, $monthly->month, 1);
				$total_attendance += $monthly->total_attendance;
				$total_present += $monthly->total_present;
				$total_absent += $monthly->total_absent;
				$total_late += $monthly->total_late;
				$total_holiday += $monthly->total_holiday;

				$attendance_data = array(
					'month' => esc_html($month->format('F Y')),
					'total_attendance' => esc_html($monthly->total_attendance),
					'total_present' => esc_html($monthly->total_present),
					'total_absent' => esc_html($monthly->total_absent),
					'total_holidays' => esc_html($monthly->total_holiday),
					'total_late' => esc_html($monthly->total_late),
				);

				array_push($attendance_monthly, $attendance_data);
			}

			// Overall consolidated data.
			$percentage_value = 0;
			if ($total_attendance > 0) {
				$percentage_value = ($total_present * 100) / $total_attendance;
			}

			$data['overall'] = array(
				'total_attendance' => $total_attendance,
				'total_present' => $total_present,
				'total_absent' => $total_absent,
				'percentage_value' => number_format($percentage_value, 2, '.', ''),
				'percentage_text' => WLSM_Config::get_percentage_text($total_attendance, $total_present, 1)
			);

			$data['monthly'] = $attendance_monthly;

			// Fetch subject-wise attendance.
			$subject_wise_attendance = WLSM_M_Staff_General::get_student_subject_wise_attendance($student_id);
			$data['subject_wise'] = array();

			foreach ($subject_wise_attendance as $subject_data) {
				$data['subject_wise'][] = array(
					'subject_label' => esc_html($subject_data->subject_label),
					'subject_code' => esc_html($subject_data->subject_code),
					'total_attendance' => esc_html($subject_data->total_attendance),
					'total_present' => esc_html($subject_data->total_present),
					'total_absent' => esc_html($subject_data->total_absent),
					'total_late' => esc_html($subject_data->total_late),
					'percentage_text' => WLSM_Config::get_percentage_text($subject_data->total_attendance, $subject_data->total_present, 1)
				);
			}

			$success = true;
			$message = esc_html__('Attendance retrieved successfully.', 'school-management');

			$response_data['attendance'] = $data;

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

