	// Student - Exam result.
	public static function exam_result($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$params = $request->get_params();

			$admit_card_id = isset($params['admit_card_id']) ? absint($params['admit_card_id']) : 0;

			// Checks if admit card exists for published exam result.
			$admit_card = WLSM_M_Staff_Examination::get_student_published_exam_result($school_id, $student->ID, $admit_card_id);

			if (!$admit_card) {
				throw new Exception(esc_html__('Exam result not found.', 'school-management'));
			}

			$exam = WLSM_M_Staff_Examination::fetch_exam($school_id, $admit_card->exam_id);

			$exam_id = $exam->ID;
			$exam_title = $exam->exam_title;
			$exam_center = $exam->exam_center;
			$start_date = $exam->start_date;
			$end_date = $exam->end_date;

			$exam_papers = WLSM_M_Staff_Examination::get_exam_papers_by_admit_card($school_id, $admit_card_id);
			$exam_results = WLSM_M_Staff_Examination::get_exam_results_by_admit_card($school_id, $admit_card_id);

			$grade_criteria = WLSM_Config::sanitize_grade_criteria($exam->grade_criteria);

			$enable_overall_grade = $grade_criteria['enable_overall_grade'];
			$marks_grades = $grade_criteria['marks_grades'];

			$show_marks_grades = count($marks_grades);

			$student_rank = WLSM_M_Staff_Examination::calculate_exam_ranks($school_id, $exam_id, array(), $admit_card->ID);

			$data = array();

			$total_maximum_marks = 0;
			$total_obtained_marks = 0;

			foreach ($exam_papers as $key => $exam_paper) {
				$results_data = array();

				if ($admit_card && isset($exam_results[$exam_paper->ID])) {
					$exam_result = $exam_results[$exam_paper->ID];
					$obtained_marks = $exam_result->obtained_marks;
				} else {
					$obtained_marks = '';
				}

				$percentage = WLSM_Config::sanitize_percentage($exam_paper->maximum_marks, WLSM_Config::sanitize_marks($obtained_marks));

				$total_maximum_marks += $exam_paper->maximum_marks;
				$total_obtained_marks += WLSM_Config::sanitize_marks($obtained_marks);

				$results_data['paper_code'] = esc_html($exam_paper->paper_code);
				$results_data['subject_name'] = esc_html(stripcslashes($exam_paper->subject_label));
				$results_data['subject_type'] = esc_html(WLSM_Helper::get_subject_type_text($exam_paper->subject_type));
				$results_data['maximum_marks'] = esc_html($exam_paper->maximum_marks);
				$results_data['obtained_marks'] = esc_html($obtained_marks);

				if ($show_marks_grades) {
					$results_data['grade'] = esc_html(WLSM_Helper::calculate_grade($marks_grades, $percentage));
				}

				array_push($data, $results_data);
			}

			$total_percentage = WLSM_Config::sanitize_percentage($total_maximum_marks, $total_obtained_marks);

			$success = true;
			$message = esc_html__('Exam result retrieved successfully.', 'school-management');

			$response_data['result'] = array(
				'title' => esc_html(WLSM_M_Staff_Examination::get_exam_label_text($exam_title)),
				'start_date' => esc_html(WLSM_Config::get_date_text($start_date)),
				'end_date' => esc_html(WLSM_Config::get_date_text($end_date)),
				'student_name' => esc_html(WLSM_M_Staff_Class::get_name_text($admit_card->name)),
				'enrollment_number' => esc_html(WLSM_M_Staff_Class::get_roll_no_text($admit_card->enrollment_number)),
				'session' => esc_html(WLSM_M_Session::get_label_text($admit_card->session_label)),
				'class' => esc_html(WLSM_M_Class::get_label_text($admit_card->class_label)),
				'section' => esc_html(WLSM_M_Class::get_label_text($admit_card->section_label)),
				'roll_number' => esc_html(WLSM_M_Staff_Class::get_roll_no_text($admit_card->roll_number)),
				'show_marks_grades' => (bool) $show_marks_grades,
				'show_overall_grade' => (bool) $enable_overall_grade,
				'data' => $data,
				'total_maximum_marks' => $total_maximum_marks,
				'total_obtained_marks' => $total_obtained_marks,
				'percentage_value' => esc_html($total_percentage),
				'percentage_text' => esc_html(WLSM_Config::get_percentage_text($total_maximum_marks, $total_obtained_marks)),
			);

			if ($show_marks_grades && $enable_overall_grade) {
				$response_data['result']['overall_grade'] = esc_html(WLSM_Helper::calculate_grade($marks_grades, $total_percentage));
			}

			$response_data['result']['student_rank'] = esc_html($student_rank);

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Overall result.
	public static function overall_result($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);
			$session_label = $student->session_label;


			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			// Checks if student exists.
			$student = WLSM_M_Staff_General::fetch_student($school_id, $session_id, $student_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$admit_cards = WLSM_M_Staff_Examination::get_student_exam_results_assessment($school_id, $student_id);

			$results_data = array();

			$overall_maximum_marks = 0;
			$overall_obtained_marks = 0;
			foreach ($admit_cards as $admit_card) {
				$exam_id = $admit_card->exam_id;
				$exam_title = $admit_card->exam_title;
				$start_date = $admit_card->start_date;
				$end_date = $admit_card->end_date;
				$admit_card_id = $admit_card->ID;

				$exam_papers = WLSM_M_Staff_Examination::get_exam_papers_by_admit_card($school_id, $admit_card_id);
				$exam_results = WLSM_M_Staff_Examination::get_exam_results_by_admit_card($school_id, $admit_card_id);

				$total_maximum_marks = 0;
				$total_obtained_marks = 0;

				foreach ($exam_papers as $key => $exam_paper) {
					if ($admit_card && isset($exam_results[$exam_paper->ID])) {
						$exam_result = $exam_results[$exam_paper->ID];
						$obtained_marks = $exam_result->obtained_marks;
					} else {
						$obtained_marks = '';
					}

					$percentage = WLSM_Config::sanitize_percentage($exam_paper->maximum_marks, WLSM_Config::sanitize_marks($obtained_marks));

					$total_maximum_marks += $exam_paper->maximum_marks;
					$total_obtained_marks += WLSM_Config::sanitize_marks($obtained_marks);
				}

				$total_percentage = WLSM_Config::sanitize_percentage($total_maximum_marks, $total_obtained_marks);

				$overall_maximum_marks += $total_maximum_marks;
				$overall_obtained_marks += WLSM_Config::sanitize_marks($total_obtained_marks);

				$results_data[] = array(
					'id' => $admit_card->ID,
					'title' => esc_html(WLSM_M_Staff_Examination::get_exam_label_text($exam_title)),
					'exam_date' => esc_html(WLSM_Config::get_date_text($start_date)),
					'maximum_marks' => esc_html($total_maximum_marks),
					'obtained_marks' => esc_html($total_obtained_marks),
					'percentage_value' => esc_html(WLSM_Config::sanitize_percentage($total_maximum_marks, $total_obtained_marks)),
					'percentage_text' => esc_html(WLSM_Config::get_percentage_text($total_maximum_marks, $total_obtained_marks)),
				);
			}

			$success = true;
			$message = esc_html__('Overall result retrieved successfully.', 'school-management');

			$response_data['result'] = array(
				'student_name' => esc_html(WLSM_M_Staff_Class::get_name_text($student->student_name)),
				'enrollment_number' => esc_html($student->enrollment_number),
				'session' => esc_html(WLSM_M_Session::get_label_text($session_label)),
				'class' => esc_html(WLSM_M_Class::get_label_text($student->class_label)),
				'section' => esc_html(WLSM_M_Class::get_label_text($student->section_label)),
				'roll_number' => esc_html(WLSM_M_Staff_Class::get_roll_no_text($student->roll_number)),
				'phone' => esc_html(WLSM_M_Staff_Class::get_phone_text($student->phone)),
				'father_name' => esc_html(WLSM_M_Staff_Class::get_name_text($student->father_name)),
				'father_phone' => esc_html(WLSM_M_Staff_Class::get_phone_text($student->father_phone)),
				'data' => $results_data,
				'overall_maximum_marks' => esc_html($overall_maximum_marks),
				'overall_obtained_marks' => esc_html($overall_obtained_marks),
				'overall_percentage_value' => esc_html(WLSM_Config::sanitize_percentage($overall_maximum_marks, $overall_obtained_marks)),
				'overall_percentage_text' => esc_html(WLSM_Config::get_percentage_text($overall_maximum_marks, $overall_obtained_marks)),
			);

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Leave requests.
	public static function student_leave_requests($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$params = $request->get_params();

			// Query.
			$leaves_query = WLSM_M::leaves_query();

			// Total.
			$leaves_total = $wpdb->get_var($wpdb->prepare("SELECT COUNT(1) FROM ({$leaves_query}) AS combined_table", $school_id, $session_id, $student_id));

			// Current page and per page.
			$leaves_page = isset($params['leaves_page']) ? absint($params['leaves_page']) : 1;
			$leaves_per_page = isset($params['leaves_per_page']) ? absint($params['leaves_per_page']) : WLSM_M::leaves_per_page();

			// Page offset.
			$leaves_page_offset = ($leaves_page * $leaves_per_page) - $leaves_per_page;

			// Paginated data.
			$leaves = $wpdb->get_results($wpdb->prepare($leaves_query . ' ORDER BY lv.ID DESC LIMIT %d, %d', $school_id, $session_id, $student_id, $leaves_page_offset, $leaves_per_page));

			// Paginated response.
			$leaves_data = array();
			$leaves_pagination = array(
				'current_page' => $leaves_page,
				'per_page' => $leaves_per_page,
			);

			// Format response.
			if (count($leaves)) {
				foreach ($leaves as $key => $leave) {
					if ($leave->end_date) {
						$leave_date = sprintf(
							/* translators: 1: leave start date, 2: leave end date */
							esc_html__('%1$s to %2$s', 'school-management'),
							esc_html(WLSM_Config::get_date_text($leave->start_date)),
							esc_html(WLSM_Config::get_date_text($leave->end_date))
						);
					} else {
						$leave_date = esc_html(WLSM_Config::get_date_text($leave->start_date));
					}

					$leaves_data[] = array(
						'id' => $leave->ID,
						'reason' => esc_html(WLSM_Config::limit_string(WLSM_M_Staff_Class::get_name_text($leave->description))),
						'leave_date' => $leave_date,
						'approval' => esc_html(WLSM_M_Staff_Class::get_leave_approval_text($leave->is_approved))
					);
				}

				$leaves_pagination['total_pages'] = ceil($leaves_total / $leaves_per_page);
				$leaves_pagination['total_records'] = $leaves_total;
			}

			$success = true;
			$message = esc_html__('Leave requests retrieved successfully.', 'school-management');

			$response_data['leaves'] = array(
				'data' => $leaves_data,
				'pagination' => $leaves_pagination
			);

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Certificates.
	public static function student_certificates($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$params = $request->get_params();

			// Query.
			$certificates_query = WLSM_M::certificates_query();

			// Total.
			$certificates_total = $wpdb->get_var($wpdb->prepare("SELECT COUNT(1) FROM ({$certificates_query}) AS combined_table", $school_id, $session_id, $student_id));

			// Current page and per page.
			$certificates_page = isset($params['certificates_page']) ? absint($params['certificates_page']) : 1;
			$certificates_per_page = isset($params['certificates_per_page']) ? absint($params['certificates_per_page']) : WLSM_M::certificates_per_page();

			// Page offset.
			$certificates_page_offset = ($certificates_page * $certificates_per_page) - $certificates_per_page;

			// Paginated data.
			$certificates = $wpdb->get_results($wpdb->prepare($certificates_query . ' ORDER BY cfsr.ID DESC LIMIT %d, %d', $school_id, $session_id, $student_id, $certificates_page_offset, $certificates_per_page));

			// Paginated response.
			$certificates_data = array();
			$certificates_pagination = array(
				'current_page' 	=> $certificates_page,
				'per_page' 		=> $certificates_per_page,
			);

			// Format response.
			if (count($certificates)) {
				foreach ($certificates as $key => $certificate) {
					$certificates_data[] = array(
						'id' 				=> isset($certificate->certificate_id) ? absint($certificate->certificate_id) : 0,
						'label' 			=> isset($certificate->label) ? WLSM_M_Staff_Class::get_certificate_label_text($certificate->label) : '',
						'certificate_number' => isset($certificate->certificate_number) ? WLSM_M_Staff_Class::get_address_text($certificate->certificate_number) : '',
						'date' 				=> isset($certificate->date_issued) ? WLSM_Config::get_date_text($certificate->date_issued) : '',
					);
				}

				$certificates_pagination['total_pages'] = ceil($certificates_total / $certificates_per_page);
				$certificates_pagination['total_records'] = $certificates_total;
			}

			$success = true;
			$message = esc_html__('Certificates retrieved successfully.', 'school-management');

			$response_data['certificates'] = array(
				'certificates_data' => $certificates_data,
				'pagination' 		=> $certificates_pagination
			);

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	public static function student_certificate_generate($request)
	{
		$user_id = get_current_user_id();

		require_once WLSM_PLUGIN_DIR_PATH . 'includes/vendor/autoload.php';
		require_once WLSM_PLUGIN_DIR_PATH . 'includes/helpers/staff/WLSM_M_Staff_General.php';

		global $wpdb;

		$student = WLSM_M_User::user_is_student($user_id);

		if (!$student) {
			throw new Exception(esc_html__('Student not found.', 'school-management'));
		}

		$student_id = $student->ID;
		$school_id  = $student->school_id;
		$session_id = $student->session_id;

		$params = $request->get_params();
		$certificate_id = isset($params['certificate_id']) ? absint($params['certificate_id']) : 0;

		$certificate_student_id = $wpdb->get_var(
			$wpdb->prepare(
				'SELECT cfsr.ID
				FROM ' . WLSM_CERTIFICATE_STUDENT . ' as cfsr
				JOIN ' . WLSM_CERTIFICATES . ' as cf ON cf.ID = cfsr.certificate_id
				WHERE cfsr.student_record_id = %d AND cf.ID = %d
				ORDER BY cfsr.ID DESC',
				$student_id,
				$certificate_id
			)
		);

		$certificate_student = WLSM_M_Staff_General::fetch_certificate_distributed($school_id, $session_id, $certificate_student_id);

		if (!$certificate_student) {
			throw new Exception(esc_html__('Student not found.', 'school-management'));
		}

		require_once WLSM_PLUGIN_DIR_PATH . 'includes/partials/certificate_result.php';
		require WLSM_PLUGIN_DIR_PATH . 'includes/partials/certificate_student.php';

		$student = WLSM_M_Staff_General::fetch_student($school_id, $session_id, $student_id);

		$orientation = $fields['orientation'] ?? 'portrait';

		if (empty($image_url)) {
			$image_url = WLSM_PLUGIN_URL . 'assets/images/certificate.png';
		}

		$field_outputs = [];

		if ($school_id) {
			$school         = WLSM_M_School::fetch_school($school_id);
			$school_name    = esc_html(WLSM_M_School::get_label_text($school->label));
			$school_phone   = esc_html(WLSM_M_School::get_phone_text($school->phone));
			$school_email   = esc_html(WLSM_M_School::get_email_text($school->email));
			$school_address = esc_html(WLSM_M_School::get_address_text($school->address));

			$settings_general = WLSM_M_Setting::get_settings_general($school_id);
			$school_logo      = $settings_general['school_logo'];
			if (!empty($school_logo)) {
				$school_logo_url = esc_url(wp_get_attachment_url($school_logo));
			}
		}

		foreach ($fields as $field_key => $field_value) {
			if ($field_key === 'orientation') continue;

			if (isset($student)) {
				if ('name' === $field_key) {
					$field_outputs[$field_key] = WLSM_M_Staff_Class::get_name_text($student->student_name);
				} elseif ('certificate-number' === $field_key) {
					$field_outputs[$field_key] = $certificate_number;
				} elseif ('certificate-title' === $field_key) {
					$field_outputs[$field_key] = $certificate_title;
				} elseif ('serial-number' === $field_key) {
					$field_outputs[$field_key] = isset($student->serial_number) ? $student->serial_number : '';
				} elseif ('photo' === $field_key) {
					if (!empty($student->photo_id)) {
						$field_outputs[$field_key] = wp_get_attachment_url($student->photo_id);
					} else {
						$field_outputs[$field_key] = '';
					}
				} elseif ('qcode' === $field_key) {
					if (!empty($certificate_number)) {
						$settings_url            = WLSM_M_Setting::get_settings_certificate_qcode_url($school_id);
						$school_certificate_url    = $settings_url['certificate_url'];
						$qr_code = $school_certificate_url . '?id=' . $certificate_number;
						$field_outputs[$field_key] 	  = esc_url('https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=' . urlencode($qr_code));
					} else {
						$field_outputs[$field_key] = '';
					}
				} elseif ('enrollment-number' === $field_key) {
					$field_outputs[$field_key] = $student->enrollment_number;
				} elseif ('admission-number' === $field_key) {
					$field_outputs[$field_key] = WLSM_M_Staff_Class::get_admission_no_text($student->admission_number);
				} elseif ('roll-number' === $field_key) {
					$field_outputs[$field_key] = WLSM_M_Staff_Class::get_roll_no_text($student->roll_number);
				} elseif ('session-label' === $field_key) {
					$field_outputs[$field_key] = WLSM_M_Session::get_label_text($session_label);
				} elseif ('session-start-date' === $field_key) {
					$field_outputs[$field_key] = WLSM_Config::get_date_text($session_start_date);
				} elseif ('session-end-date' === $field_key) {
					$field_outputs[$field_key] = WLSM_Config::get_date_text($session_end_date);
				} elseif ('session-start-year' === $field_key) {
					$field_outputs[$field_key] = DateTime::createFromFormat('Y-m-d', $session_start_date);
					$field_outputs[$field_key] = $field_outputs[$field_key]->format('Y');
				} elseif ('session-end-year' === $field_key) {
					$field_outputs[$field_key] = DateTime::createFromFormat('Y-m-d', $session_end_date);
					$field_outputs[$field_key] = $field_outputs[$field_key]->format('Y');
				} elseif ('class' === $field_key) {
					$field_outputs[$field_key] = WLSM_M_Class::get_label_text($student->class_label);
				} elseif ('section' === $field_key) {
					$field_outputs[$field_key] = WLSM_M_Class::get_label_text($student->section_label);
				} elseif ('dob' === $field_key) {
					$field_outputs[$field_key] = WLSM_Config::get_date_text($student->dob);
				} elseif ('caste' === $field_key) {
					$field_outputs[$field_key] = stripcslashes($student->caste);
				} elseif ('blood-group' === $field_key) {
					$field_outputs[$field_key] = stripcslashes($student->blood_group);
				} elseif ('father-name' === $field_key) {
					$field_outputs[$field_key] = stripcslashes($student->father_name);
				} elseif ('mother-name' === $field_key) {
					$field_outputs[$field_key] = stripcslashes($student->mother_name);
				} elseif ('class-teacher' === $field_key) {
					$section_id = $student->section_id;
					$teacher = WLSM_M_Staff_Class::get_section_teachers($school_id, $section_id, true);
					if ($teacher) {
						$teacher_name = $teacher->name;
					} else {
						$teacher_name = '';
					}
					$field_outputs[$field_key] = stripcslashes($teacher_name);
				} elseif ('school-name' === $field_key) {
					$field_outputs[$field_key] = $school_name;
				} elseif ('school-phone' === $field_key) {
					$field_outputs[$field_key] = $school_phone;
				} elseif ('school-email' === $field_key) {
					$field_outputs[$field_key] = $school_email;
				} elseif ('school-address' === $field_key) {
					$field_outputs[$field_key] = $school_address;
				} elseif ('school-logo' === $field_key) {
					$field_outputs[$field_key] = $school_logo_url;
				} elseif ('total-max-mark' === $field_key) {
					$field_outputs[$field_key] = isset($total_maximum_marks) ? $total_maximum_marks : '';
				} elseif ('total-obtained-mark' === $field_key) {
					$field_outputs[$field_key] = isset($total_obtained_marks) ? $total_obtained_marks : '';
				} elseif ('rank' === $field_key) {
					$field_outputs[$field_key] = isset($student_rank) ? $student_rank : '';
				} elseif ('percentage' === $field_key) {
					$field_outputs[$field_key] = isset($student_percentage) ? $student_percentage : '';
				} elseif ('pass_out_year' === $field_key) {
					$field_outputs[$field_key] = $student->pass_out_year;
				} elseif ('school_class' === $field_key) {
					$field_outputs[$field_key] = $student->school_class;
				} elseif ('school_address' === $field_key) {
					$field_outputs[$field_key] = $student->school_address;
				} elseif ('school_name' === $field_key) {
					$field_outputs[$field_key] = $student->school_name;
				} elseif ('birth_place' === $field_key) {
					$field_outputs[$field_key] = $student->birth_place;
				} elseif ('mother_tongue' === $field_key) {
					$field_outputs[$field_key] = $student->mother_tongue;
				} elseif ('dob_in_words' === $field_key) {
					$field_outputs[$field_key] = $student->dob_in_words;
				} elseif ('religion' === $field_key) {
					$field_outputs[$field_key] = $student->religion;
				} else {
					$field_outputs[$field_key] = '';
				}
			} else {
				$field_outputs[$field_key] = WLSM_Helper::get_certificate_place_holder($field_key, $school_id);
			}
		}

		$pt_to_mm = 0.3528;
		$field_positions = [];

		foreach ($fields as $field_key => $field_value) {
			if ($field_key === 'orientation') continue;
			if (empty($field_value['enable'])) continue;

			$left = 0;
			$top = 0;
			$width = 0;
			$height = 0;
			$font_size = '14pt';

			if (!empty($field_value['props'])) {
				foreach ($field_value['props'] as $prop_key => $prop) {

					$val  = isset($prop['value']) ? floatval($prop['value']) : 0;
					$unit = $prop['unit'] ?? 'pt';
					$val_mm = ($unit === 'pt') ? $val * $pt_to_mm : $val;

					switch ($prop_key) {
						case 'left': $left = $val_mm; break;
						case 'top': $top = $val_mm; break;
						case 'width': $width = $val_mm; break;
						case 'height': $height = $val_mm; break;
						case 'font-size': $font_size = $val . $unit; break;
					}
				}
			}

			$field_positions[$field_key] = compact('left', 'top', 'width', 'height', 'font_size');
		}

		try {
			$mpdf = new \Mpdf\Mpdf([
				'format' => 'A4',
				'orientation' => ($orientation === 'landscape') ? 'L' : 'P',
				'margin_top' => 0,
				'margin_bottom' => 0,
				'margin_left' => 0,
				'margin_right' => 0,
			]);

			$mpdf->AddPage();

			$page_width = ($orientation === 'landscape') ? 297 : 210;
			$page_height = ($orientation === 'landscape') ? 210 : 297;

			$html = '
				<div style="position:absolute; top:0; left:0; width:' . $page_width . 'mm; height:' . $page_height . 'mm;">
					<img src="' . $image_url . '" style="width:' . $page_width . 'mm; height:' . $page_height . 'mm;">
				</div>
			';

			$mpdf->WriteHTML($html);

			foreach ($field_positions as $key => $pos) {

				if (empty($field_outputs[$key])) continue;

				$value = $field_outputs[$key];

				if ($key === 'photo' && filter_var($value, FILTER_VALIDATE_URL)) {
					$mpdf->Image(
						$value,
						$pos['left'],
						$pos['top'],
						$pos['width'] ?: 30,
						$pos['height'] ?: 40
					);
					continue;
				}

				if ($key === 'school-logo' && filter_var($school_logo_url, FILTER_VALIDATE_URL)) {
					$mpdf->Image(
						$value,
						$pos['left'],
						$pos['top'],
						$pos['width'] ?: 30,
						$pos['height'] ?: 40
					);
					continue;
				}

				// if ($key === 'qcode' && !empty($value)) {
					// $html = "<img src='{$value}' style='width:{$pos['width']}mm; height:{$pos['height']}mm;' />";

					// $mpdf->WriteFixedPosHTML(
					// 	$html,
					// 	$pos['left'],
					// 	$pos['top'],
					// 	$pos['width'] ?: 30,
					// 	$pos['height'] ?: 30
					// );

					// continue;
				// }

				$html = "<div style='font-size:{$pos['font_size']};'>{$value}</div>";

				$mpdf->WriteFixedPosHTML(
					$html,
					$pos['left'],
					$pos['top'],
					$pos['width'] ?: 100,
					$pos['height'] ?: 20
				);
			}

			// Save PDF
			$upload_dir = wp_upload_dir();
			$dir = $upload_dir['basedir'] . '/wlsm/certificates';

			if (!file_exists($dir)) wp_mkdir_p($dir);

			$file = 'certificate_' . time() . '.pdf';
			$path = $dir . '/' . $file;
			$url  = $upload_dir['baseurl'] . '/wlsm/certificates/' . $file;

			$mpdf->Output($path, 'F');

			wp_schedule_single_event(time() + 30, 'wlsm_delete_student_certificate_generated', array($file));

			return new WP_REST_Response([
				'success' => true,
				'url' => $url
				// 'file_path' => $file_path
			], 200);

		} catch (Exception $e) {
			return new WP_REST_Response([
				'success' => false,
				'message' => $e->getMessage()
			], 500);
		}
	}

	// Student - Student Subjects.
	public static function student_subjects($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$params = $request->get_params();

			$subjects   = WLSM_M_Staff_General::fetch_subjects($student->ID);

			$subject_data = array();

			if (count($subjects)) {
				foreach ($subjects as $subject) {
					$subject_data[] = array(
						'id' 		=> isset($subject->ID) ? absint($subject->ID) : 0,
						'label' 	=> isset($subject->label) ? WLSM_M_Staff_Class::get_label_text($subject->label) : '',
					);
				}
			}

			$success = true;
			$message = esc_html__('Student subjects retrieved successfully.', 'school-management');

			$response_data['subject_data'] = $subject_data;

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Tickets.
	public static function student_tickets($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id = $student->class_school_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$params = $request->get_params();

			// Query.
			$tickets_query = WLSM_M::tickets_query();

			// Total.
			$tickets_total = $wpdb->get_var($wpdb->prepare("SELECT COUNT(1) FROM ({$tickets_query}) AS combined_table", $school_id, $session_id, $student_id));

			// Current page and per page.
			$tickets_page = isset($params['tickets_page']) ? absint($params['tickets_page']) : 1;
			$tickets_per_page = isset($params['tickets_per_page']) ? absint($params['tickets_per_page']) : WLSM_M::tickets_per_page();

			// Page offset.
			$tickets_page_offset = ($tickets_page * $tickets_per_page) - $tickets_per_page;

			// Paginated data.
			$tickets = $wpdb->get_results($wpdb->prepare($tickets_query . ' ORDER BY t.ID DESC LIMIT %d, %d', $school_id, $session_id, $student_id, $tickets_page_offset, $tickets_per_page));

			// Paginated response.
			$tickets_data = array();
			$tickets_pagination = array(
				'current_page' 	=> $tickets_page,
				'per_page' 		=> $tickets_per_page,
			);

			// Format response.
			if (count($tickets)) {
				foreach ($tickets as $key => $ticket) {
					$tickets_data[] = array(
						'id' 			=> isset($ticket->ID) ? absint($ticket->ID) : 0,
						'title' 		=> isset($ticket->title) ? WLSM_M_Staff_Class::get_label_text($ticket->title) : '',
						'description' 	=> isset($ticket->description) ? WLSM_M_Staff_Class::get_address_text($ticket->description) : '',
						'status' 		=> isset($ticket->status) ? WLSM_M_Staff_Class::get_label_text($ticket->status) : '',
						'priority' 		=> isset($ticket->priority) ? WLSM_M_Staff_Class::get_label_text($ticket->priority) : '',
						'assigned_to' 	=> isset($ticket->assigned_to) ? WLSM_M_Staff_Class::get_name_text($ticket->assigned_to) : '',
						'created_at' 	=> isset($ticket->created_at) ? WLSM_Config::get_date_text($ticket->created_at) : '',
					);
				}

				$tickets_pagination['total_pages'] = ceil($tickets_total / $tickets_per_page);
				$tickets_pagination['total_records'] = $tickets_total;
			}

			$success = true;
			$message = esc_html__('Tickets retrieved successfully.', 'school-management');

			$response_data['tickets'] = array(
				'tickets_data' 		=> $tickets_data,
				'pagination' 		=> $tickets_pagination
			);

			WLSM_Helper::check_buffer();
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Submit ticket.
	public static function student_submit_ticket($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$wpdb->query('BEGIN;');

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id 	= $student->class_school_id;
			$class_id 			= $student->class_id;
			$section_id 		= $student->section_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$params 		= $request->get_params();
			$title 			= isset($params['title']) ? sanitize_text_field($params['title']) : '';
			$priority 		= isset($params['priority']) ? sanitize_text_field($params['priority']) : 'low';
			$subject_id		= isset($params['subject_id']) ? absint($params['subject_id']) : '';
			$description 	= isset($params['description']) ? sanitize_text_field($params['description']) : '';

			if (empty($title)) {
				throw new Exception(esc_html__('Please specify title.', 'school-management'));
			}

			if (!empty($subject_id)) {
				$subject = WLSM_M_Staff_Class::get_subject($school_id, $subject_id);
				if (empty($subject)) {
					throw new Exception(__('Subject not found.', 'school-management'));
				}
			}

			if (empty($description)) {
				throw new Exception(esc_html__('Please specify description.', 'school-management'));
			}

			$status 	= 'open';

			// Student ticket data.
			$data = array(
				'title' 		=> $title,
				'description' 	=> $description,
				'priority' 		=> $priority,
				'status' 		=> $status,
				'school_id' 	=> $school_id,
				'student_id' 	=> $student_id,
				'class_id' 		=> $class_id,
				'section_id' 	=> $section_id,
				'subject_id' 	=> $subject_id,
			);

			$data['created_at'] = current_time('Y-m-d H:i:s');

			$success = $wpdb->insert(WLSM_TICKETS, $data);
			$ticket_id = $wpdb->insert_id;

			$changed_by = get_current_user_id();
			$success = WLSM_P_Student::add_ticket_history($ticket_id, $status, $description, $changed_by);

			WLSM_Helper::check_buffer();

			if (false === $success) {
				throw new Exception($wpdb->last_error);
			}

			$wpdb->query('COMMIT;');

			$success = true;
			$message = esc_html__('Ticket submitted successfully.', 'school-management');

			$response_data['ticket'] = array(
				'id' 			=> $ticket_id,
				'title' 		=> esc_html(WLSM_M_Staff_Class::get_label_text($title)),
				'priority' 		=> esc_html(WLSM_M_Staff_Class::get_label_text($priority)),
				'subject_id' 	=> esc_html(absint($subject_id)),
				'description'	=> esc_html(WLSM_Config::limit_string(WLSM_M_Staff_Class::get_address_text($description))),
			);
		} catch (Exception $exception) {
			$wpdb->query('ROLLBACK;');
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Student - Ticket history.
	public static function student_ticket_history($request)
	{
		$user_id = get_current_user_id();

		try {
			global $wpdb;

			$wpdb->query('BEGIN;');

			$student = WLSM_M_User::user_is_student($user_id);

			if (!$student) {
				throw new Exception(esc_html__('Student not found.', 'school-management'));
			}

			$response_data = array();

			$student_id = $student->ID;
			$school_id = $student->school_id;
			$session_id = $student->session_id;

			$class_school_id 	= $student->class_school_id;
			$class_id 			= $student->class_id;
			$section_id 		= $student->section_id;

			$common_details = self::student_common_details($student);
			$response_data['student'] = $common_details;

			$params 		= $request->get_params();
			$id 			= isset($params['id']) ? absint($params['id']) : '';

