				'status' 		=> isset($ticket->status) ? WLSM_M_Staff_Class::get_address_text($ticket->status) : '',
				'priority' 		=> isset($ticket->priority) ? WLSM_M_Staff_Class::get_address_text($ticket->priority) : '',
				'assigned_to' 	=> isset($ticket->assigned_to) ? WLSM_M_Staff_Class::get_address_text($ticket->assigned_to) : '',
