						'status' 			=> isset($th->status) ? WLSM_M_Staff_Class::get_address_text($th->status) : '',
						'comment' 			=> isset($th->comment) ? WLSM_M_Staff_Class::get_address_text($th->comment) : '',
						'changed_by_name' 	=> isset($th->changed_by_name) ? WLSM_M_Staff_Class::get_name_text($th->changed_by_name) : '',
					);
