	// Staff - Student list.
	public static function student_list($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 	= isset($staff->school_id) ? absint($staff->school_id) : 0;
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 	= $request->get_params();

		$class_id 	= isset($params['class_id']) ? absint($params['class_id']) : 0;
		$section_id = isset($params['section_id']) ? absint($params['section_id']) : 0;
		$subject_id = isset($params['subject_id']) ? absint($params['subject_id']) : 0;

		try {
			global $wpdb;

			$current_session_id = get_option('wlsm_current_session');
			$session = WLSM_M_Session::get_session($current_session_id);
			if (!$session) {
				throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
			}
			$session_id = isset($session->ID) ? absint($session->ID) : 0;

			if (empty($class_id)) {
				throw new Exception(esc_html__('Please select a class.', 'school-management'));
			}

			if (! empty($class_id) && empty($section_id)) {
				$students = WLSM_M_Staff_Class::get_class_students($school_id, $session_id, $class_id, true);
			} else if (! empty($class_id) && ! empty($section_id) && empty($subject_id)) {
				$students = WLSM_M_Staff_Class::get_section_students($school_id, $session_id, $section_id, true);
			} else {
				$students = WLSM_M_Staff_Class::get_students_by_subject($school_id, $session_id, $section_id, $subject_id);
			}

			if (!$students) {
				throw new Exception(esc_html__('No students found.', 'school-management'));
			}

			foreach ($students as $student) {
				$student_data[] = array(
					'ID' 				=> isset($student->ID) ? absint($student->ID) : 0,
					'name' 				=> isset($student->name) ? WLSM_M_Staff_Class::get_label_text($student->name) : '',
					'enrollment_number' => isset($student->enrollment_number) ? WLSM_M_Staff_Class::get_roll_no_text($student->enrollment_number) : '',
					'roll_number' 		=> isset($student->roll_number) ? WLSM_M_Staff_Class::get_roll_no_text($student->roll_number) : '',
					'phone' 			=> isset($student->phone) ? WLSM_M_Staff_Class::get_phone_text($student->phone) : '',
					'father_name' 		=> isset($student->father_name) ? WLSM_M_Staff_Class::get_label_text($student->father_name) : '',
					'father_phone' 		=> isset($student->father_phone) ? WLSM_M_Staff_Class::get_phone_text($student->father_phone) : '',
					'section_label' 	=> isset($student->section_label) ? WLSM_M_Staff_Class::get_label_text($student->section_label) : '',
				);
			}

			$response_data = array();
			$response_data['students'] = $student_data;

			$success = true;
			$message = esc_html__('Students Retrieved Successfully.', 'school-management');
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Class Subject list.
	public static function class_subject_list($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$user_can_manage_subjects 	= WLSM_M_Role::can('assigned_subjects');
				$staff_permissions 			= false;
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			global $wpdb;

			$params = $request->get_params();
			$class_id = isset($params['class_id']) ? absint($params['class_id']) : 0;

			if (empty($class_id)) {
				throw new Exception(esc_html__('Please select a class.', 'school-management'));
			}

			if ($staff_permissions || ! $user_can_manage_subjects) {
				$subjects = WLSM_M_Staff_class::get_class_subjects($school_id, $class_id);
			} else {
				$admin = WLSM_M_Role::get_user_admin($school_id, $user_id);
				if ($admin) {
					$subjects = WLSM_Helper::getAssignedSubjects($admin->ID);
					if (!empty($subjects) && isset($subjects[0]->ID) && $subjects[0]->ID === '') {
						array_shift($subjects);
					}
				}
			}

			if (!$subjects) {
				throw new Exception(esc_html__('No subjects found.', 'school-management'));
			}

			$response_data = array();

			foreach ($subjects as $subject) {
				$subject_name = isset($subject->label) ? $subject->label : $subject->subject_name;
				$subject_name = isset($subject->subject_name) ? $subject->subject_name : $subject->label;

				$subeject_data[] = array(
					'ID'    => $subject->ID,
					'label' => isset($subject_name) ? WLSM_M_Staff_Class::get_label_text($subject_name) : '',
				);
			}

			$response_data['subjects'] = $subeject_data;

			$success = true;
			$message = esc_html__('Subjects Retrieved Successfully.', 'school-management');
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Subject Teacher List.
	public static function subject_teacher_list($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 	= $request->get_params();
		$subject_id = isset($params['subject_id']) ? absint($params['subject_id']) : 0;

		try {
			global $wpdb;

			$response_data = array();

			$subject = WLSM_M_Staff_Class::get_subject($school_id, $subject_id);
			if (empty($subject)) {
				throw new Exception(esc_html__('Subject not found.', 'school-management'));
			}

			$subject_teachers = WLSM_M_Staff_Class::fetch_subject_admins($school_id, $subject_id);
			if (empty($subject_teachers)) {
				throw new Exception(esc_html__('Subject Teachers not found.', 'school-management'));
			}

			if ($subject_teachers) {
				foreach ($subject_teachers as $subject_teacher) {
					global $wpdb;
					$data[] = array(
						'ID' 	=> isset($subject_teacher->ID) ? WLSM_M_Staff_Class::get_label_text($subject_teacher->ID) : '',
						'name' 	=> isset($subject_teacher->name) ? WLSM_M_Staff_Class::get_label_text($subject_teacher->name) : '',
					);
				}
				$response_data['teachers'] = $data;
			}

			$success = true;
			$message = esc_html__('Subject Teachers Retrieved Successfully.', 'school-management');

			if (false === $success) {
				throw new Exception($wpdb->last_error);
			}

			$wpdb->query('COMMIT;');
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - View Classes and Sections.
	public static function view_classes_and_sections($request)
	{

		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section 	= false;

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('manage_classes', $permissions);

				$manage_class = WLSM_M_Role::can('assigned_class');
				if ($manage_class) {
					$restrict_to_section = $section_id;
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {

			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = absint($session->ID);

				$classes_query 	= WLSM_M_Staff_Class::fetch_classes_query($school_id, $session_id, $restrict_to_section);
				$group_by 		= ' ' . WLSM_M_Staff_Class::fetch_classes_query_group_by();
				$classes_query  .= $group_by;
				$classes 		= $wpdb->get_results($classes_query);

				if (empty($classes)) {
					throw new Exception(esc_html__('Classes not found.', 'school-management'));
				}

				foreach ($classes as $class) {
					$student_counts = array(
						'Male' 		=> absint($class->male_students_count),
						'Female' 	=> absint($class->female_students_count),
						'Total'		=> absint($class->students_count)
					);

					$class_teachers = array();

					// Get class teachers.
					$teachers = WLSM_M_Staff_Class::get_class_teachers($school_id, $class->ID);

					foreach ($teachers as $teacher) {
						$class_teacher = array(
							'ID' 			=> isset($teacher->ID) ? absint($teacher->ID) : 0,
							'name' 			=> isset($teacher->name) ? WLSM_M_Staff_Class::get_name_text($teacher->name) : '',
							'section_label'	=> isset($teacher->section_label) ? WLSM_M_Staff_Class::get_section_label_text($teacher->section_label) : ''
						);
						$class_teachers[] = $class_teacher;
					}

					$data = array(
						'ID' 				=> isset($class->ID) ? absint($class->ID) : 0,
						'class_label' 		=> isset($class->label) ? WLSM_M_Staff_Class::get_label_text($class->label) : '',
						'no_of_sections' 	=> isset($class->sections_count) ? absint($class->sections_count) : 0,
						'no_of_students' 	=> $student_counts,
						'class_teacher' 	=> $class_teachers
					);
					$classes_array[] = $data;
				}
				$response_data['classes'] = $classes_array;

				$success = true;
				$message = esc_html__('Classes Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have manage classes & sections permission to view classes and sections.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - View Class Sections.
	public static function view_class_sections($request)
	{

		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section 	= false;

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('manage_classes', $permissions);

				$manage_class = WLSM_M_Role::can('assigned_class');
				if ($manage_class) {
					$restrict_to_section = $section_id;
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 	= $request->get_params();
		$class_id 	= isset($params['class_id']) ? $params['class_id'] : 0;

		if (empty($class_id)) {
			throw new Exception(esc_html__('Please select a class.', 'school-management'));
		}

		try {

			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = absint($session->ID);

				$class_school    = WLSM_M_Staff_Class::fetch_class( $school_id, $class_id );
				$class_school_id = isset($class_school->ID) ? absint($class_school->ID) : 0;

				$sections_query = WLSM_M_Staff_Class::fetch_sections_query($school_id, $session_id, $class_school_id);
				$group_by = ' ' . WLSM_M_Staff_Class::fetch_sections_query_group_by();
				$sections_query  .= $group_by;
				$sections 		= $wpdb->get_results($sections_query);

				if (empty($sections)) {
					throw new Exception(esc_html__('Sections not found.', 'school-management'));
				}

				foreach ($sections as $section) {
					$default_section_text = '';
					if ($section->ID !== $section->default_section_id) {
						$default_section_text = false;
					} else {
						$default_section_text = true;
					}

					$student_counts = array(
						'Male' 		=> absint($section->male_students_count),
						'Female' 	=> absint($section->female_students_count),
						'Total'		=> absint($section->students_count)
					);

					$class_teachers = array();

					// Get class teachers.
					$teachers = WLSM_M_Staff_Class::get_section_teachers($school_id, $section->ID);

					foreach ($teachers as $teacher) {
						$class_teacher = array(
							'ID' 			=> isset($teacher->ID) ? absint($teacher->ID) : 0,
							'name' 			=> isset($teacher->name) ? WLSM_M_Staff_Class::get_name_text($teacher->name) : ''
						);
						$class_teachers[] = $class_teacher;
					}

					$data = array(
						'ID' 				=> isset($section->ID) ? absint($section->ID) : 0,
						'section_label' 	=> isset($section->label) ? WLSM_M_Staff_Class::get_label_text($section->label) : '',
						'no_of_students' 	=> $student_counts,
						'class_teacher' 	=> $class_teachers,
						'is_default'        => $default_section_text
					);
					$class_sections[] = $data;
				}
				$response_data['class_sections'] = $class_sections;

				$success = true;
				$message = esc_html__('Class Sections Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have manage classes & sections permission to view class sections.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Add new section.
	public static function add_new_section($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('manage_classes', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 	= $request->get_params();
		$class_id 	= isset($params['class_id']) ? absint($params['class_id']) : 0;
		$label 		= isset($params['label']) ? sanitize_text_field($params['label']) : '';
		$is_default = isset($params['is_default']) ? (bool) $params['is_default'] : 0;

		try {

			if ($staff_permissions) {
				global $wpdb;

				if (empty($class_id)) {
					throw new Exception(esc_html__('Please select a class.', 'school-management'));
				}

				if (empty($label)) {
					throw new Exception(esc_html__('Please enter a section label.', 'school-management'));
				}

				if (strlen($label) > 191) {
					throw new Exception(esc_html__('Maximum length cannot exceed 191 characters.', 'school-management'));
				}

				// Checks if class exists in the school.
				$class_school = WLSM_M_Staff_Class::get_class($school_id, $class_id);

				if (!$class_school) {
					throw new Exception(esc_html__('Class not found.', 'school-management'));
				}

				$class_school_id = $class_school->ID;

				// Checks if section already exists in the class with this label.
				$section_exist = $wpdb->get_var($wpdb->prepare('SELECT COUNT(*) as count FROM ' . WLSM_SECTIONS . ' as se WHERE se.label = %s AND se.class_school_id = %d', $label, $class_school_id));

				if ($section_exist) {
					throw new Exception(esc_html__('Section already exists.', 'school-management'));
				}

				$wpdb->query('BEGIN;');

				// Data to insert.
				$data = array(
					'label'           => $label,
					'class_school_id' => $class_school_id,
					'created_at'      => current_time('Y-m-d H:i:s'),
				);

				$success = $wpdb->insert(WLSM_SECTIONS, $data);

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$section_id = $wpdb->insert_id;

				if ($is_default) {
					$success = $wpdb->update(
						WLSM_CLASS_SCHOOL,
						array('default_section_id' => $section_id, 'updated_at' => current_time('Y-m-d H:i:s')),
						array('ID' => $class_school_id)
					);

					WLSM_Helper::check_buffer();

					if (false === $success) {
						throw new Exception($wpdb->last_error);
					}
				}

				$wpdb->query('COMMIT;');

				$response_data = array(
					'section_id' => $section_id
				);

				$success = true;
				$message = esc_html__('Section Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have manage classes & sections permission to add new section.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (!empty($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Edit section.
	public static function edit_section($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('manage_classes', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$section_id 	= isset($params['section_id']) ? absint($params['section_id']) : 0;
		$class_id 		= isset($params['class_id']) ? absint($params['class_id']) : 0;
		$label 			= isset($params['label']) ? sanitize_text_field($params['label']) : '';
		$is_default 	= isset($params['is_default']) ? (bool) $params['is_default'] : 0;

		try {

			if ($staff_permissions) {
				global $wpdb;

				if (empty($section_id)) {
					throw new Exception(esc_html__('Please select a section.', 'school-management'));
				}

				if (empty($class_id)) {
					throw new Exception(esc_html__('Please select a class.', 'school-management'));
				}

				if (empty($label)) {
					throw new Exception(esc_html__('Please enter a section label.', 'school-management'));
				}

				if (strlen($label) > 191) {
					throw new Exception(esc_html__('Maximum length cannot exceed 191 characters.', 'school-management'));
				}

				// Checks if class exists in the school.
				$class_school = WLSM_M_Staff_Class::get_class($school_id, $class_id);

				if (!$class_school) {
					throw new Exception(esc_html__('Class not found.', 'school-management'));
				}

				$class_school_id = $class_school->ID;

				// Checks if section exists.
				$section = WLSM_M_Staff_Class::get_section($school_id, $section_id, $class_school_id);

				if (!$section) {
					throw new Exception(esc_html__('Section not found.', 'school-management'));
				}

				// Checks if section already exists in the class with this label.
				$section_exist = $wpdb->get_var($wpdb->prepare('SELECT COUNT(*) as count FROM ' . WLSM_SECTIONS . ' as se WHERE se.label = %s AND se.ID != %d AND se.class_school_id = %d', $label, $section_id, $class_school_id));

				if ($section_exist) {
					throw new Exception(esc_html__('Section already exists.', 'school-management'));
				}

				$wpdb->query('BEGIN;');

				// Data to update.
				$data = array(
					'label'      => $label,
					'updated_at' => current_time('Y-m-d H:i:s'),
				);

				$success = $wpdb->update(WLSM_SECTIONS, $data, array('ID' => $section_id));

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				if ($is_default) {
					$success = $wpdb->update(
						WLSM_CLASS_SCHOOL,
						array('default_section_id' => $section_id, 'updated_at' => current_time('Y-m-d H:i:s')),
						array('ID' => $class_school_id)
					);

					WLSM_Helper::check_buffer();

					if (false === $success) {
						throw new Exception($wpdb->last_error);
					}
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Section Updated Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have manage classes & sections permission to edit section.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Delete section.
	public static function delete_section($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('manage_classes', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$section_id 	= isset($params['section_id']) ? absint($params['section_id']) : 0;
		$class_id 		= isset($params['class_id']) ? absint($params['class_id']) : 0;

		try {

			if ($staff_permissions) {
				global $wpdb;

				if (empty($section_id)) {
					throw new Exception(esc_html__('Please select a section.', 'school-management'));
				}

				if (empty($class_id)) {
					throw new Exception(esc_html__('Please select a class.', 'school-management'));
				}

				// Checks if class exists in the school.
				$class_school = WLSM_M_Staff_Class::get_class($school_id, $class_id);

				if (!$class_school) {
					throw new Exception(esc_html__('Class not found.', 'school-management'));
				}

				$class_school_id = $class_school->ID;

				$default_section_id = $class_school->default_section_id;

				// Checks if section exists.
				$section = WLSM_M_Staff_Class::get_section($school_id, $section_id, $class_school_id);

				if (!$section) {
					throw new Exception(esc_html__('Section not found.', 'school-management'));
				}

				if ((int) $section->ID === (int) $default_section_id) {
					throw new Exception(esc_html__('Default section cannot be deleted.', 'school-management'));
				}

				$wpdb->query('BEGIN;');

				// Update student records to set section_id to default section
				$wpdb->update(
					WLSM_STUDENT_RECORDS,
					array('section_id' => $default_section_id, 'updated_at' => current_time('Y-m-d H:i:s')),
					array('section_id' => $section_id)
				);

				WLSM_Helper::check_buffer();

				// Delete the section
				$success = $wpdb->delete(WLSM_SECTIONS, array('ID' => $section_id, 'class_school_id' => $class_school_id));

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Section Deleted Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have manage classes & sections permission to delete section.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

