					if ($subject_id) {
						$attendance = WLSM_M::fetch_student_subject_attendance($student_id, $date, $subject_id);
					} else {
						$attendance = WLSM_M::fetch_student_attendance($student_id, $date);
					}

					if (empty($attendance)) {
						$attendance = array(
							'ID' 			=> "",
							'status' 		=> "",
							'reason' 		=> "",
