				$students = $new_students;
				$response_data['students'] = $students;

				$success = true;
				$message = esc_html__('Manage Students Attendance Retrieved Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view students attendance.', 'school-management'));
				die();
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

