			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Delete Event.
	public static function delete_event($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('delete_events', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 	= $request->get_params();
		$event_ids 	= isset($params['id']) && is_array($params['id']) ? $params['id'] : array();

		try {

			if ($staff_permissions) {
				global $wpdb;

				foreach ($event_ids as $event_id) {
					$event = WLSM_M_Staff_Class::get_event($school_id, $event_id);
					if (empty($event)) {
						throw new Exception(esc_html__('Event not found.', 'school-management'));
					}

					$success = $wpdb->delete(WLSM_EVENTS, array('ID' => $event_id, 'school_id' => $school_id));
					continue;
				}

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Event Deleted Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to delete event.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - View live classes.
	public static function view_live_classes($request)
	{

		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section 	= false;

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_live_classes', $permissions);
				$manage_class 		= in_array('assigned_class', $permissions);
				if ($manage_class) {
					$restrict_to_section = $section_id;
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$response_data = array();

				if ($restrict_to_section) {
					$admin = WLSM_M_Role::get_user_admin($school_id);
					$admin_id = $admin->ID;
					$meeting_query = WLSM_M_Staff_Class::fetch_staff_meeting_query($school_id, $admin_id);
				} else {
					$meeting_query = WLSM_M_Staff_Class::fetch_meeting_query($school_id);
				}

				$group_by		= ' ' . WLSM_M_Staff_Class::fetch_meeting_query_group_by();
				$meeting_query 	.= $group_by;
				$meetings 		= $wpdb->get_results($meeting_query);

				if ($meetings) {
					foreach ($meetings as $meeting) {
						$data[] = array(
							'ID' 			=> isset($meeting->ID) ? WLSM_M_Staff_Class::get_label_text($meeting->ID) : '',
							'topic' 		=> isset($meeting->topic) ? WLSM_M_Staff_Class::get_label_text($meeting->topic) : '',
							'host_id' 		=> isset($meeting->host_id) ? WLSM_M_Staff_Class::get_label_text($meeting->host_id) : '',
							'duration' 		=> isset($meeting->duration) ? absint($meeting->duration) : 0,
							'meeting_id' 	=> isset($meeting->meeting_id) ? WLSM_M_Staff_Class::get_label_text($meeting->meeting_id) : '',
							'start_url' 	=> isset($meeting->start_url) ? WLSM_M_Staff_Class::get_label_text($meeting->start_url) : '',
							'start_time' 	=> isset($meeting->start_at) ? WLSM_Config::get_at_text($meeting->start_at) : '',
							'type' 			=> isset($meeting->type) ? absint($meeting->type) : 0,
							'join_url' 		=> isset($meeting->join_url) ? WLSM_M_Staff_Class::get_label_text($meeting->join_url) : '',
							'class_label' 	=> isset($meeting->class_label) ? WLSM_M_Staff_Class::get_label_text($meeting->class_label) : '',
							'subject_name'  => isset($meeting->subject_name) ? WLSM_M_Staff_Class::get_label_text($meeting->subject_name) : '',
							'teacher' 		=> isset($meeting->name) ? WLSM_M_Staff_Class::get_label_text($meeting->name) : '',
						);
					}
					$response_data['meetings'] = $data;
				}

				$success = true;
				$message = esc_html__('Live Classes Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view live classes.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Add New Live Class.
	public static function add_new_live_class($request)
	{

		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section	= false;

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('add_live_classes', $permissions);
				$manage_class 		= in_array('assigned_class', $permissions);
				if ($manage_class) {
					$restrict_to_section = $section_id;
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {

			if ($staff_permissions) {
				global $wpdb;


				if (WLSM_Helper::is_php_incompatible_for_meetings()) {
					wp_send_json_error(esc_html__('Requires PHP 7.1 or greater.', 'school-management'));
				}

				$params 	= $request->get_params();
				$class_type = isset($params['class_type']) ? sanitize_text_field($params['class_type']) : '';

				$class_id   = isset($params['class_id']) ? absint($params['class_id']) : 0;
				$section_id = isset($params['section_id']) ? absint($params['section_id']) : 0;
				$subject_id = isset($params['subject_id']) ? absint($params['subject_id']) : 0;
				$admin_id   = isset($params['admin_id']) ? absint($params['admin_id']) : 0;

				$type 		= isset($params['type']) ? sanitize_text_field($params['type']) : '';
				$start_at 	= isset($params['start_at']) ? DateTime::createFromFormat(WLSM_Config::get_default_at_format(), sanitize_text_field($params['start_at'])) : 0;
				$duration 	= isset($params['duration']) ? absint($params['duration']) : 0;

				$password 	= isset($params['password']) ? sanitize_text_field($params['password']) : '';
				$topic  	= isset($params['topic']) ? sanitize_text_field($params['topic']) : '';
				$agenda 	= isset($params['agenda']) ? sanitize_text_field($params['agenda']) : '';

				$approval_type     	= isset($params['approval_type']) ? sanitize_text_field($params['approval_type']) : '';
				$registration_type 	= isset($params['registration_type']) ? sanitize_text_field($params['registration_type']) : '';
				$recurrence_type   	= isset($params['recurrence_type']) ? sanitize_text_field($params['recurrence_type']) : '';
				$repeat_interval 	= isset($params['repeat_interval']) ? sanitize_text_field($params['repeat_interval']) : '';
				$weekly_days     	= (isset($params['weekly_days']) && is_array($params['weekly_days'])) ? $params['weekly_days'] : array();
				$monthly_day     	= isset($params['monthly_day']) ? sanitize_text_field($params['monthly_day']) : '';
				$end_times       	= isset($params['end_times']) ? sanitize_text_field($params['end_times']) : '';
				$end_at   			= isset($params['end_at']) ? DateTime::createFromFormat(WLSM_Config::get_default_at_format(), sanitize_text_field($params['end_at'])) : 0;

				$join_before_host  = isset($params['join_before_host']) ? (bool) $params['join_before_host'] : false;
				$host_video        = isset($params['host_video']) ? (bool) $params['host_video'] : false;
				$participant_video = isset($params['participant_video']) ? (bool) $params['participant_video'] : false;
				$mute_upon_entry   = isset($params['mute_upon_entry']) ? (bool) $params['mute_upon_entry'] : false;

				// bbb
				$moderator  = isset($params['moderator']) ? sanitize_text_field($params['moderator']) : '';
				$recordable = isset($params['recordable']) ? (bool) $params['recordable'] : false;

				if (empty($recurrence_type)) {
					$recurrence_type   = '3';
				}

				if ($manage_class) {
					if ($restrict_to_section) {
						$restrict_to_section_detail = WLSM_M_Staff_Class::get_section_by_id($restrict_to_section);

						if (intval($restrict_to_section_detail->class_id) !== $class_id) {
							throw new Exception(esc_html__("You don't have permission to save for this class.", 'school-management'));
						}
					}
				}

				if (empty($admin_id)) {
					throw new Exception(esc_html__('Please select a teacher.', 'school-management'));
				}

				if (empty($class_id)) {
					throw new Exception(esc_html__('Please select a class.', 'school-management'));
				} else {
					$class_school = WLSM_M_Staff_Class::get_class($school_id, $class_id);
					if (!$class_school) {
						throw new Exception(esc_html__('Class not found.', 'school-management'));
					} else {
						$class_school_id = $class_school->ID;
					}
				}

				if (empty($subject_id)) {
					throw new Exception(esc_html__('Please select a subject.', 'school-management'));
				} else {
					// Check if subject belongs to a class.
					$subject = WLSM_M_Staff_Class::get_class_subject($school_id, $class_id, $subject_id);
					if (!$subject) {
						throw new Exception(esc_html__('Subject not found.', 'school-management'));
					}
				}

				$admin_subject = NULL;
				if ($admin_id) {
					// Check if teacher belongs to subject.
					$admin_subject = WLSM_M_Staff_Class::get_admin_subject($school_id, $subject_id, $admin_id);
					if (!$admin_subject) {
						throw new Exception(esc_html__('Teacher not found.', 'school-management'));
					}
				}

				if (!$admin_subject) {
					$admin_id = NULL;
				}

				if (!empty($type) && !in_array($type, array_keys(WLSM_Helper::meeting_types()))) {
					throw new Exception(esc_html__('Please select class type.', 'school-management'));
				}

				if (!empty($start_at)) {
					$start_at_string = ($start_at->format('Y-m-d') . 'T' . $start_at->format('H:i:s'));
					$start_at        = $start_at->format('Y-m-d H:i:s');
				} else {
					$start_at_string = null;
					$start_at        = NULL;
				}

				if (!empty($end_at)) {
					$end_at_string = ($end_at->format('Y-m-d') . 'T' . $end_at->format('H:i:s'));
					$end_at        = $end_at->format('Y-m-d H:i:s');
				} else {
					$end_at_string = null;
					$end_at        = NULL;
				}

				if (!empty($recurrence_type) && !in_array($recurrence_type, array_keys(WLSM_Helper::meeting_recurrence_types()))) {
					throw new Exception(esc_html__('Please select recurrence type.', 'school-management'));
				}

				if (!empty($approval_type) && !in_array($approval_type, array_keys(WLSM_Helper::meeting_approval_types()))) {
					throw new Exception(esc_html__('Please select approval type.', 'school-management'));
				}

				if (!empty($registration_type) && !in_array($registration_type, array_keys(WLSM_Helper::meeting_registration_types()))) {
					throw new Exception(esc_html__('Please select registration type.', 'school-management'));
				}

				if ($class_type === "bbb_class") {
					if (!$password) {
						throw new Exception(esc_html__('Please enter Password', 'school-management'));
					}
				}

				$settings_zoom_api_token = '';

				if ($class_type === 'zoom_class') {
					/** Get user id from the staff table  */
					$staff_id = WLSM_M_Staff_General::get_staff_id($admin_id);
					$staff_id = $staff_id->user_id;

					/** If user id exists */
					if ($staff_id) {
						$settings_zoom_api_key    = get_user_meta($staff_id, 'api_key', true);
						$settings_zoom_api_secret = get_user_meta($staff_id, 'api_secret', true);
						$settings_zoom_api_url    = get_user_meta($staff_id, 'redirect_url', true);
						$settings_zoom_api_token  = get_user_meta($staff_id, 'token', true);
						$token_expiration         = get_user_meta($staff_id, 'token_expiration', true);
					}
					if (!$settings_zoom_api_key) {
						throw new Exception(esc_html__('This Staff User Does Not Have API!', 'school-management'));
					}
				}

				$weekly_days = implode(',', $weekly_days);

				if ($class_type === 'bbb_class') {
					$data['moderator_code'] = $moderator;
					$data['recordable']     = $recordable;

					// New Lock Settings (passed to API where needed)
					$bbb_options = array(
						'record'            				=> $recordable ? 'true' : 'false',
						'lockSettingsDisablePrivateChat' 	=> isset($params['lock_private_chat']) ? 'true' : 'false',
						'lockSettingsDisablePublicChat'  	=> isset($params['lock_public_chat']) ? 'true' : 'false',
						'lockSettingsDisableNote'        	=> isset($params['lock_note']) ? 'true' : 'false',
						'lockSettingsDisableCam'         	=> isset($params['lock_cam']) ? 'true' : 'false',
						'lockSettingsDisableMic'         	=> isset($params['lock_mic']) ? 'true' : 'false',
					);
				} else {
					require_once WLSM_PLUGIN_DIR_PATH . 'includes/vendor/autoload.php';

					$client = new GuzzleHttp\Client(['base_uri' => 'https://api.zoom.us']);

					$access_token = $settings_zoom_api_token;

					$api_data = array(
						'topic'      => $topic,
						'type'       => $type,
						'start_time' => $start_at_string,
						'duration'   => $duration,
						'password'   => $password,
						'agenda'     => $agenda,
						'recurrence' => array(
							'type'            => $recurrence_type,
							'repeat_interval' => $repeat_interval,
							'weekly_days'     => $weekly_days,
							'monthly_day'     => $monthly_day,
							'end_times'       => $end_times,
						),
						'settings' => array(
							'join_before_host'  => $join_before_host,
							'host_video'        => $host_video,
							'participant_video' => $participant_video,
							'mute_upon_entry'   => $mute_upon_entry,
							'approval_type'     => $approval_type,
							'registration_type' => $registration_type,
						),
					);

					// Create a Zoom meeting using the obtained access token
					$response = $client->request('POST', '/v2/users/me/meetings', [
						'headers' => [
							'Authorization' => 'Bearer ' . $access_token,
							'Content-Type' 	=> 'application/json'
						],
						'json' => $api_data
					]);
					$response = json_decode($response->getBody());
				}

				// Meeting data.
				$data = array(
					'school_id'         => $school_id,
					'subject_id'        => $subject_id,
					'section_id'        => $section_id,
					'admin_id'          => $admin_id,
					'class_school_id'   => $class_school_id,
					'type'              => $type,
					'topic'             => $topic,
					'agenda'            => $agenda,
					'duration'          => $duration,
					'start_at'          => $start_at,
					'end_at'            => $end_at,
					'password'          => $password,
					'recurrence_type'   => isset($response->recurrence->type) ? $response->recurrence->type : $recurrence_type,
					'repeat_interval'   => isset($response->recurrence->repeat_interval) ? $response->recurrence->repeat_interval : $repeat_interval,
					'monthly_day'       => $monthly_day,
					'weekly_days'       => $weekly_days,
					'end_times'         => isset($response->recurrence->end_times) ? $response->recurrence->end_times : $end_times,
					'host_video'        => $host_video,
					'participant_video' => $participant_video,
					'join_before_host'  => $join_before_host,
					'mute_upon_entry'   => $mute_upon_entry,
					'approval_type'     => $approval_type,
					'registration_type' => $registration_type,
					'class_type'        => $class_type,
				);

				$data['meeting_id'] 	= WLSM_Helper::generate_random_code();
				$data['moderator_code'] = $moderator;
				$data['recordable']     = $recordable;

				if (isset($response->id)) {
					$data['meeting_id'] = $response->id;
				}

				if (isset($response->start_url)) {
					$data['start_url'] = $response->start_url;
				}

				if (isset($response->join_url)) {
					$data['join_url'] = $response->join_url;
				}

				if (isset($response->host_id)) {
					$data['host_id'] = $response->host_id;
				}

				$data['added_by'] 	= get_current_user_id();
				$data['created_at'] = current_time('Y-m-d H:i:s');

				$success = $wpdb->insert(WLSM_MEETINGS, $data);

				if ($class_type === 'bbb_class' && isset($bbb_options)) {
					// Use the actual meeting_id code (string) not the auto-inc ID
					update_option('wlsm_bbb_options_' . $data['meeting_id'], $bbb_options);
				}

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Live Class Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to add new live class.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - View live class by id.
	public static function view_live_class_by_id($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_live_classes', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$meeting_id 	= isset($params['id']) ? absint($params['id']) : 0;

		try {
			if ($staff_permissions) {
				global $wpdb;

				$response_data = array();

				$meeting = WLSM_M_Staff_Class::fetch_meeting($school_id, $meeting_id);
				if (! $meeting) {
					throw new Exception(esc_html__('Live class not found.', 'school-management'));
				}

				if ($meeting) {
					$bbb_options = array();
					$bbb_options = get_option('wlsm_bbb_options_' . $meeting->meeting_id);

					$data = array(
						'ID' 				=> isset($meeting->ID) ? absint($meeting->ID) : 0,
						'class_type' 		=> isset($meeting->class_type) ? WLSM_M_Staff_Class::get_label_text($meeting->class_type) : '',
						'class_id' 			=> isset($meeting->ID) ? absint($meeting->ID) : 0,
						'section_id' 		=> isset($meeting->ID) ? absint($meeting->ID) : 0,
						'subject_id' 		=> isset($meeting->ID) ? absint($meeting->ID) : 0,
						'admin_id' 			=> isset($meeting->ID) ? absint($meeting->ID) : 0,
						'class_label' 		=> isset($meeting->class_label) ? WLSM_M_Staff_Class::get_label_text($meeting->class_label) : '',
						'section_label' 	=> isset($meeting->section_label) ? WLSM_M_Staff_Class::get_label_text($meeting->section_label) : '',
						'subject_name' 		=> isset($meeting->subject_name) ? WLSM_M_Staff_Class::get_label_text($meeting->subject_name) : '',
						'name' 				=> isset($meeting->name) ? WLSM_M_Staff_Class::get_label_text($meeting->name) : '',
						'type' 				=> isset($meeting->type) ? absint($meeting->type) : 0,
						'start_time' 		=> isset($meeting->start_at) ? WLSM_Config::get_at_text($meeting->start_at) : '',
						'duration' 			=> isset($meeting->duration) ? absint($meeting->duration) : 0,
						'moderator_code' 	=> isset($meeting->moderator_code) ? WLSM_M_Staff_Class::get_label_text($meeting->moderator_code) : '',
						'password' 			=> isset($meeting->password) ? WLSM_M_Staff_Class::get_label_text($meeting->password) : '',
						'topic' 			=> isset($meeting->topic) ? WLSM_M_Staff_Class::get_label_text($meeting->topic) : '',
						'agenda' 			=> isset($meeting->agenda) ? WLSM_M_Staff_Class::get_label_text($meeting->agenda) : '',
						'approval_type' 	=> isset($meeting->approval_type) ? absint($meeting->approval_type) : 0,
						'registration_type' => isset($meeting->registration_type) ? absint($meeting->registration_type) : 0,
						'recurrence_type' 	=> isset($meeting->recurrence_type) ? absint($meeting->recurrence_type) : 0,
						'repeat_interval' 	=> isset($meeting->repeat_interval) ? absint($meeting->repeat_interval) : 0,
						'weekly_days' 		=> isset($meeting->weekly_days) ? absint($meeting->weekly_days) : 0,
						'monthly_day' 		=> isset($meeting->monthly_day) ? WLSM_M_Staff_Class::get_label_text($meeting->monthly_day) : '',
						'end_times' 		=> isset($meeting->end_times) ? WLSM_M_Staff_Class::get_label_text($meeting->end_times) : '',
						'end_at' 			=> isset($meeting->end_at) ? WLSM_Config::get_at_text($meeting->end_at) : '',
						'join_before_host' 	=> isset($meeting->join_before_host) ? (bool) $meeting->join_before_host : false,
						'host_video' 		=> isset($meeting->host_video) ? (bool) $meeting->host_video : false,
						'participant_video' => isset($meeting->participant_video) ? (bool) $meeting->participant_video : false,
						'mute_upon_entry' 	=> isset($meeting->mute_upon_entry) ? (bool) $meeting->mute_upon_entry : false,
						'recordable' 		=> isset($meeting->recordable) ? (bool) $meeting->recordable : false,
						'lockPrivateChat' 	=> is_array($bbb_options) ? (bool) $bbb_options['lockSettingsDisablePrivateChat'] : false,
						'lockPublicChat' 	=> is_array($bbb_options) ? (bool) $bbb_options['lockSettingsDisablePublicChat'] : false,
						'lockNote' 			=> is_array($bbb_options) ? (bool) $bbb_options['lockSettingsDisableNote'] : false,
						'lockCam' 			=> is_array($bbb_options) ? (bool) $bbb_options['lockSettingsDisableCam'] : false,
						'lockMic' 			=> is_array($bbb_options) ? (bool) $bbb_options['lockSettingsDisableMic'] : false,
					);
					$response_data['meeting'] = $data;
				}

				$success = true;
				$message = esc_html__('Live Class Retrieved Successfully.', 'school-management');

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view live class.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Edit live class.
	public static function edit_live_class($request)
	{
		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section	= false;

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('edit_live_classes', $permissions);
				$manage_class 		= in_array('assigned_class', $permissions);
				if ($manage_class) {
					$restrict_to_section = $section_id;
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {

			if ($staff_permissions) {
				global $wpdb;

				if (WLSM_Helper::is_php_incompatible_for_meetings()) {
					wp_send_json_error(esc_html__('Requires PHP 7.1 or greater.', 'school-management'));
				}

				$params 	= $request->get_params();
				$meeting_id = isset($params['meeting_id']) ? absint($params['meeting_id']) : 0;
				$class_type = isset($params['class_type']) ? sanitize_text_field($params['class_type']) : '';

				$class_id   = isset($params['class_id']) ? absint($params['class_id']) : 0;
				$section_id = isset($params['section_id']) ? absint($params['section_id']) : 0;
				$subject_id = isset($params['subject_id']) ? absint($params['subject_id']) : 0;
				$admin_id   = isset($params['admin_id']) ? absint($params['admin_id']) : 0;

				$type 		= isset($params['type']) ? sanitize_text_field($params['type']) : '';
				$start_at 	= isset($params['start_at']) ? DateTime::createFromFormat(WLSM_Config::get_default_at_format(), sanitize_text_field($params['start_at'])) : 0;
				$duration 	= isset($params['duration']) ? absint($params['duration']) : 0;

				$password 	= isset($params['password']) ? sanitize_text_field($params['password']) : '';
				$topic  	= isset($params['topic']) ? sanitize_text_field($params['topic']) : '';
				$agenda 	= isset($params['agenda']) ? sanitize_text_field($params['agenda']) : '';

				$approval_type     	= isset($params['approval_type']) ? sanitize_text_field($params['approval_type']) : '';
				$registration_type 	= isset($params['registration_type']) ? sanitize_text_field($params['registration_type']) : '';
				$recurrence_type   	= isset($params['recurrence_type']) ? sanitize_text_field($params['recurrence_type']) : '';
				$repeat_interval 	= isset($params['repeat_interval']) ? sanitize_text_field($params['repeat_interval']) : '';
				$weekly_days     	= (isset($params['weekly_days']) && is_array($params['weekly_days'])) ? $params['weekly_days'] : array();
				$monthly_day     	= isset($params['monthly_day']) ? sanitize_text_field($params['monthly_day']) : '';
				$end_times       	= isset($params['end_times']) ? sanitize_text_field($params['end_times']) : '';
				$end_at   			= isset($params['end_at']) ? DateTime::createFromFormat(WLSM_Config::get_default_at_format(), sanitize_text_field($params['end_at'])) : 0;

				$join_before_host  = isset($params['join_before_host']) ? (bool) $params['join_before_host'] : false;
				$host_video        = isset($params['host_video']) ? (bool) $params['host_video'] : false;
				$participant_video = isset($params['participant_video']) ? (bool) $params['participant_video'] : false;
				$mute_upon_entry   = isset($params['mute_upon_entry']) ? (bool) $params['mute_upon_entry'] : false;

				// bbb
				$moderator  = isset($params['moderator']) ? sanitize_text_field($params['moderator']) : '';
				$recordable = isset($params['recordable']) ? (bool) $params['recordable'] : false;

				if (empty($recurrence_type)) {
					$recurrence_type   = '3';
				}

				if ($manage_class) {
					if ($restrict_to_section) {
						$restrict_to_section_detail = WLSM_M_Staff_Class::get_section_by_id($restrict_to_section);

						if (intval($restrict_to_section_detail->class_id) !== $class_id) {
							throw new Exception(esc_html__("You don't have permission to save for this class.", 'school-management'));
						}
					}
				}

				$meeting = WLSM_M_Staff_Class::get_meeting($school_id, $meeting_id);
				if (empty($meeting)) {
					throw new Exception(esc_html__('Live class not found.', 'school-management'));
				}

				if (empty($admin_id)) {
					throw new Exception(esc_html__('Please select a teacher.', 'school-management'));
				}

				if (empty($class_id)) {
					throw new Exception(esc_html__('Please select a class.', 'school-management'));
				} else {
					$class_school = WLSM_M_Staff_Class::get_class($school_id, $class_id);
					if (!$class_school) {
						throw new Exception(esc_html__('Class not found.', 'school-management'));
					} else {
						$class_school_id = $class_school->ID;
					}
				}

				if (empty($subject_id)) {
					throw new Exception(esc_html__('Please select a subject.', 'school-management'));
				} else {
					// Check if subject belongs to a class.
					$subject = WLSM_M_Staff_Class::get_class_subject($school_id, $class_id, $subject_id);
					if (!$subject) {
						throw new Exception(esc_html__('Subject not found.', 'school-management'));
					}
				}

				$admin_subject = NULL;
				if ($admin_id) {
					// Check if teacher belongs to subject.
					$admin_subject = WLSM_M_Staff_Class::get_admin_subject($school_id, $subject_id, $admin_id);
					if (!$admin_subject) {
						throw new Exception(esc_html__('Teacher not found.', 'school-management'));
					}
				}

				if (!$admin_subject) {
					$admin_id = NULL;
				}

				if (!empty($type) && !in_array($type, array_keys(WLSM_Helper::meeting_types()))) {
					throw new Exception(esc_html__('Please select class type.', 'school-management'));
				}

				if (!empty($start_at)) {
					$start_at_string = ($start_at->format('Y-m-d') . 'T' . $start_at->format('H:i:s'));
					$start_at        = $start_at->format('Y-m-d H:i:s');
				} else {
					$start_at_string = null;
					$start_at        = NULL;
				}

				if (!empty($end_at)) {
					$end_at_string = ($end_at->format('Y-m-d') . 'T' . $end_at->format('H:i:s'));
					$end_at        = $end_at->format('Y-m-d H:i:s');
				} else {
					$end_at_string = null;
					$end_at        = NULL;
				}

				if (!empty($recurrence_type) && !in_array($recurrence_type, array_keys(WLSM_Helper::meeting_recurrence_types()))) {
					throw new Exception(esc_html__('Please select recurrence type.', 'school-management'));
				}

				if (!empty($approval_type) && !in_array($approval_type, array_keys(WLSM_Helper::meeting_approval_types()))) {
					throw new Exception(esc_html__('Please select approval type.', 'school-management'));
				}

				if (!empty($registration_type) && !in_array($registration_type, array_keys(WLSM_Helper::meeting_registration_types()))) {
					throw new Exception(esc_html__('Please select registration type.', 'school-management'));
				}

				if ($class_type === "bbb_class") {
					if (!$password) {
						throw new Exception(esc_html__('Please enter Password', 'school-management'));
					}
				}

				$settings_zoom_api_token = '';

				if ($class_type === 'zoom_class') {
					/** Get user id from the staff table  */
					$staff_id = WLSM_M_Staff_General::get_staff_id($admin_id);
					$staff_id = $staff_id->user_id;

					/** If user id exists */
					if ($staff_id) {
						$settings_zoom_api_key    = get_user_meta($staff_id, 'api_key', true);
						$settings_zoom_api_secret = get_user_meta($staff_id, 'api_secret', true);
						$settings_zoom_api_url    = get_user_meta($staff_id, 'redirect_url', true);
						$settings_zoom_api_token  = get_user_meta($staff_id, 'token', true);
						$token_expiration         = get_user_meta($staff_id, 'token_expiration', true);
					}
					if (!$settings_zoom_api_key) {
						throw new Exception(esc_html__('This Staff User Does Not Have API!', 'school-management'));
					}
				}

				$weekly_days = implode(',', $weekly_days);

				if ($class_type === 'bbb_class') {
					$data['moderator_code'] = $moderator;
					$data['recordable']     = $recordable;

					// New Lock Settings (passed to API where needed)
					$bbb_options = array(
						'record'            				=> $recordable ? 'true' : 'false',
						'lockSettingsDisablePrivateChat' 	=> isset($params['lock_private_chat']) ? 'true' : 'false',
						'lockSettingsDisablePublicChat'  	=> isset($params['lock_public_chat']) ? 'true' : 'false',
						'lockSettingsDisableNote'        	=> isset($params['lock_note']) ? 'true' : 'false',
						'lockSettingsDisableCam'         	=> isset($params['lock_cam']) ? 'true' : 'false',
						'lockSettingsDisableMic'         	=> isset($params['lock_mic']) ? 'true' : 'false',
					);
				} else {
					require_once WLSM_PLUGIN_DIR_PATH . 'includes/vendor/autoload.php';

					$client = new GuzzleHttp\Client(['base_uri' => 'https://api.zoom.us']);

					$access_token = $settings_zoom_api_token;

					$api_data = array(
						'topic'      => $topic,
						'type'       => $type,
						'start_time' => $start_at_string,
						'duration'   => $duration,
						'password'   => $password,
						'agenda'     => $agenda,
						'recurrence' => array(
							'type'            => $recurrence_type,
							'repeat_interval' => $repeat_interval,
							'weekly_days'     => $weekly_days,
							'monthly_day'     => $monthly_day,
							'end_times'       => $end_times,
						),
						'settings' => array(
							'join_before_host'  => $join_before_host,
							'host_video'        => $host_video,
							'participant_video' => $participant_video,
							'mute_upon_entry'   => $mute_upon_entry,
							'approval_type'     => $approval_type,
							'registration_type' => $registration_type,
						),
					);

					// Create a Zoom meeting using the obtained access token
					$response = $client->request('POST', '/v2/users/me/meetings', [
						'headers' => [
							'Authorization' => 'Bearer ' . $access_token,
							'Content-Type' 	=> 'application/json'
						],
						'json' => $api_data
					]);
					$response = json_decode($response->getBody());
				}

				// Meeting data.
				$data = array(
					'school_id'         => $school_id,
					'subject_id'        => $subject_id,
					'section_id'        => $section_id,
					'admin_id'          => $admin_id,
					'class_school_id'   => $class_school_id,
					'type'              => $type,
					'topic'             => $topic,
					'agenda'            => $agenda,
					'duration'          => $duration,
					'start_at'          => $start_at,
					'end_at'            => $end_at,
					'password'          => $password,
					'recurrence_type'   => isset($response->recurrence->type) ? $response->recurrence->type : $recurrence_type,
					'repeat_interval'   => isset($response->recurrence->repeat_interval) ? $response->recurrence->repeat_interval : $repeat_interval,
					'monthly_day'       => $monthly_day,
					'weekly_days'       => $weekly_days,
					'end_times'         => isset($response->recurrence->end_times) ? $response->recurrence->end_times : $end_times,
					'host_video'        => $host_video,
					'participant_video' => $participant_video,
					'join_before_host'  => $join_before_host,
					'mute_upon_entry'   => $mute_upon_entry,
					'approval_type'     => $approval_type,
					'registration_type' => $registration_type,
					'class_type'        => $class_type,
				);

				$data['meeting_id'] 	= WLSM_Helper::generate_random_code();
				$data['moderator_code'] = $moderator;
				$data['recordable']     = $recordable;

				if (isset($response->id)) {
					$data['meeting_id'] = $response->id;
				}

				if (isset($response->start_url)) {
					$data['start_url'] = $response->start_url;
				}

				if (isset($response->join_url)) {
					$data['join_url'] = $response->join_url;
				}

				if (isset($response->host_id)) {
					$data['host_id'] = $response->host_id;
				}

				$data['updated_at'] = current_time('Y-m-d H:i:s');

				$success = $wpdb->update(WLSM_MEETINGS, $data, array('ID' => $meeting_id));

				if ($class_type === 'bbb_class' && isset($bbb_options)) {
					// Use the actual meeting_id code (string) not the auto-inc ID
					update_option('wlsm_bbb_options_' . $meeting->meeting_id, $bbb_options);
				}

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Live Class Updated Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to edit live class.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Delete live class.
	public static function delete_live_class($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('delete_live_classes', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {

			if ($staff_permissions) {
				global $wpdb;

				$params 		= $request->get_params();
				$meeting_id 	= isset($params['id']) ? absint($params['id']) : 0;

				$meeting = WLSM_M_Staff_Class::get_meeting($school_id, $meeting_id);
				if (empty($meeting)) {
					throw new Exception(esc_html__('Live class not found.', 'school-management'));
				}

				$success = $wpdb->delete(WLSM_MEETINGS, array('ID' => $meeting_id, 'school_id' => $school_id));

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Live Class Deleted Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to delete live class.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - View staff rating.
	public static function view_staff_rating($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_live_classes', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$ratings_query 	= WLSM_M_Staff_Class::fetch_ratting_query();
				$group_by 		= ' ' . WLSM_M_Staff_Class::fetch_ratting_query_group_by();
				$ratings_query  .= $group_by;
				$ratings 		= $wpdb->get_results($ratings_query);

				if (empty($ratings)) {
					throw new Exception(esc_html__('No ratings found.', 'school-management'));
				}

				$rating_data = array();
				$rate_5 = 0;
				$rate_4 = 0;
				$rate_3 = 0;
				$rate_2 = 0;
				$rate_1 = 0;

				foreach ($ratings as $rating) {
					$get_class_students_count = WLSM_M_Staff_Class::get_class_students_count($rating->class_id);
					$feedback = $rating->ratting . '/' . $get_class_students_count;

					$total_ratting = WLSM_M_Staff_Class::fetch_ratting_count_query($rating->live_class_id);
					foreach ($total_ratting as $ratting) {

						if ($ratting->ratting == "5") {
							$rate_5 = intval($ratting->count);
						} elseif ($ratting->ratting == "4") {
							$rate_4 = intval($ratting->count);
						} elseif ($ratting->ratting == "3") {
							$rate_3 = intval($ratting->count);
						} elseif ($ratting->ratting == "2") {
							$rate_2 = intval($ratting->count);
						} elseif ($ratting->ratting == "1") {
							$rate_1 = intval($ratting->count);
						}
					}

					$average_ratting = (5 * $rate_5 + 4 * $rate_4 + 3 * $rate_3 + 2 * $rate_2 + 1 * $rate_1) / ($rate_5 + $rate_4 + $rate_3 + $rate_2 + $rate_1);

					$rating_data[] = array(
						'class_label' 		=> isset($rating->class_label) ? WLSM_M_Staff_Class::get_label_text($rating->class_label) : '',
						'subject_label' 	=> isset($rating->subject_label) ? WLSM_M_Staff_Class::get_label_text($rating->subject_label) : '',
						'teacher' 			=> isset($rating->teacher) ? WLSM_M_Staff_Class::get_label_text($rating->teacher) : '',
						'feedback' 			=> $feedback,
						'average_ratting' 	=> $average_ratting
					);
				}

				$success = true;
				$message = esc_html__('Staff ratings retrieved successfully.', 'school-management');

				$response_data['rating'] = $rating_data;

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have view live classes permission to view staff rating.', 'school-management'));
			}

		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (!empty($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - View student birthdays.
	public static function view_student_birthdays($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_students', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$students_birthdays_query 	= WLSM_M_Staff_General::fetch_students_birthdays_query($school_id, $session_id, $start_date = null, $end_date = null);
				$group_by 					= ' ' . WLSM_M_Staff_General::fetch_students_query_group_by();
				$students_birthdays_query   .= $group_by;
				$students 					= $wpdb->get_results($students_birthdays_query);

				if (!$students) {
					throw new Exception(esc_html__('No students found.', 'school-management'));
				}

				foreach ($students as $student) {
					$student_data[] = array(
						'ID'  				=> isset($student->ID) ? absint($student->ID) : 0,
						'admission_number'  => isset($student->admission_number) ? WLSM_M_Staff_Class::get_admission_no_text($student->admission_number) : '',
