			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Delete exam result.
	public static function delete_exam_result($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('delete_exam_results', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$admit_card_id 	= isset($params['admit_card_id']) ? absint($params['admit_card_id']) : 0;

		try {

			if ($staff_permissions) {
				global $wpdb;

				$admit_card = WLSM_M_Staff_Examination::get_admit_card($school_id, $admit_card_id);
				if (! $admit_card) {
					throw new Exception(esc_html__('Admit card not found.', 'school-management'));
				}

				// Get exam results for admit card.
				$exam_results_ids = WLSM_M_Staff_Examination::get_exam_results_ids_by_admit_card($school_id, $admit_card_id);

				$exam_results_ids_count = count($exam_results_ids);

				$place_holders = array_fill(0, $exam_results_ids_count, '%d');

				$exam_results_ids_format = implode(', ', $place_holders);

				$success = $wpdb->query($wpdb->prepare('DELETE FROM ' . WLSM_EXAM_RESULTS . ' WHERE ID IN( ' . $exam_results_ids_format . ') ', $exam_results_ids));

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Exam Result Deleted Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to delete exam result.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - View class exams.
	public static function view_class_exams($request)
	{

		$user_id = get_current_user_id();
		$staff 	= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('add_exam_results', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = absint($session->ID);

				$params 	= $request->get_params();
				$class_id 	= isset($params['class_id']) ? absint($params['class_id']) : 0;

				if (empty($class_id)) {
					throw new Exception(esc_html__('Class not found.', 'school-management'));
				}

				$exams = WLSM_M_Staff_Class::get_exams($school_id, $class_id, $session_id);

				foreach ($exams as $exam) {
					$data[] = array(
						'ID' 		=> isset($exam->ID) ? absint($exam->ID) : 0,
						'label' 	=> isset($exam->label) ? WLSM_M_Staff_Class::get_label_text($exam->label) : '',
						'exam_type' => isset($exam->exam_type) ? WLSM_M_Staff_Class::get_label_text($exam->exam_type) : ''
					);
					$response_data['class_exams'] = $data;
				}

				$success = true;
				$message = esc_html__('Class Exams Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view exam results.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - View academic reports.
	public static function view_academic_reports($request)
	{

		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section 	= false;
		$is_admin 				= false;

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_exam_results', $permissions);
				$manage_class 		= WLSM_M_Role::can('assigned_class');
				if ($manage_class) {
					$restrict_to_section = $section_id;
					$is_admin = $manage_class['school']['role'] === WLSM_M_Role::get_admin_key();
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = absint($session->ID);

				$academic_report_query = WLSM_M_Staff_Examination::fetch_academic_report_query($school_id, $session_id);

				if ($manage_class && ! $is_admin) {
					if ($restrict_to_section) {
						$restrict_to_section_detail = WLSM_M_Staff_Class::get_section_by_id($restrict_to_section);
						$class_id = $restrict_to_section_detail->class_id;
						$academic_report_query = WLSM_M_Staff_Examination::fetch_academic_report_query_by_class_id($school_id, $class_id, $session_id);
					} else {
						$academic_report_query = WLSM_M_Staff_Examination::fetch_academic_report_query($school_id, $session_id) . ' AND 1=0';
					}
				}

				$group_by 				= ' ' . WLSM_M_Staff_Examination::fetch_academic_report_query_group_by();
				$academic_report_query  .= $group_by;
				$academic_reports 		= $wpdb->get_results($academic_report_query);

				if ($academic_reports) {
					foreach ($academic_reports as $academic_report) {

						$exam_ids = isset($academic_report->exam_ids) ? $academic_report->exam_ids : [];
						if (!is_array($exam_ids)) {
							$exam_ids = json_decode($academic_report->exam_ids, true);
						}

						if (!empty($exam_ids)) {
							$placeholders = implode(',', array_fill(0, count($exam_ids), '%d'));
							$query = "SELECT ID, label FROM " . WLSM_EXAMS . " WHERE ID IN ($placeholders)";
							$exam_names = $wpdb->get_results($wpdb->prepare($query, $exam_ids));
							$exam_names = array_map(function($exam) {
								return [
									'id'    => (int) $exam->ID,
									'label' => $exam->label
								];
							}, $exam_names);
						} else {
							$exam_names = [];
						}

						$data[] = array(
							'ID' 		=> isset($academic_report->ID) ? absint($academic_report->ID) : 0,
							'title' 	=> isset($academic_report->report_label) ? WLSM_M_Staff_Class::get_label_text($academic_report->report_label) : '',
							'group_id' 	=> isset($academic_report->group_id) ? absint($academic_report->group_id) : 0,
							'group_label' => isset($academic_report->group_label) ? WLSM_M_Staff_Class::get_label_text($academic_report->group_label) : '',
							'class_id' 	=> isset($academic_report->class_id) ? absint($academic_report->class_id) : 0,
							'class_label' => isset($academic_report->class_label) ? WLSM_M_Staff_Class::get_label_text($academic_report->class_label) : '',
							'exams' 	=> isset($exam_names) ? $exam_names	: array()
						);
						$response_data['academic_reports'] = $data;
					}
				}

				$success = true;
				$message = esc_html__('Academic Reports Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view exam results.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Add New Academic Report.
	public static function add_new_academic_report($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('add_exam_results', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();

		$label 			= isset($params['label']) ? sanitize_text_field($params['label']) : '';
		$exam_group		= isset($params['exam_group']) ? absint($params['exam_group']) : 0;
		$class_id 		= isset($params['class_id']) ? absint($params['class_id']) : 0;
		$exam_ids 		= isset($params['exam_ids']) && is_array($params['exam_ids']) ? $params['exam_ids'] : [];

		try {

			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = absint($session->ID);

				if (empty($label)) {
					throw new Exception(esc_html__('Please enter a title.', 'school-management'));
				}

				if (empty($exam_group)) {
					throw new Exception(esc_html__('Please select an exam group.', 'school-management'));
				}

				if (empty($class_id)) {
					throw new Exception(esc_html__('Please select a class.', 'school-management'));
				}

				if (empty($exam_ids)) {
					throw new Exception(esc_html__('Please select atleast an exam.', 'school-management'));
				}

				$exam_ids = json_encode($exam_ids);

				$data = array(
					'label' 			=> $label,
					'exam_group'		=> $exam_group,
					'class_id' 			=> $class_id,
					'exams' 			=> $exam_ids,
					'is_active' 		=> 1,
					'school_id' 		=> $school_id,
					'session_id' 		=> $session_id,
					'created_at'        => current_time('Y-m-d H:i:s')
				);

				$success = $wpdb->insert(WLSM_ACADEMIC_REPORTS, $data);

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Academic Report Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to add new exam results.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

