	{

		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_accounting_dashboard', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::fetch_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id 		= isset($session->ID) ? absint($session->ID) : 0;
				$session_start_date = $session->start_date;
				$session_end_date 	= $session->end_date;
				$date_now        	= date('Y-m-d');
				$previous_session 		= WLSM_M_Session::get_pre_session($current_session_id);
				$previous_session_id 	= ($previous_session) ? $previous_session->ID : null ;
				$previous_session_label = ($previous_session) ? $previous_session->label : 'Not Exists' ;

				$total_invoices_count = WLSM_M_Staff_Accountant::get_total_invoices_count($school_id, $session_id);
				$invoices_paid_count = WLSM_M_Staff_Accountant::get_invoices_paid_count($school_id, $session_id);
				$invoices_unpaid_count = WLSM_M_Staff_Accountant::get_invoices_unpaid_count($school_id, $session_id);
				$invoices_partially_paid_count = WLSM_M_Staff_Accountant::get_invoices_partially_paid_count($school_id, $session_id);

				$total_payments_count = $wpdb->get_var(WLSM_M_Staff_Accountant::fetch_payments_query_count($school_id, $session_id));
				$total_payment_received = WLSM_M_Staff_Accountant::get_total_payments_received($school_id, $session_id);
				$invoices_pending_amount = WLSM_M_Staff_Accountant::get_invoices_pending_amount($school_id, $session_id);
				$invoices_pending_amount = array_sum( $invoices_pending_amount );
				$total_expenses_sum = WLSM_M_Staff_Accountant::get_total_expenses_sum($school_id, $session_start_date, $session_end_date);

				$total_income_sum = WLSM_M_Staff_Accountant::get_total_income_sum($school_id, $session_start_date, $session_end_date);
				$total_dailypaymentstotal_sum = WLSM_M_Staff_Accountant::get_total_dailypaymentstotal_sum($school_id, $session_id, $date_now);
				$total_dailyexpencestotal_sum = WLSM_M_Staff_Accountant::get_total_dailyexpencestotal_sum($school_id, $date_now);
				if ($previous_session_id) {
					$previous_session_invoices_pending_amount = WLSM_M_Staff_Accountant::get_previous_session_invoices_pending_amount( $school_id, $previous_session_id );
					$previous_session_pending_invoice = array_sum( $previous_session_invoices_pending_amount );
				} else {
					$previous_session_pending_invoice = 0;
				}

				$transport_students_count = WLSM_M_Staff_Accountant::get_transport_students_count($school_id, $session_id);
				$transport_invoices_total = WLSM_M_Staff_Accountant::get_transport_invoices_total($session_id, $school_id);
				$transport_invoices_paid = WLSM_M_Staff_Accountant::get_transport_invoices_paid($session_id, $school_id);
				$transport_invoices_unpaid = WLSM_M_Staff_Accountant::get_transport_invoices_unpaid($session_id, $school_id);
				$transport_amount_collected = WLSM_M_Staff_Accountant::get_transport_amount_collected($session_id, $school_id);

				$data = array(
					'total_invoices'  				=> $total_invoices_count,
					'paid_invoices'   				=> $invoices_paid_count,
					'unpaid_invoices' 				=> $invoices_unpaid_count,
					'partially_paid_invoices' 		=> $invoices_partially_paid_count,
					'total_payments' 				=> $total_payments_count,
					'payment_received' 				=> $total_payment_received,
					'amount_pending' 				=> $invoices_pending_amount,
					'expense'						=> $total_expenses_sum,
					'donation'						=> $total_income_sum,
			        'daily_payments_total'      	=> $total_dailypaymentstotal_sum,
					'daily_expense_total'			=> $total_dailyexpencestotal_sum,
					'previous_year_total_pending'	=> $previous_session_pending_invoice,
					'students_with_transport'       => $transport_students_count,
					'transport_invoices'			=> $transport_invoices_total,
					'transport_paid'				=> $transport_invoices_paid,
					'transport_unpaid'				=> $transport_invoices_unpaid,
					'transport_collected'			=> $transport_amount_collected
				);
				$response_data['accounting_dashboard'] = $data;

				$now = date('Y-m-d');

				// Last 15 Payments
				$payments = WLSM_M_Staff_Accountant::fetch_payments($school_id, $session_id, $now);

				foreach ($payments as $row) {
					$payments_data[] = array(
						'receipt_number' => esc_html(WLSM_M_Invoice::get_receipt_number_text($row->receipt_number)),
						'amount' => esc_html(WLSM_Config::get_money_text($row->amount, $school_id)),
						'payment_method' => esc_html(WLSM_M_Invoice::get_payment_method_text($row->payment_method)),
						'transaction_id' => esc_html(WLSM_M_Invoice::get_transaction_id_text($row->transaction_id)),
						'date' => esc_html(WLSM_Config::get_date_text($row->created_at)),
						'invoice' => esc_html(WLSM_M_Staff_Class::get_label_text($row->invoice_title)),
						'student_name' => esc_html(WLSM_M_Staff_Class::get_name_text($row->student_name)),
						'admission_number' => esc_html(WLSM_M_Staff_Class::get_admission_no_text($row->admission_number)),
						'class_label' => esc_html(WLSM_M_Class::get_label_text($row->class_label)),
						'section_label' => esc_html(WLSM_M_Staff_Class::get_section_label_text($row->section_label)),
						'phone' => esc_html(WLSM_M_Staff_Class::get_phone_text($row->phone)),
						'father_name' => esc_html(WLSM_M_Staff_Class::get_name_text($row->father_name)),
						'father_phone' => esc_html(WLSM_M_Staff_Class::get_phone_text($row->father_phone))
					);
					$response_data['payments'] = $payments_data;
				}

				$success = true;
				$message = esc_html__('Accounting Dashboard Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view accounting dashboard.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - View fee types.
	public static function view_fee_types($request)
	{

		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section 	= false;

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_fees', $permissions);
				$manage_class 		= WLSM_M_Role::can('assigned_class');
				if ($manage_class) {
					$restrict_to_section = $section_id;
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::fetch_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$fee_query 	= WLSM_M_Staff_Accountant::fetch_fee_query($school_id, $restrict_to_section, $session_id);
				$group_by 	= ' ' . WLSM_M_Staff_Accountant::fetch_fee_query_group_by();
				$fee_query  .= $group_by;
				$fee_types 	= $wpdb->get_results($fee_query);

				if ($fee_types) {
					foreach ($fee_types as $fee_type) {
						$data[] = array(
							'ID'   			=> isset($fee_type->ID) ? WLSM_M_Staff_Class::get_label_text($fee_type->ID) : '',
							'label' 		=> isset($fee_type->fee_label) ? WLSM_M_Staff_Class::get_label_text($fee_type->fee_label) : '',
							'amount'   		=> isset($fee_type->amount) ? WLSM_M_Staff_Class::get_label_text($fee_type->amount) : '',
							'class_label'   => isset($fee_type->label) ? WLSM_M_Staff_Class::get_label_text($fee_type->label) : '',
							'period'   		=> isset($fee_type->period) ? WLSM_M_Staff_Class::get_label_text($fee_type->period) : '',
						);
						$response_data['fee_types'] = $data;
					}
				}

				$success = true;
				$message = esc_html__('Fee Types Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view fees.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Add New Fee Types.
	public static function add_new_fee_type($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('add_fees', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 							= $request->get_params();

		$label 								= isset($params['label']) ? sanitize_text_field($params['label']) : '';
		$session_id	 						= isset($params['session_id']) ? absint($params['session_id']) : 0;
		$class_ids	 						= isset($params['class_ids']) && is_array($params['class_ids']) ? $params['class_ids'] : '';
		$student_types 						= isset($params['student_types']) && is_array($params['student_types']) ? $params['student_types'] : '';
		$fee_type 							= isset($params['fee_type']) ? WLSM_Helper::normalize_fee_type($params['fee_type']) : '';
		$period 							= isset($params['period']) ? sanitize_text_field($params['period']) : 'one-time';
		$amount 							= isset($params['amount']) ? sanitize_text_field($params['amount']) : 0;
		$auto_generate_invoice_on_admission = isset($params['auto_generate_invoice_on_admission']) ? (bool) $params['auto_generate_invoice_on_admission'] : true;
		$dashboard_disable 					= isset($params['dashboard_disable']) ? (bool) $params['dashboard_disable'] : false;
		$include_on_promotion 				= isset($params['include_on_promotion']) ? (bool) $params['include_on_promotion'] : true;

		try {

			if ($staff_permissions) {
				global $wpdb;

				if (empty($label)) {
					throw new Exception(esc_html__('Please enter a title.', 'school-management'));
				}

				if (empty($session_id)) {
					throw new Exception(esc_html__('Please select a session.', 'school-management'));
				}

				if (empty($class_ids)) {
					throw new Exception(esc_html__('Please select atleast a class.', 'school-management'));
				}

				if (empty($student_types)) {
					throw new Exception(esc_html__('Please select atleast a student type.', 'school-management'));
				}

				if (empty($amount)) {
					throw new Exception(esc_html__('Please enter amount.', 'school-management'));
				}

				if (empty($fee_type)) {
					throw new Exception(esc_html__('Please select fee type.', 'school-management'));
				}

				$student_type = is_array($student_types) ? serialize($student_types) : '';

				foreach ($class_ids as $class_id) {
					$data = array(
						'label'   					=> $label,
						'amount' 					=> $amount,
						'period'   					=> $period,
						'school_id' 				=> $school_id,
						'session_id'        		=> $session_id,
						'active_on_admission'   	=> $auto_generate_invoice_on_admission,
						'active_on_dashboard'   	=> $dashboard_disable,
						'student_type'   			=> $student_type,
						'fee_type'   				=> $fee_type,
						'include_on_promotion' 	=> $include_on_promotion,
						'class_id'					=> $class_id,
					);
					$data['created_at'] = current_time('Y-m-d H:i:s');
					$success 			= $wpdb->insert(WLSM_FEES, $data);
				}

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Fee Type Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to add fees.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

