	// Staff - View Transport Students.
	public static function view_transport_students($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_invoices', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 	= $request->get_params();
		$class_id 	= isset($params['class_id']) ? absint($params['class_id']) : 0;
		$section_id = isset($params['section_id']) ? absint($params['section_id']) : 0;
		$status 	= isset($params['status']) ? sanitize_text_field($params['status']) : '';

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::fetch_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$start_dt = new DateTime( $session->start_date );
				$end_dt   = new DateTime( $session->end_date );
				$end_dt->modify( 'last day of this month' );
				$session_months = 0;
				$tmp = clone $start_dt;
				while ( $tmp <= $end_dt ) {
					$session_months++;
					$tmp->modify( '+1 month' );
				}

				$filter = array(
					'class_id' 		=> $class_id,
					'section_id' 	=> $section_id,
					'student_id' 	=> 0
				);

				$students_query = WLSM_M_Staff_Accountant::fetch_transport_students_query( $school_id, $session_id, $filter );
				$students_all   = $wpdb->get_results( $students_query );
				$student_ids 	= wp_list_pluck( $students_all, 'ID' );

				$invoice_counts = array();
				if ( ! empty( $student_ids ) ) {
					$in_ids = implode( ',', array_map( 'absint', $student_ids ) );
					$invs   = $wpdb->get_results(
						"SELECT student_record_id, status, transport_month
						FROM " . WLSM_INVOICES . "
						WHERE student_record_id IN ($in_ids) AND invoice_type = 'transport'"
					);

					// Group by student and unique Month-Year
					$student_month_map = array();
					foreach ( $invs as $inv ) {
						$month_key = $inv->transport_month;
						if ( ! empty( $month_key ) ) {
							$student_month_map[ $inv->student_record_id ][ $month_key ] = $inv->status;
						}
					}

					foreach ( $student_month_map as $sid => $months ) {
						$invoice_counts[ $sid ] = array( 'paid' => 0, 'unpaid' => 0, 'partially_paid' => 0, 'total' => 0 );
						foreach ( $months as $inv_status ) {
							if ( isset( $invoice_counts[ $sid ][ $inv_status ] ) ) {
								$invoice_counts[ $sid ][ $inv_status ]++;
							}
							$invoice_counts[ $sid ]['total']++;
						}
					}
				}

				// Build rows and apply status filter
				$rows = array();
				foreach ( $students_all as $std ) {
					$counts   = isset( $invoice_counts[ $std->ID ] ) ? $invoice_counts[ $std->ID ] : array( 'paid' => 0, 'unpaid' => 0, 'partially_paid' => 0, 'total' => 0 );
					$paid     = $counts['paid'];
					$unpaid   = $counts['unpaid'] + $counts['partially_paid'];
					$total_inv = $counts['total'];

					if ( ! $std->route_vehicle_id ) {
						$row_status = 'no_transport';
					} elseif ( $total_inv >= $session_months ) {
						$row_status = 'all_generated';
					} elseif ( $total_inv === 0 ) {
						$row_status = 'none_generated';
					} else {
						$row_status = 'partial';
					}

					if ( $status && $status !== $row_status ) {
						continue;
					}

					$rows[] = array(
						'student'     => $std,
						'paid'        => $paid,
						'unpaid'      => $unpaid,
						'total_inv'   => $total_inv,
						'session_months' => $session_months,
						'row_status'  => $row_status,
					);
				}

				foreach ( $rows as $row ) {
					$std        = $row['student'];
					$paid       = $row['paid'];
					$unpaid     = $row['unpaid'];
					$total_inv  = $row['total_inv'];
					$sm         = $row['session_months'];
					$not_gen    = max( 0, $sm - $total_inv );

					if ( $std->route_vehicle_id ) {
						$route_info = esc_html( $std->route_name . ' / ' . $std->vehicle_number );
						$fare_info  = esc_html( WLSM_Config::get_money_text( $std->fare ) );
					} else {
						$route_info = esc_html__( 'Not Assigned', 'school-management' );
						$fare_info  = '—';
					}

					$paid_badge    = $paid    > 0 ? $paid : 0;
					$unpaid_badge  = $unpaid  > 0 ? $unpaid : 0;

					if ( $std->route_vehicle_id ) {
						$not_gen_badge = $not_gen > 0
							? $not_gen
							: 0;
					} else {
						$not_gen_badge = '—';
					}

					$data = array(
						'ID' 				=> esc_html( $std->ID ),
						'student_name' 		=> esc_html( $std->name ),
						'enrollment_number' => esc_html( $std->enrollment_number ),
						'class_section' 	=> esc_html( $std->class_label . ' / ' . $std->section_label ),
						'route_info' 		=> $route_info,
						'fare_info' 		=> $fare_info,
						'paid' 				=> $paid_badge,
						'unpaid' 			=> $unpaid_badge,
						'not_gen' 			=> $not_gen_badge
					);
					$response_data['transport_students'][] = $data;
				}

				$success = true;
				$message = esc_html__('Transport Students Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view invoices.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Assign Route To Student.
	public static function assign_route_to_student($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('edit_students', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$params 			= $request->get_params();
				$student_id 		= isset($params['student_id']) ? absint($params['student_id']) : 0;
				$route_vehicle_id 	= isset($params['route_vehicle_id']) ? absint($params['route_vehicle_id']) : 0;

				if (! $route_vehicle_id ) {
					throw new Exception(esc_html__('Please select a vehicle.', 'school-management'));
				}

				$student = WLSM_M::get_student_by_id($student_id);
				if (! $student ) {
					throw new Exception(esc_html__('Student not found.', 'school-management'));
				}

				$vehicle = WLSM_M_Staff_Transport::get_route_vehicle( $school_id, $route_vehicle_id );
				if (! $vehicle ) {
					throw new Exception(esc_html__('Vehicle not found.', 'school-management'));
				}

				$success = $wpdb->update(WLSM_STUDENT_RECORDS, array( 'route_vehicle_id' => $route_vehicle_id ), array( 'ID' => $student_id ));

				$message = esc_html__('Route Assigned To Student Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to edit students.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - View student transport details.
	public static function view_student_transport_details($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 	= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_invoices', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$params 		= $request->get_params();
				$class_id 		= isset($params['class_id']) ? absint($params['class_id']) : 0;
				$section_id 	= isset($params['section_id']) ? absint($params['section_id']) : 0;
				$student_id 	= isset($params['student_id']) ? absint($params['student_id']) : 0;
				$status 		= isset($params['status']) ? sanitize_text_field($params['status']) : '';

				if ( empty( $class_id ) && empty( $section_id ) && empty( $student_id ) ) {
					throw new Exception( esc_html__( 'Please specify search criteria.', 'school-management' ) );
				}

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::fetch_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$start_date = new DateTime( $session->start_date );
				$end_date   = new DateTime( $session->end_date );
				$end_date->modify( 'last day of this month' );
				$interval = DateInterval::createFromDateString( '1 month' );
				$period   = new DatePeriod( $start_date, $interval, $end_date );

				$filter = array(
					'class_id' 		=> $class_id,
					'section_id' 	=> $section_id,
					'student_id' 	=> $student_id,
					'status' 		=> $status,
				);

				$students_query = WLSM_M_Staff_Accountant::fetch_transport_students_query( $school_id, $session_id, $filter );
				$students = $wpdb->get_results( $students_query );

				$invoice_map = array();
				$rows = array();

				$invoices = WLSM_M_Staff_Accountant::fetch_transport_invoices( $session_id );
				foreach ( $invoices as $inv ) {
					$month_key = $inv->transport_month;
					if ( ! empty( $month_key ) ) {
						$invoice_map[ $inv->student_record_id . '_' . $month_key ] = $inv;
					}
				}

				foreach ( $students as $student ) {
					foreach ( $period as $dt ) {
						$month_key = $dt->format( 'Y-m' );
						$month_name = $dt->format( 'F Y' );
						$has_invoice = isset( $invoice_map[ $student->ID . '_' . $month_key ] );

							$row_status = '';

							if ( $has_invoice ) {
								$row_status = 'generated';
							} elseif ( ! $student->route_vehicle_id ) {
								$row_status = 'no_transport';
							} else {
								$row_status = 'pending';
							}

						if ( $status && $status !== $row_status ) {
							continue;
						}

						$row = array(
							'student'      => $student,
							'month_key'    => $month_key,
							'month_name'   => $month_name,
							'status'       => $row_status,
							'invoice'      => $has_invoice ? $invoice_map[ $student->ID . '_' . $month_key ] : null,
						);
						$rows[] = $row;
					}
				}

				foreach ( $rows as $row ) {
					$std 		 = $row['student'];
					$invoice_no  = '-';
					$amount 	 = '-';
					$status_html = '';
					$route_info  = $std->route_vehicle_id ? ($std->route_name . ' (' . $std->vehicle_number . ')') : esc_html__( 'Not Assigned', 'school-management' );

					if ( 'generated' === $row['status'] ) {
						$inv 		= $row['invoice'];
						$amount 	= WLSM_Config::get_money_text( $inv->amount );
						$invoice_no = esc_html( $inv->invoice_number );
						if ( $inv->status == 'paid' ) {
							$status_html 	= 'Paid';
						} else {
							$status_html = 'Unpaid';			
						}
					} elseif ( 'no_transport' === $row['status'] ) {
						$status_html = 'No Transport';
					} else {
						$amount = WLSM_Config::get_money_text( $std->fare );
						$status_html = 'Not Generated';
					}

					$data = array(
						'student_name' 		=> esc_html( $std->name ),
						'enrollment_number' => esc_html( $std->enrollment_number ),
						'class_section' 	=> esc_html( $std->class_label . ' / ' . $std->section_label ),
						'route_info' 		=> $route_info,
						'month_name' 		=> esc_html( $row['month_name'] ),
						'amount' 			=> $amount,
						'invoice_no' 		=> $invoice_no,
						'status_html' 		=> $status_html,
					);
					$response_data['student_transport_details'][] = $data;
				}

				$success = true;
				$message = esc_html__('Student Transport Details Retrieved Successfully.', 'school-management');

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view invoices.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Generate Student Transport Invoice.
	public static function generate_student_transport_invoice($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('add_invoices', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}
	
		try {

			if ($staff_permissions) {
				global $wpdb;

				$params = $request->get_params();
				$items  = isset( $params['items'] ) ? $params['items'] : array();
				if ( empty( $items ) ) {
					throw new Exception( esc_html__( 'No items selected.', 'school-management' ) );
				}

				$generated = 0;
				$skipped   = 0;

				$settings_general      = WLSM_M_Setting::get_settings_general( $school_id );
				$allow_partial_payment = isset( $settings_general['auto_invoice_allow_partial_payment'] ) ? $settings_general['auto_invoice_allow_partial_payment'] : 1;

				foreach ( $items as $item ) {
					$student_id = absint( $item['student_record_id'] );
					$month_year = sanitize_text_field( $item['month_year'] ); // e.g., '2024-04'

					$student = $wpdb->get_row( $wpdb->prepare(
						"SELECT sr.ID as student_id, cs.school_id, sr.session_id, sr.route_vehicle_id, sr.name as student_name,
								ro.fare, ro.period, ro.name as route_name, v.vehicle_number
						FROM " . WLSM_STUDENT_RECORDS . " as sr
						INNER JOIN " . WLSM_SECTIONS . " as se ON se.ID = sr.section_id
						INNER JOIN " . WLSM_CLASS_SCHOOL . " as cs ON cs.ID = se.class_school_id
						INNER JOIN " . WLSM_ROUTE_VEHICLE . " as rv ON rv.ID = sr.route_vehicle_id
						INNER JOIN " . WLSM_ROUTES . " as ro ON ro.ID = rv.route_id
						INNER JOIN " . WLSM_VEHICLES . " as v ON v.ID = rv.vehicle_id
						WHERE sr.ID = %d AND cs.school_id = %d",
						$student_id, $school_id
					) );

					if ( ! $student ) continue;

					$existing_invoice = $wpdb->get_var( $wpdb->prepare(
						"SELECT COUNT(*) FROM " . WLSM_INVOICES . "
						WHERE student_record_id = %d
						AND invoice_type = 'transport'
						AND transport_month = %s",
						$student->student_id,
						$month_year
					) );

					if ( $existing_invoice == 0 ) {
						$invoice_label  = sprintf( 'Transport Fee - %s (%s)', $student->route_name, date('F Y', strtotime($month_year . '-01')) );
						$date_issued    = current_time('Y-m-d H:i:s'); // True generation date
						$due_date       = date( 'Y-m-t', strtotime( $month_year . '-01' ) ); // Last day of target month
						$invoice_number = WLSM_M_Invoice::get_invoice_number( $school_id );

						$wpdb->query('BEGIN;');

						$transport_invoice_data = array(
							'label'                => $invoice_label,
							'amount'               => $student->fare,
							'invoice_amount_total' => $student->fare,
							'invoice_number'       => $invoice_number,
							'date_issued'          => $date_issued,
							'due_date'             => $due_date,
							'invoice_type'         => 'transport',
							'transport_month'      => $month_year,
							'student_record_id'    => $student->student_id,
							'partial_payment'      => $allow_partial_payment,
							'added_by'             => get_current_user_id(),
							'created_at'           => current_time('Y-m-d H:i:s'),
						);

						$invoice_success = $wpdb->insert( WLSM_INVOICES, $transport_invoice_data );
						if ( $invoice_success ) {
							$wpdb->query('COMMIT;');
							$generated++;
						} else {
							$wpdb->query('ROLLBACK;');
							$skipped++;
						}
					} else {
						$skipped++;
					}
				}

				$success = true;
				$message = sprintf( esc_html__( '%d invoices generated successfully.', 'school-management' ), $generated );
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to add invoices.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - View Collect Payment.
	public static function view_collect_payment($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_invoices', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$params 	= $request->get_params();
				$search_by 	= 'search_by_class';
				$class_id   = isset($params['class_id']) ? absint($params['class_id']) : 0;
				$section_id = isset($params['section_id']) ? absint($params['section_id']) : 0;
				$student_id = isset($params['student_id']) ? absint($params['student_id']) : 0;
				$status     = isset($params['status']) ? sanitize_text_field($params['status']) : '';

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				if (!in_array($search_by, array('search_by_keyword', 'search_by_class', 'search_by_date'))) {
					throw new Exception(esc_html__('Please specify search criteria.', 'school-management'));
				}

				if ('search_by_class' === $search_by) {
					if (empty($class_id)) {
						throw new Exception(esc_html__('Please select a class.', 'school-management'));
					}

					$filter = array(
						'class_id'   => $class_id,
						'section_id' => $section_id,
						'student_id' => $student_id,
						'status'     => $status,
					);
				}
				
				$filter['search_by'] = $search_by;

				$query 		= WLSM_M_Staff_Accountant::fetch_invoices_query($school_id, $session_id, $filter);
				$group_by 	= ' ' . WLSM_M_Staff_Accountant::fetch_invoices_query_group_by();
				$query    	.= $group_by;
				$invoices   = $wpdb->get_results($query);

				if ($invoices) {
					foreach ($invoices as $invoice) {
						$invoice_id = isset($invoice->ID) ? absint($invoice->ID) : 0;
						$paid 		= WLSM_M_Staff_Accountant::get_invoice_payments_total($invoice_id);
						$due 		= isset($invoice->amount) ? ($invoice->amount) - $paid : '';
						$data = array(
							'ID'   				=> isset($invoice->ID) ? absint($invoice->ID) : 0,
							'student_name'  	=> isset($invoice->student_name) ? WLSM_M_Staff_Class::get_label_text($invoice->student_name) : '',
							'father_name'   	=> isset($invoice->father_name) ? WLSM_M_Staff_Class::get_label_text($invoice->father_name) : '',
							'admission_number'  => isset($invoice->admission_number) ? WLSM_M_Staff_Class::get_admission_no_text($invoice->admission_number) : '',
							'invoice_number'  	=> isset($invoice->invoice_number) ? WLSM_M_Staff_Class::get_admission_no_text($invoice->invoice_number) : '',
							'invoice_title'   	=> isset($invoice->invoice_title) ? WLSM_M_Staff_Class::get_label_text($invoice->invoice_title) : '',
							'payable' 			=> isset($invoice->amount) ? WLSM_M_Staff_Class::get_label_text($invoice->amount) : '',
							'paid' 				=> isset($paid) ? $paid : '',
							'due' 				=> isset($due) ? $due : '',
							'status' 			=> isset($invoice->status) ? WLSM_M_Staff_Class::get_label_text($invoice->status) : '',
							'date_issued' 		=> isset($invoice->date_issued) ? WLSM_M_Staff_Class::get_date_text($invoice->date_issued) : '',
							'due_date' 			=> isset($invoice->due_date) ? WLSM_M_Staff_Class::get_date_text($invoice->due_date) : '',
							'phone' 			=> isset($invoice->phone) ? WLSM_M_Staff_Class::get_phone_text($invoice->phone) : '',
							'class_label' 		=> isset($invoice->class_label) ? WLSM_M_Staff_Class::get_label_text($invoice->class_label) : '',
							'section_label' 	=> isset($invoice->section_label) ? WLSM_M_Staff_Class::get_label_text($invoice->section_label) : '',
							'enrollment_number'  => isset($invoice->enrollment_number) ? WLSM_M_Staff_Class::get_admission_no_text($invoice->enrollment_number) : ''
						);
						$response_data['collect_payments'][] = $data;
					}
				}

				$success = true;
				$message = esc_html__('Collecte Payments Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view invoices.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Student Finance Summary.
	public static function student_finance_summary($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_invoices', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$params 	= $request->get_params();
				$student_id = isset($params['student_id']) ? absint($params['student_id']) : 0;
				if (!$student_id) { 
					throw new Exception(esc_html__('Please select a student.', 'school-management')); 
				}

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				// Basic student details
				$student = WLSM_M_Staff_General::fetch_student($school_id, $session_id, $student_id);
				if (!$student) { 
					throw new Exception(__('Student not found.', 'school-management')); 
				}

				// Session months from student record (fallback to 12 if dates unavailable)
				$months_in_session = 12;
				
				if (!empty($student->start_date) && !empty($student->end_date)) {
					$start_date = new DateTime($student->start_date);
					$end_date   = new DateTime($student->end_date);
					$interval   = $start_date->diff($end_date);
					$months_in_session = ($interval->y * 12) + $interval->m;
					if ($interval->d > 0) { $months_in_session++; }
				}

				// Fees totals by period
				$fees = WLSM_M_Staff_Accountant::fetch_student_fees($school_id, $student_id);
				$period_totals = array(
					'monthly' => 0,
					'quarterly' => 0,
					'quadrimester' => 0,
					'half-yearly' => 0,
					'annually' => 0,
					'one-time' => 0,
				);
				foreach ($fees as $fee) {
					switch ($fee->period) {
						case 'monthly':       $period_totals['monthly']       += (int)$fee->amount * $months_in_session; break;
						case 'one-time':      $period_totals['one-time']      += (int)$fee->amount; break;
						case 'quarterly':     $period_totals['quarterly']     += (int)$fee->amount * ceil($months_in_session / 3); break;
						case 'quadrimester':  $period_totals['quadrimester']  += (int)$fee->amount * ceil($months_in_session / 4); break;
						case 'half-yearly':   $period_totals['half-yearly']   += (int)$fee->amount * ceil($months_in_session / 6); break;
						case 'annually':      $period_totals['annually']      += (int)$fee->amount * ceil($months_in_session / 12); break;
					}
				}
				$total_payable = array_sum($period_totals);

				// Concession
				$concession = WLSM_M_Staff_General::fetch_student_concession($student_id, $session_id, $school_id);
				$concession_amount = 0;
				if ($concession && 'approved' === $concession->status) {
					if ('percentage' === $concession->concession_type) {
						$concession_amount = ($total_payable * $concession->percentage_value) / 100;
					} elseif ('fixed_amount' === $concession->concession_type) {
						$concession_amount = min($concession->fixed_amount, $total_payable);
					}
				}
				$payable_after_concession = max($total_payable - $concession_amount, 0);

				// Total paid
				$total_paid = 0;
				$payments = WLSM_M_Staff_Accountant::get_student_payments($student_id);
				if (!empty($payments)) { foreach ($payments as $p) { $total_paid += (float)$p->amount; } }
				$remaining = max($payable_after_concession - $total_paid, 0);

				// Build detailed student record for response
				$student_full = WLSM_M_Staff_General::fetch_student_by_id($student_id);

				// Response build
				$data = array(
					'student' => array(
						'name' => isset($student->student_name) ? $student->student_name : (isset($student_full->student_name) ? $student_full->student_name : ''),
						'admission_number' => isset($student_full->admission_number) ? $student_full->admission_number : (isset($student->admission_number) ? $student->admission_number : ''),
						// 'enrollment_number' => isset($student_full->enrollment_number) ? $student_full->enrollment_number : (isset($student->enrollment_number) ? $student->enrollment_number : ''),
						'father_name' => isset($student_full->father_name) ? $student_full->father_name : (isset($student->father_name) ? $student->father_name : ''),
						'class_label' => isset($student_full->class_label) ? $student_full->class_label : (isset($student->class_label) ? $student->class_label : ''),
						'section_label' => isset($student_full->section_label) ? $student_full->section_label : (isset($student->section_label) ? $student->section_label : ''),
						'phone' => isset($student_full->phone) ? $student_full->phone : (isset($student->phone) ? $student->phone : ''),
						'email' => isset($student_full->email) ? $student_full->email : (isset($student->email) ? $student->email : ''),
					),
					'amounts' => array(
						'total_session' => WLSM_Config::get_money_text($total_payable, $school_id),
						'concession' => WLSM_Config::get_money_text($concession_amount, $school_id),
						'balance' => WLSM_Config::get_money_text($payable_after_concession, $school_id),
						'paid' => WLSM_Config::get_money_text($total_paid, $school_id),
						'remaining' => WLSM_Config::get_money_text($remaining, $school_id),
					),
					// 'raw' => compact('total_payable','concession_amount','payable_after_concession','total_paid','remaining','period_totals'),
				);
				$response_data['student_finance_summary'] = $data;

				$success = true;
				$message = esc_html__('Collecte Payments Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view invoices.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - View invoices report.
	public static function view_invoices_report($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_invoices', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$class_id 		= isset($params['class_id']) ? absint($params['class_id']) : 0;
		$section_id 	= isset($params['section_id']) ? absint($params['section_id']) : 0;
		$status 		= isset($params['status']) ? sanitize_text_field($params['status']) : '';
		$payment_method = isset($params['payment_method']) ? sanitize_text_field($params['payment_method']) : '';

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::fetch_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id 	= isset($session->ID) ? absint($session->ID) : 0;
				$session_label 	= isset($session->label) ? sanitize_text_field($session->label) : 0;

				// Get all payment methods
				$collect_payment_methods = WLSM_M_Invoice::collect_payment_methods();

				// Get payment gateway settings
				// Razorpay settings
				$settings_razorpay      = WLSM_M_Setting::get_settings_razorpay($school_id);
				$school_razorpay_enable = $settings_razorpay['enable'];

				// Paytm settings
				$settings_paytm      = WLSM_M_Setting::get_settings_paytm($school_id);
				$school_paytm_enable = $settings_paytm['enable'];

				// Stripe settings
				$settings_stripe      = WLSM_M_Setting::get_settings_stripe($school_id);
				$school_stripe_enable = $settings_stripe['enable'];

				// Payu settings
				$settings_payu      = WLSM_M_Setting::get_settings_payu($school_id);
				$school_payu_enable = $settings_payu['enable'];

				// PayPal settings
				$settings_paypal      = WLSM_M_Setting::get_settings_paypal($school_id);
				$school_paypal_enable = $settings_paypal['enable'];

				// Amberpay settings
				$settings_amberpay      = WLSM_M_Setting::get_settings_amberpay($school_id);
				$school_amberpay_enable = $settings_amberpay['enable'];

				// Pesapal settings
				$settings_pesapal      = WLSM_M_Setting::get_settings_pesapal($school_id);
				$school_pesapal_enable = $settings_pesapal['enable'];

				// Sslcommerz settings
				$settings_sslcommerz      = WLSM_M_Setting::get_settings_sslcommerz($school_id);
				$school_sslcommerz_enable = $settings_sslcommerz['enable'];

				// Paystack settings
				$settings_paystack      = WLSM_M_Setting::get_settings_paystack($school_id);
				$school_paystack_enable = $settings_paystack['enable'];

				// Authorize settings
				$settings_authorize      = WLSM_M_Setting::get_settings_authorize($school_id);
				$school_authorize_enable = $settings_authorize['enable'];

				// Bank transfer settings
				$settings_bank_transfer      = WLSM_M_Setting::get_settings_bank_transfer($school_id);
				$school_bank_transfer_enable = $settings_bank_transfer['enable'];

				// UPI transfer settings
				$settings_upi_transfer      = WLSM_M_Setting::get_settings_upi_transfer($school_id);
				$school_upi_transfer_enable = $settings_upi_transfer['enable'];

				// Cash payment settings
				$settings_cash = WLSM_M_Setting::get_settings_cash($school_id);
				$school_cash_enable = $settings_cash['enable'];

				// Card payment settings
				$settings_card = WLSM_M_Setting::get_settings_card($school_id);
				$school_card_enable = $settings_card['enable'];

				// Check payment settings
				$settings_check = WLSM_M_Setting::get_settings_check($school_id);
				$school_check_enable = $settings_check['enable'];

				// Demand Draft payment settings
				$settings_demand_draft = WLSM_M_Setting::get_settings_demand_draft($school_id);
				$school_demand_draft_enable = $settings_demand_draft['enable'];

				$enabled_payment_methods = array(
					'stripe'        => (bool) $school_stripe_enable,
					'payu'          => (bool) $school_payu_enable,
					'paypal'        => (bool) $school_paypal_enable,
					'razorpay'      => (bool) $school_razorpay_enable,
					'paytm'         => (bool) $school_paytm_enable,
					'pesapal'       => (bool) $school_pesapal_enable,
					'paystack'      => (bool) $school_paystack_enable,
					'sslcommerz'    => (bool) $school_sslcommerz_enable,
					'bank-transfer' => (bool) $school_bank_transfer_enable,
					'upi-transfer'  => (bool) $school_upi_transfer_enable,
					'amberpay'      => (bool) $school_amberpay_enable,
					'cash'          => (bool) $school_cash_enable,
					'check'         => (bool) $school_check_enable,
					'demand-draft'  => (bool) $school_demand_draft_enable,
					'card'          => (bool) $school_card_enable,
				);
				$response_data['payment_methods'] = $enabled_payment_methods;

				// Get payment statistics
				$payment_statistics = WLSM_M_Staff_Accountant::get_payment_method_statistics($school_id, $session_id);

				foreach ($collect_payment_methods as $method_key => $method_label) {

					// If method not returned from DB → default zero
					$stat = isset($payment_statistics[$method_key]) ? $payment_statistics[$method_key] : array(
						'amount' => 0
					);

					$statistics[] = array(
						'payment_method'       => $method_label,
						'amount'               => WLSM_Config::get_money_text($stat['amount'], $school_id),
						'session_label'           => $session_label,
					);
				}
				$response_data['payment_statistics'] = $statistics;

				$filter = array(
					'class_id' 			=> $class_id,
					'section_id' 		=> $section_id,
					'student_id' 		=> 0,
					'status' 			=> $status,
					'payment_method' 	=> $payment_method
				);

				$filter['search_by'] = 'search_by_class';

				$invoices_report_query 	= WLSM_M_Staff_Accountant::fetch_invoices_report($school_id, $session_id, $filter);
				$group_by 				= ' ' . WLSM_M_Staff_Accountant::fetch_invoices_report_query_group_by();
				$query_with_group 		= $invoices_report_query . $group_by;
				$invoices_report 		= $wpdb->get_results($query_with_group);

				if ($invoices_report) {
					foreach ($invoices_report as $invoice) {
						$data = array(
							'student_name'  	=> isset($invoice->student_name) ? WLSM_M_Staff_Class::get_label_text($invoice->student_name) : '',
							'enrollment_number' => isset($invoice->enrollment_number) ? WLSM_M_Staff_Class::get_admission_no_text($invoice->enrollment_number) : '',
							'father_name'   	=> isset($invoice->father_name) ? WLSM_M_Staff_Class::get_label_text($invoice->father_name) : '',
							'admission_number'  => isset($invoice->admission_number) ? WLSM_M_Staff_Class::get_admission_no_text($invoice->admission_number) : '',
							'payable'   		=> isset($invoice->payable) ? WLSM_M_Staff_Class::get_label_text($invoice->payable) : '',
							'paid'   			=> isset($invoice->paid) ? WLSM_M_Staff_Class::get_label_text($invoice->paid) : '',
							'due'   			=> isset($invoice->due) ? WLSM_M_Staff_Class::get_label_text($invoice->due) : '',
							'phone' 			=> isset($invoice->phone) ? WLSM_M_Staff_Class::get_phone_text($invoice->phone) : '',
							'class_label' 		=> isset($invoice->class_label) ? WLSM_M_Staff_Class::get_label_text($invoice->class_label) : '',
							'section_label' 	=> isset($invoice->section_label) ? WLSM_M_Staff_Class::get_label_text($invoice->section_label) : ''
						);
						$response_data['invoices_report'][] = $data;
					}
				}

				$success = true;
				$message = esc_html__('Invoices Report Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view invoices.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

