	// Staff - Add new donation category.
	public static function add_new_donation_category($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('add_income_category', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params = $request->get_params();
		$label 	= isset($params['label']) ? sanitize_text_field($params['label']) : '';

		try {

			if ($staff_permissions) {
				global $wpdb;

				if (empty($label)) {
					throw new Exception(esc_html__('Please specify donation category.', 'school-management'));
				}

				$income_category_exist = $wpdb->get_var($wpdb->prepare('SELECT COUNT(*) as count FROM ' . WLSM_INCOME_CATEGORIES . ' as ic WHERE ic.label = %s AND ic.school_id = %d', $label, $school_id));

				if ($income_category_exist) {
					throw new Exception(esc_html__('Donation category already exists with this label.', 'school-management'));
				}

				$data = array(
					'label' 	 => $label,
					'school_id'  => $school_id,
				);
				$data['created_at'] = current_time('Y-m-d H:i:s');
				$success 			= $wpdb->insert(WLSM_INCOME_CATEGORIES, $data);

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Donation Category Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to add donation.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

