	// Staff - Add new hostel.
	public static function add_new_hostel($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('add_hostel', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 	= $request->get_params();
		$name 		= isset($params['name']) ? sanitize_text_field($params['name']) : '';
		$type 		= isset($params['type']) ? sanitize_text_field($params['type']) : NULL;
		$address	= isset($params['address']) ? sanitize_text_field($params['address']) : NULL;
		$intake		= isset($params['intake']) ? absint($params['intake']) : 0;
		$fees 		= isset($params['fees']) ? absint($params['fees']) : 0;

		try {

			if ($staff_permissions) {
				global $wpdb;

				if (empty($name)) {
					throw new Exception(esc_html__('Please enter name.', 'school-management'));
				}

				$data = array(
					'hostel_name'  			=> $name,
					'hostel_type'  			=> $type,
					'hostel_address'  		=> $address,
					'hostel_intake'  		=> $intake,
					'fees' 	 				=> $fees,
					'school_id' 			=> $school_id,
				);
				$data['created_at'] = current_time('Y-m-d H:i:s');
				$success 			= $wpdb->insert(WLSM_HOSTELS, $data);

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Hostel Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to add hostel.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

