	// Staff - Add new activity.
	public static function add_new_activity($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('add_activities', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$title 			= isset($params['title']) ? sanitize_text_field($params['title']) : '';
		$fees 			= isset($params['fees']) ? sanitize_text_field($params['fees']) : '';
		$description 	= isset($params['description']) ? sanitize_text_field($params['description']) : '';
		$status 		= isset($params['status']) ? absint($params['status']) : '';
