				$success = true;
				$message = esc_html__('Ticket Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to add tickets.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Ticket details.
	public static function ticket_details($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('view_tickets', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$params 	= $request->get_params();
				$id 		= isset($params['id']) ? absint($params['id']) : 0;

				$ticket = WLSM_M_Staff_Tickets::fetch_ticket($id);

				if (! $ticket) {
					throw new Exception(esc_html__('Ticket not found.', 'school-management'));
				}

				if ($ticket) {
					$class 		= isset($ticket->priority) ? WLSM_M_Staff_Class::fetch_class($school_id, $ticket->class_id) : '';
					$section 	= isset($ticket->priority) ? WLSM_M_Staff_Class::get_section_by_id($ticket->section_id) : '';
					$student 	= isset($ticket->priority) ? WLSM_M::get_student_by_id($ticket->student_id) : '';
					$subject 	= isset($ticket->priority) ? WLSM_M_Staff_Class::fetch_subject($school_id, $ticket->subject_id) : '';
					$role 		= isset($ticket->priority) ? WLSM_M_Staff_General::fetch_role( $school_id, $ticket->role_id ) : '';
					$staff 		= isset($ticket->priority) ? WLSM_M::get_admin($ticket->assigned_to) : '';

					$data = array(
						'ID'   			=> isset($ticket->ID) ? absint($ticket->ID) : 0,
						'title'   		=> isset($ticket->title) ? WLSM_M_Staff_Class::get_name_text($ticket->title) : '',
						'due_date'   		=> isset($ticket->due_date) ? WLSM_M_Staff_Class::get_date_text($ticket->due_date) : '',
						'class_id'    		=> isset($ticket->class_id) ? absint($ticket->class_id) : 0,
						'section_id'    	=> isset($ticket->section_id) ? absint($ticket->section_id) : 0,
						'student_id'    	=> isset($ticket->student_id) ? absint($ticket->student_id) : 0,
						'subject_id'    	=> isset($ticket->subject_id) ? absint($ticket->subject_id) : 0,
						'role_id'    		=> isset($ticket->role_id) ? absint($ticket->role_id) : 0,
						'assigned_to'   	=> isset($ticket->assigned_to) ? absint($ticket->assigned_to) : 0,
						'class_label'   	=> isset($class) ? WLSM_M_Staff_Class::get_label_text($class->class_label) : '',
						'section_label' 	=> isset($section) ? WLSM_M_Staff_Class::get_label_text($section->section_label) : '',
						'student_name'  	=> isset($student) ? WLSM_M_Staff_Class::get_label_text($student->student_name) : '',
						'subject_label' 	=> isset($subject) ? WLSM_M_Staff_Class::get_label_text($subject->subject_name) : '',
						'role_name' 		=> isset($role) ? WLSM_M_Staff_Class::get_label_text($role->name) : '',
						'assigned_to_name' 	=> isset($staff) ? WLSM_M_Staff_Class::get_label_text($staff->name) : '',
						'description'   	=> isset($ticket->description) ? WLSM_M_Staff_Class::get_name_text($ticket->description) : '',
						'priority'   		=> isset($ticket->priority) ? ucfirst($ticket->priority) : '',
						'status'   			=> isset($ticket->status) ? ucfirst($ticket->status) : '',
					);
					$response_data['ticket_details'] = $data;
				}

				$ticket_history = WLSM_M_Staff_Tickets::get_ticket_history($id);

				foreach ($ticket_history as $history) {
					$history_data[] = array(
						'ID'   			=> isset($history->ID) ? absint($history->ID) : 0,
						'changed_by'   	=> isset($history->changed_by_name) ? WLSM_M_Staff_Class::get_name_text($history->changed_by_name) : '',
						'comment'   	=> isset($history->comment) ? WLSM_M_Staff_Class::get_name_text($history->comment) : '',
						'status'   		=> isset($history->status) ? ucfirst($history->status) : '',
						'created_at'   	=> isset($history->created_at) ? WLSM_M_Staff_Class::get_date_text($history->created_at) : '',
					);
					$response_data['ticket_history'] = $history_data;
				}

				$success = true;
				$message = esc_html__('Ticket details Retrieved Successfully.', 'school-management');

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to view tickets.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Edit ticket.
	public static function edit_ticket($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : null;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : null;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('edit_tickets', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$id 			= isset($params['id']) ? absint($params['id']) : 0;
		$title 			= isset($params['title']) ? sanitize_text_field($params['title']) : '';
		$description 	= isset($params['description']) ? sanitize_text_field($params['description']) : '';
		$priority 		= isset($params['priority']) ? sanitize_text_field($params['priority']) : 'normal';
		$status 		= isset($params['status']) ? sanitize_text_field($params['status']) : 'open';
		$assigned_to    = isset($params['assigned_to']) ? absint($params['assigned_to']) : 0;
		$due_date       = isset($params['due_date']) ? DateTime::createFromFormat(WLSM_Config::date_format(), sanitize_text_field($params['due_date'])) : NULL;
		$class_id       = isset($params['class_id']) ? absint($params['class_id']) : 0;
		$section_id     = isset($params['section_id']) ? absint($params['section_id']) : 0;
		$student_id     = isset($params['student_id']) ? absint($params['student_id']) : 0;
		$subject_id     = isset($params['subject_id']) ? absint($params['subject_id']) : 0;
		$role           = isset($params['role']) ? absint($params['role']) : 0;

		try {

			if ($staff_permissions) {
				global $wpdb;

				$ticket = WLSM_M_Staff_Tickets::fetch_ticket($id);

				if (! $ticket) {
					throw new Exception(esc_html__('Ticket not found.', 'school-management'));
				}

				if (empty($title)) {
					throw new Exception(esc_html__('Please enter title.', 'school-management'));
				}

				if (empty($class_id)) {
					throw new Exception(esc_html__('Please select a class.', 'school-management'));
				}

				if (empty($section_id)) {
					throw new Exception(esc_html__('Please select a section.', 'school-management'));
				}

				if (empty($student_id)) {
					throw new Exception(esc_html__('Please select a student.', 'school-management'));
				}

				// Check priority enum
				if (!in_array($priority, array('low', 'normal', 'high', 'urgent'))) {
					$priority = 'normal';
				}

				// Check status enum
				if (!in_array($status, array('open', 'in_progress', 'resolved', 'closed'))) {
					$status = 'open';
				}

				if (empty($due_date)) {
					throw new Exception(esc_html__('Please specify leave end date.', 'school-management'));
				} else {
					$due_date = $due_date->format('Y-m-d');
				}

				// Ticket data
				$data = array(
					'title'       => $title,
					'description' => $description,
					'priority'    => $priority,
					'status'      => $status,
					'assigned_to' => $assigned_to,
					'due_date'    => $due_date,
					'class_id'    => $class_id,
					'section_id'  => $section_id,
					'student_id'  => $student_id,
					'subject_id'  => $subject_id,
					'school_id'   => $school_id,
					'role_id'     => $role
				);

				$data['updated_at'] = current_time('Y-m-d H:i:s');
				$success            = $wpdb->update(WLSM_TICKETS, $data, array('ID' => $id));

				if ($success) {
					// Add ticket history
					$data = array(
						'ticket_id' 	=> $id,
						'status' 		=> $status,
						'comment' 		=> $description,
						'assigned_to'   => $assigned_to,
						'changed_by' 	=> $user_id,
						'created_at' 	=> current_time('Y-m-d H:i:s')
					);
					$wpdb->insert(WLSM_TICKET_HISTORY, $data);
				}

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Ticket Updated Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to edit tickets.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

