		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Edit book.
	public static function edit_book($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('edit_library', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$id 			= isset($params['id']) ? absint($params['id']) : 0;
		$title 			= isset($params['title']) ? sanitize_text_field($params['title']) : '';
		$author 		= isset($params['author']) ? sanitize_text_field($params['author']) : '';
		$subject 		= isset($params['subject']) ? sanitize_text_field($params['subject']) : '';
		$price 			= isset($params['price']) ? sanitize_text_field($params['price']) : '';
		$quantity    	= isset($params['quantity']) ? sanitize_text_field($params['quantity']) : '';
		$description    = isset($params['description']) ? sanitize_text_field($params['description']) : NULL;
		$rack_number    = isset($params['rack_number']) ? sanitize_text_field($params['rack_number']) : '';
		$book_number    = isset($params['book_number']) ? sanitize_text_field($params['book_number']) : '';
		$isbn_number    = isset($params['isbn_number']) ? sanitize_text_field($params['isbn_number']) : '';

		try {

			if ($staff_permissions) {
				global $wpdb;

				$book = WLSM_M_Staff_Library::fetch_book($school_id, $id);

				if (! $book) {
					throw new Exception(esc_html__('Book not found.', 'school-management'));
				}

				if (empty($title)) {
					throw new Exception(esc_html__('Please enter title.', 'school-management'));
				}

				if (strlen($title) > 100) {
					throw new Exception(esc_html__('Maximum length cannot exceed 100 characters.', 'school-management'));
				}

				if (strlen($author) > 60) {
					throw new Exception(esc_html__('Maximum length cannot exceed 60 characters.', 'school-management'));
				}

				if (strlen($subject) > 100) {
					throw new Exception(esc_html__('Maximum length cannot exceed 100 characters.', 'school-management'));
				}

				if (strlen($rack_number) > 40) {
					throw new Exception(esc_html__('Maximum length cannot exceed 40 characters.', 'school-management'));
				}

				if (strlen($book_number) > 100) {
					throw new Exception(esc_html__('Maximum length cannot exceed 100 characters.', 'school-management'));
				}

				if (strlen($isbn_number) > 100) {
					throw new Exception(esc_html__('Maximum length cannot exceed 100 characters.', 'school-management'));
				}

				// Book data.
				$data = array(
					'title'       => $title,
					'author'      => $author,
					'subject'     => $subject,
					'price'       => $price,
					'quantity'    => $quantity,
					'description' => $description,
					'rack_number' => $rack_number,
					'book_number' => $book_number,
					'isbn_number' => $isbn_number,
					'school_id'   => $school_id
				);

				$data['updated_at'] = current_time('Y-m-d H:i:s');
				$success            = $wpdb->update(WLSM_BOOKS, $data, array('school_id' => $school_id, 'ID' => $id));

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Book Updated Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to edit library.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

