	// Staff - Issue book.
	public static function issue_book($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('issue_books', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 			= $request->get_params();
		$id 				= isset($params['id']) ? absint($params['id']) : 0;
		$student_id 		= isset($params['student']) ? absint($params['student']) : '';
		$quantity    		= isset($params['quantity']) ? absint($params['quantity']) : 1;
		$date_issued       	= isset($params['date_issued']) ? DateTime::createFromFormat(WLSM_Config::date_format(), sanitize_text_field($params['date_issued'])) : NULL;
		$return_date       	= isset($params['return_date']) ? DateTime::createFromFormat(WLSM_Config::date_format(), sanitize_text_field($params['return_date'])) : NULL;

		try {

			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$book = WLSM_M_Staff_Library::get_book($school_id, $id);

				if (! $book) {
					throw new Exception(esc_html__('Book not found.', 'school-management'));
				}

				if (empty($student_id)) {
					throw new Exception(esc_html__('Please select a student.', 'school-management'));
				}

				if (empty($date_issued)) {
					throw new Exception(esc_html__('Please provide date issued.', 'school-management'));
				} else {
					$date_issued = $date_issued->format('Y-m-d');
				}

				if (! empty($return_date)) {
					$return_date = $return_date->format('Y-m-d');
				} else {
					$return_date = NULL;
				}

				// Checks if student exists.
				$student = WLSM_M_Staff_General::get_student($school_id, $session_id, $student_id, true, true);

				if (! $student) {
					throw new Exception(esc_html__('Student not found.', 'school-management'));
				}

				$total_book_copies_issued = absint(WLSM_M_Staff_Library::get_total_book_copies_issued($school_id, $session_id, $id));

				if ($book->quantity <= $total_book_copies_issued) {
					throw new Exception(esc_html__('Total ' . $total_book_copies_issued . ' of this books issued to students have pending returns which exceeds book quantity in the library.', 'school-management'));
				}

				// Book issued data.
				$data = array(
					'book_id'           => $id,
					'student_record_id' => $student_id,
					'quantity'          => $quantity,
					'date_issued'       => $date_issued,
					'return_date'       => $return_date
				);
				$data['created_at'] = current_time('Y-m-d H:i:s');
				$success = $wpdb->insert(WLSM_BOOKS_ISSUED, $data);

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Issue Book Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to issue books.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - View books issued.
	public static function view_books_issued($request)
	{
		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section 	= false;

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('issue_books', $permissions);
				$manage_class 		= WLSM_M_Role::can('assigned_class');
				if ($manage_class) {
					$restrict_to_section = $section_id;
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$params 	= $request->get_params();
				$id 		= isset($params['id']) ? absint($params['id']) : 0;

				$books_issued_query = WLSM_M_Staff_Library::fetch_book_issued_query($school_id, $session_id, $restrict_to_section);
				$books_issued = $wpdb->get_results($books_issued_query);


				foreach ($books_issued as $book_issued) {
					$returned_text = isset($book_issued->returned_at) ? esc_html(WLSM_Config::get_date_text($book_issued->returned_at)) : '';

					$data[] = array(
						'ID'   				=> isset($book_issued->ID) ? absint($book_issued->ID) : 0,
						'title'   			=> isset($book_issued->title) ? WLSM_M_Staff_Library::get_book_title($book_issued->title) : '',
						'student_name'   	=> isset($book_issued->student_name) ? WLSM_M_Staff_Class::get_name_text($book_issued->student_name) : '',
						'enrollment_number' => isset($book_issued->enrollment_number) ? $book_issued->enrollment_number : '',
						'class_label'   	=> isset($book_issued->class_label) ? WLSM_M_Staff_Class::get_label_text($book_issued->class_label) : '',
						'section_label'   	=> isset($book_issued->section_label) ? WLSM_M_Staff_Class::get_section_label_text($book_issued->section_label) : '',
						'issued_quantity'   => isset($book_issued->issued_quantity) ? WLSM_M_Staff_Library::get_book_quantity($book_issued->issued_quantity) : '',
						'date_issued'   	=> isset($book_issued->date_issued) ? WLSM_M_Staff_Class::get_date_text($book_issued->date_issued) : '',
						'return_date'   	=> isset($book_issued->return_date) ? WLSM_M_Staff_Class::get_date_text($book_issued->return_date) : '',
						'returned_at'   	=> isset($book_issued->returned_at) ? 'Retuened ' . WLSM_M_Staff_Class::get_date_text($book_issued->returned_at) : 'Pending',
						'author'   			=> isset($book_issued->author) ? WLSM_M_Staff_Library::get_book_author($book_issued->author) : '',
						'subject'   		=> isset($book_issued->subject) ? WLSM_M_Staff_Library::get_book_subject($book_issued->subject) : '',
						'rack_number'   	=> isset($book_issued->rack_number) ? WLSM_M_Staff_Library::get_book_rack_number($book_issued->rack_number) : '',
						'book_number'   	=> isset($book_issued->book_number) ? WLSM_M_Staff_Library::get_book_number($book_issued->book_number) : '',
						'isbn_number'   	=> isset($book_issued->isbn_number) ? WLSM_M_Staff_Library::get_book_isbn_number($book_issued->isbn_number) : '',
						'price'   			=> isset($book_issued->price) ? WLSM_Config::get_money_text($book_issued->price, $school_id) : '',
					);
					$response_data['book_issued'] = $data;
				}

				$success = true;
				$message = esc_html__('Books Issued Retrieved Successfully.', 'school-management');
				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to issue books.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Deposit book issued.
	public static function deposit_book_issued($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('issue_books', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 		= $request->get_params();
		$id 			= isset($params['id']) ? absint($params['id']) : 0;

		try {

			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$book_issued = WLSM_M_Staff_Library::get_book_issued($school_id, $session_id, $id);

				if (! $book_issued) {
					throw new Exception(esc_html__('Record not found.', 'school-management'));
				}

				if ($book_issued->returned_at) {
					throw new Exception(esc_html__('Book was already marked as returned.', 'school-management'));
				}

				$now = current_time('Y-m-d H:i:s');

				$data = array(
					'returned_at' => $now,
					'updated_at'  => $now
				);

				$success = $wpdb->update(WLSM_BOOKS_ISSUED, $data, array('ID' => $id));

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Deposit Book Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to issue books.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

