	// Staff - Issue library card.
	public static function issue_library_card($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('issue_library_card', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 				= $request->get_params();
		$card_number_prefix 	= isset($params['card_number_prefix']) ? sanitize_text_field($params['card_number_prefix']) : '';
		$staring_card_number 	= isset($params['staring_card_number']) ? sanitize_text_field($params['staring_card_number']) : '';
		$date_issued       		= isset($params['date_issued']) ? DateTime::createFromFormat(WLSM_Config::date_format(), sanitize_text_field($params['date_issued'])) : NULL;
		$students 				= isset($params['student']) && is_array($params['student']) ? array_map('absint', $params['student']) : '';

		try {

			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				if (empty($staring_card_number)) {
					throw new Exception(esc_html__('Please provide starting library card number.', 'school-management'));
				}

				$first_card_number = $card_number_prefix . $staring_card_number;

				if (strlen($first_card_number) > 47) {
					throw new Exception(esc_html__('Library card number length is too large.', 'school-management'));
				}

				if (empty($date_issued)) {
					throw new Exception(esc_html__('Please specify date issued.', 'school-management'));
				} else {
					$date_issued = $date_issued->format('Y-m-d');
				}

				if (! count($students)) {
					throw new Exception(esc_html__('Please select atleast one student.', 'school-management'));
				}

				$library_card_data = array(
					'date_issued' => $date_issued,
				);

				foreach ($students as $student_id) {
					// Checks if student exists.
					$student = WLSM_M_Staff_General::get_student($school_id, $session_id, $student_id, true, true);

					if (! $student) {
						throw new Exception(esc_html__('Student not found.', 'school-management'));
					}

					$library_card_data['student_record_id'] = $student_id;
					$library_card_data['card_number']       = $card_number_prefix . $staring_card_number;

					// Checks if library card number already exists in this session.
					$library_card_number_exists = WLSM_M_Staff_Library::check_library_card_number_exists($school_id, $session_id, $library_card_data['card_number']);

					if ($library_card_number_exists) {
						throw new Exception(
							sprintf(
								/* translators: %s: library card number */
								esc_html__('Library card number %s already exists for this session.', 'school-management'),
								$library_card_data['card_number']
							)
						);
					}

					// Checks if student library card already exists.
					$student_library_card_exists = WLSM_M_Staff_Library::check_student_library_card_exists($school_id, $session_id, $student->ID);

					if ($student_library_card_exists) {
						throw new Exception(
							sprintf(
								/* translators: %s: enrollment number */
								esc_html__('Student library card already exists for enrollment %s.', 'school-management'),
								$student->enrollment_number
							)
						);
					}

					$library_card_data['created_at'] = current_time('Y-m-d H:i:s');

					$success = $wpdb->insert(WLSM_LIBRARY_CARDS, $library_card_data);

					$staring_card_number++;
				}

				$data['created_at'] = current_time('Y-m-d H:i:s');
				$success = $wpdb->insert(WLSM_BOOKS_ISSUED, $data);

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Issue Book Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to issue books.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - View library cards.
	public static function view_library_cards($request)
	{
		$user_id 				= get_current_user_id();
		$staff 					= WLSM_M::get_staff($user_id);
		$restrict_to_section 	= false;

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('issue_library_card', $permissions);
				$manage_class 		= WLSM_M_Role::can('assigned_class');
				if ($manage_class) {
					$restrict_to_section = $section_id;
				}
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$params 	= $request->get_params();
				$id 		= isset($params['id']) ? absint($params['id']) : 0;

				$library_card_query = WLSM_M_Staff_Library::fetch_library_card_query($school_id, $session_id, $restrict_to_section);
				$library_cards = $wpdb->get_results($library_card_query);


				foreach ($library_cards as $library_card) {
					$data[] = array(
						'ID'   				=> isset($library_card->ID) ? absint($library_card->ID) : 0,
						'card_number'   	=> isset($library_card->card_number) ? $library_card->card_number : '',
						'issued_to'   		=> isset($library_card->student_name) ? WLSM_M_Staff_Class::get_name_text($library_card->student_name) : '',
						'enrollment_number' => isset($library_card->enrollment_number) ? $library_card->enrollment_number : '',
						'class_label'   	=> isset($library_card->class_label) ? WLSM_M_Staff_Class::get_label_text($library_card->class_label) : '',
						'section_label'   	=> isset($library_card->section_label) ? WLSM_M_Staff_Class::get_section_label_text($library_card->section_label) : '',
						'date_issued'   	=> isset($library_card->date_issued) ? WLSM_M_Staff_Class::get_date_text($library_card->date_issued) : '',
					);
					$response_data['library_cards'] = $data;
				}

				$success = true;
				$message = esc_html__('Library Cards Retrieved Successfully.', 'school-management');
				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to issue library cards.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Delete library card.
	public static function delete_library_card($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$permissions 		= unserialize($staff->permissions);
			if ($staff->role == 'admin') {
				$staff_permissions 	= array_keys(WLSM_M_Role::get_permissions());
			} else {
				$staff_permissions 	= in_array('delete_library', $permissions);
			}
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params = $request->get_params();
		$id 	= isset($params['id']) ? absint($params['id']) : 0;

		try {

			if ($staff_permissions) {
				global $wpdb;

				$current_session_id = get_option('wlsm_current_session');
				$session = WLSM_M_Session::get_session($current_session_id);
				if (!$session) {
					throw new Exception(esc_html__('Current session not found. Please contact the administrator.', 'school-management'));
				}
				$session_id = isset($session->ID) ? absint($session->ID) : 0;

				$library_card = WLSM_M_Staff_Library::get_library_card($school_id, $session_id, $id);

				if (! $library_card) {
					throw new Exception(esc_html__('Library card not found.', 'school-management'));
				}

				$success = $wpdb->delete(WLSM_LIBRARY_CARDS, array('ID' => $id));

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Library Card Deleted Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to delete library.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

