	// Staff - Add new admin.
	public static function add_new_admin($request)
	{
		$current_user_id 	= get_current_user_id();
		$staff 				= WLSM_M::get_staff($current_user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user = WLSM_M_Role::can('manage_admins');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($current_user) {
				global $wpdb;

				$user_id = NULL;

				$params 		= $request->get_params();
				$name 			= isset($params['name']) ? sanitize_text_field($params['name']) : '';
				$gender 		= isset($params['gender']) ? sanitize_text_field($params['gender']) : 'male';
				$dob 			= isset($params['dob']) ? DateTime::createFromFormat(WLSM_Config::date_format(), sanitize_text_field($params['dob'])) : NULL;
				$address 		= isset($params['address']) ? sanitize_text_field($params['address']) : '';
				$phone 			= isset($params['phone']) ? sanitize_text_field($params['phone']) : '';
				$email 			= isset($params['email']) ? sanitize_email($params['email']) : '';
				$photo 			= isset($_FILES['photo']) && is_array($_FILES['photo']) ? $_FILES['photo'] : '';
				$joining_date 	= isset($params['joining_date']) ? DateTime::createFromFormat(WLSM_Config::date_format(), sanitize_text_field($params['joining_date'])) : NULL;
				$note			= isset($params['note']) ? sanitize_text_field($params['note']) : '';
				$salary			= isset($params['salary']) ? WLSM_Config::sanitize_money($params['salary']) : 0;
				$designation	= isset($params['designation']) ? sanitize_text_field($params['designation']) : '';
				$qualification	= isset($params['qualification']) ? sanitize_text_field($params['qualification']) : '';

				// Bus Incharge.
				$bus_incharge	= isset($params['bus_incharge']) ? (bool) $params['bus_incharge'] : 0;
				$vehicle_id     = isset($params['vehicle_id']) ? absint($params['vehicle_id']) : 0;

				// Permissions.
				$assign_permissions = array();
				$admin_permissions  = WLSM_M_Role::get_role_permissions( 'admin', $assign_permissions );

				// Login Detail.
				$new_or_existing   = isset($params['staff_new_or_existing']) ? sanitize_text_field($params['staff_new_or_existing']) : '';
				$existing_username = isset($params['existing_username']) ? sanitize_text_field($params['existing_username']) : '';
				$username          = isset($params['username']) ? sanitize_text_field($params['username']) : '';
				$login_email       = isset($params['login_email']) ? sanitize_text_field($params['login_email']) : '';
				$password          = isset($params['password']) ? $params['password'] : '';

				// zoom api
				$api_key      = isset($params['api_key']) ? sanitize_text_field($params['api_key']) : '';
				$api_secret   = isset($params['api_secret']) ? sanitize_text_field($params['api_secret']) : '';
				$redirect_url = isset($params['redirect_url']) ? esc_url_raw($params['redirect_url']) : '';
				$sdk_key      = isset($params['sdk_key']) ? sanitize_text_field($params['sdk_key']) : '';
				$sdk_secret   = isset($params['sdk_secret']) ? sanitize_text_field($params['sdk_secret']) : '';

				// Status.
				$is_active 		= isset($params['is_active']) ? (bool) $params['is_active'] : 1;

				if (empty($name)) {
					throw new Exception(esc_html__('Please specify name.', 'school-management'));
				}

				if (!empty($email)) {
					if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
						throw new Exception(esc_html__('Please provide a valid email.', 'school-management'));
					}
				}

				if (!in_array($gender, array_keys(WLSM_Helper::gender_list($school_id)))) {
					$gender = NULL;
				}
				if (!empty($dob)) {
					$dob = $dob->format('Y-m-d');
				} else {
					$dob = NULL;
				}

				if (!empty($joining_date)) {
					$joining_date = $joining_date->format('Y-m-d');
				} else {
					$joining_date = NULL;
				}

				if ($bus_incharge) {
					if (!$vehicle_id) {
						throw new Exception(esc_html__('Please select a vehicle.', 'school-management'));
					} else {
						$vehicle = WLSM_M_Staff_Transport::get_vehicle($school_id, $vehicle_id);

						if (!$vehicle) {
							throw new Exception(esc_html__('Vehicle not found.', 'school-management'));
						}
					}
				} else {
					$vehicle_id = NULL;
				}

				// Login Detail.
				if ('existing_user' === $new_or_existing) {
					if (empty($existing_username)) {
						throw new Exception(esc_html__('Please provide existing username.', 'school-management'));
					}
				} elseif ('new_user' === $new_or_existing) {
					if (empty($username)) {
						throw new Exception(esc_html__('Please provide username.', 'school-management'));
					}
					if (empty($login_email)) {
						throw new Exception(esc_html__('Please provide login email.', 'school-management'));
					}
					if (!filter_var($login_email, FILTER_VALIDATE_EMAIL)) {
						throw new Exception(esc_html__('Please provide a valid email.', 'school-management'));
					}
					if (empty($password)) {
						throw new Exception(esc_html__('Please provide login password.', 'school-management'));
					}
				}
	
				if (isset($photo['tmp_name']) && !empty($photo['tmp_name'])) {
					if (!WLSM_Helper::is_valid_file($photo, 'image')) {
						throw new Exception(esc_html__('This file type is not allowed.', 'school-management'));
					}
				}

				$attachment_id = NULL;

				if (isset($photo) && is_array($photo)) {
					require_once ABSPATH . 'wp-admin/includes/file.php';
					require_once ABSPATH . 'wp-admin/includes/media.php';
					require_once ABSPATH . 'wp-admin/includes/image.php';

					if (isset($photo) && is_array($photo)) {
						if (!empty($_FILES['photo']['tmp_name'])) {
							$file_array = array(
								'name'     => $_FILES['photo']['name'],
								'type'     => $_FILES['photo']['type'],
								'tmp_name' => $_FILES['photo']['tmp_name'],
								'error'    => $_FILES['photo']['error'],
								'size'     => $_FILES['photo']['size'],
							);

							if (!WLSM_Helper::is_valid_file($file_array, 'image')) {
								throw new Exception(esc_html__('Invalid file format.', 'school-management'));
							}

							$_FILES['photo'] = $file_array;
							$attachment_id = media_handle_upload('photo', 0);

							if (is_wp_error($attachment_id)) {
								throw new Exception($attachment_id->get_error_message());
							}
						}
					}
				}

				if ('existing_user' === $new_or_existing) {
					// Existing user.
					$user = get_user_by('login', $existing_username);
					if (!$user) {
						throw new Exception(esc_html__('Username does not exist.', 'school-management'));
					}
					$user_id = $user->ID;

					if (user_can($user_id, WLSM_ADMIN_CAPABILITY)) {
						throw new Exception(esc_html__('User is a multi-school administrator.', 'school-management'));
					}

					// Check if user already has a staff record in the school.
					$user_has_staff_record = $wpdb->get_row($wpdb->prepare('SELECT sf.ID FROM ' . WLSM_STAFF . ' as sf WHERE sf.user_id = %d AND sf.school_id = %d', $user_id, $school_id));
					
					if ($user_has_staff_record) {
						throw new Exception(esc_html__('The user already has a staff record.', 'school-management'));
					}
				} elseif ('new_user' === $new_or_existing) {
					// New user.
					$user_data = array(
						'user_email' => $login_email,
						'user_login' => $username,
						'user_pass'  => $password,
					);

					$user_id = wp_insert_user($user_data);
					if (is_wp_error($user_id)) {
						throw new Exception($user_id->get_error_message());
					}
				} else {
					$user_id = NULL;
				}

				// Admin data.
				$admin_data = array(
					'name'         => $name,
					'gender'       => $gender,
					'dob'          => $dob,
					'phone'        => $phone,
					'email'        => $email,
					'address'      => $address,
					'salary'       => $salary,
					'designation'  => $designation,
					'qualification'=> $qualification,
					'note'         => $note,
					'joining_date' => $joining_date,
					'vehicle_id'   => $vehicle_id,
					'role_id'      => NULL,
					'photo_id'     => $attachment_id,
					'is_active'    => $is_active,
				);

				$staff_data = array(
					'role'        => 'admin',
					'permissions' => serialize($admin_permissions),
					'user_id'     => $user_id,
				);

				// if User id exists then store then api keys
				if ($user_id) {
					update_user_meta( $user_id, 'api_key', $params['api_key'] );
					update_user_meta( $user_id, 'api_secret', $params['api_secret'] );
					update_user_meta( $user_id, 'redirect_url', $redirect_url );
					update_user_meta( $user_id, 'sdk_key', $params['sdk_key'] );
					update_user_meta( $user_id, 'sdk_secret', $params['sdk_secret'] );
				}

				$staff_data['created_at'] 	= current_time('Y-m-d H:i:s');
				$staff_data['school_id'] 	= $school_id;
				$success 					= $wpdb->insert(WLSM_STAFF, $staff_data);
				$staff_id 					= $wpdb->insert_id;

				$admin_data['created_at'] 	= current_time('Y-m-d H:i:s');
				$admin_data['staff_id'] 	= $staff_id;
				$success 					= $wpdb->insert(WLSM_ADMINS, $admin_data);

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$current_school_exists = false;
				if ($current_school_id = get_user_meta($user_id, 'wlsm_school_id', true)) {
					$staff_in_school = WLSM_M_Admin::user_in_school($current_school_id, $user_id);

					if ($staff_in_school) {
						$current_school_exists = true;
					}
				}

				if (!$current_school_exists) {
					update_user_meta($user_id, 'wlsm_school_id', $school_id);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Admin Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage admins.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Admins details.
	public static function admin_details($request)
	{
		$current_user_id 	= get_current_user_id();
		$staff 				= WLSM_M::get_staff($current_user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user 	= WLSM_M_Role::can('manage_admins');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($current_user) {
				global $wpdb;

				$params 		= $request->get_params();
				$id 			= isset($params['id']) ? absint($params['id']) : 0;

				$admin	= WLSM_M_Staff_General::fetch_staff($school_id, 'admin', $id);

				if ($admin) {
					$user_id  = $admin->user_id;
					
					$data = array(
						'ID'   			=> isset($admin->ID) ? absint($admin->ID) : 0,
						'name'   		=> isset($admin->name) ? WLSM_M_Staff_Class::get_label_text($admin->name) : '',
						'gender'   		=> isset($admin->gender) ? WLSM_M_Staff_Class::get_label_text($admin->gender) : 'male',
						'dob'   		=> isset($admin->dob) ? WLSM_M_Staff_Class::get_date_text($admin->dob) : '',
						'address'		=> isset($admin->address) ? WLSM_M_Staff_Class::get_address_text($admin->address) : '',
						'phone'   		=> isset($admin->phone) ? WLSM_M_Staff_Class::get_phone_text($admin->phone) : '',
						'email'   		=> isset($admin->email) ? WLSM_M_Staff_Class::get_email_text($admin->email) : '',
						'photo'   		=> isset($admin->photo_id) ? wp_get_attachment_url($admin->photo_id) : '',
						'joining_date'	=> isset($admin->joining_date) ? WLSM_M_Staff_Class::get_date_text($admin->joining_date) : '',
						'role'			=> 'Admin',
						'note'			=> isset($admin->note) ? WLSM_M_Staff_Class::get_address_text($admin->note) : '',
						'salary'		=> isset($admin->salary) ? WLSM_M_Staff_Class::get_label_text($admin->salary) : '',
						'designation'	=> isset($admin->designation) ? WLSM_M_Staff_Class::get_label_text($admin->designation) : '',
						'qualification'	=> isset($admin->qualification) ? WLSM_M_Staff_Class::get_label_text($admin->qualification) : '',
						'bus_incharge'	=> isset($admin->vehicle_id) ? 'yes' : 'no',
						'vehicle_id'	=> isset($admin->vehicle_id) ? WLSM_M_Staff_Class::get_label_text($admin->vehicle_id) : '',
						'username'		=> isset($admin->username) ? WLSM_M_Staff_Class::get_label_text($admin->username) : '',
						'login_email'	=> isset($admin->login_email) ? WLSM_M_Staff_Class::get_email_text($admin->login_email) : '',	
						'api_key'		=> isset($user_id) ? get_the_author_meta('api_key', $user_id) : '',	
						'api_secret'	=> isset($user_id) ? get_the_author_meta('api_secret', $user_id) : '',
						'redirect_url'	=> isset($user_id) ? get_the_author_meta('redirect_url', $user_id) : '',
						'sdk_key'		=> isset($user_id) ? get_the_author_meta('sdk_key', $user_id) : '',
						'sdk_secret'	=> isset($user_id) ? get_the_author_meta('sdk_secret', $user_id) : '',
						'status'		=> isset($admin->is_active) ? WLSM_M_Staff_Class::get_status_text($admin->is_active) : ''
					);
					$response_data['admin'] = $data;
				} else {
					throw new Exception(esc_html__('Admin not found.', 'school-management'));
				}

				$success = true;
				$message = esc_html__('Admin Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage admins.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Edit admin.
	public static function edit_admin($request)
	{

		$current_user_id 	= get_current_user_id();
		$staff 				= WLSM_M::get_staff($current_user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user  	= WLSM_M_Role::can('manage_admins');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($current_user) {
				global $wpdb;

				$params 		= $request->get_params();
				$id 			= isset($params['id']) ? absint($params['id']) : 0;
				$name 			= isset($params['name']) ? sanitize_text_field($params['name']) : '';
				$gender 		= isset($params['gender']) ? sanitize_text_field($params['gender']) : 'male';
				$dob 			= isset($params['dob']) ? DateTime::createFromFormat(WLSM_Config::date_format(), sanitize_text_field($params['dob'])) : NULL;
				$address 		= isset($params['address']) ? sanitize_text_field($params['address']) : '';
				$phone 			= isset($params['phone']) ? sanitize_text_field($params['phone']) : '';
				$email 			= isset($params['email']) ? sanitize_email($params['email']) : '';
				$photo 			= isset($_FILES['photo']) && is_array($_FILES['photo']) ? $_FILES['photo'] : '';
				$joining_date 	= isset($params['joining_date']) ? DateTime::createFromFormat(WLSM_Config::date_format(), sanitize_text_field($params['joining_date'])) : NULL;
				$note			= isset($params['note']) ? sanitize_text_field($params['note']) : '';
				$salary			= isset($params['salary']) ?  WLSM_Config::sanitize_money($params['salary']) : 0;
				$designation	= isset($params['designation']) ? sanitize_text_field($params['designation']) : '';
				$qualification	= isset($params['qualification']) ? sanitize_text_field($params['qualification']) : '';

				// Bus Incharge.
				$bus_incharge	= isset($params['bus_incharge']) ? (bool) $params['bus_incharge'] : 0;
				$vehicle_id     = isset($params['vehicle_id']) ? absint($params['vehicle_id']) : 0;

				// Permissions.
				$assign_permissions = array();
				$admin_permissions  = WLSM_M_Role::get_role_permissions( 'admin', $assign_permissions );

				// Login Detail.
				$new_or_existing   = isset($params['staff_new_or_existing']) ? sanitize_text_field($params['staff_new_or_existing']) : '';
				$existing_username = isset($params['existing_username']) ? sanitize_text_field($params['existing_username']) : '';
				$new_login_email   = isset($params['new_login_email']) ? sanitize_text_field($params['new_login_email']) : '';
				$new_password      = isset($params['new_password']) ? sanitize_text_field($params['new_password']) : '';
				$username          = isset($params['username']) ? sanitize_text_field($params['username']) : '';
				$login_email       = isset($params['login_email']) ? sanitize_text_field($params['login_email']) : '';
				$password          = isset($params['password']) ? $params['password'] : '';

				// Status.
				$is_active 		= isset($params['is_active']) ? (bool) $params['is_active'] : 1;

				// zoom api
				$api_key      = isset($params['api_key']) ? sanitize_text_field($params['api_key']) : '';
				$api_secret   = isset($params['api_secret']) ? sanitize_text_field($params['api_secret']) : '';
				$redirect_url = isset($params['redirect_url']) ? esc_url_raw($params['redirect_url']) : '';
				$sdk_key      = isset($params['sdk_key']) ? sanitize_text_field($params['sdk_key']) : '';
				$sdk_secret   = isset($params['sdk_secret']) ? sanitize_text_field($params['sdk_secret']) : '';

				$user_id 	= NULL;

				if ($id) {
					$admin = WLSM_M_Staff_General::get_staff($school_id, 'admin', $id);
					if (!$admin) {
						throw new Exception(esc_html__('Admin not found.', 'school-management'));
					}
					$user_id  = $admin->user_id;
					$staff_id = $admin->staff_id;
				}

				if (empty($name)) {
					throw new Exception(esc_html__('Please specify name.', 'school-management'));
				}

				if (!empty($email)) {
					if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
						throw new Exception(esc_html__('Please provide a valid email.', 'school-management'));
					}
				}

				if (!in_array($gender, array_keys(WLSM_Helper::gender_list($school_id)))) {
					$gender = NULL;
				}
				if (!empty($dob)) {
					$dob = $dob->format('Y-m-d');
				} else {
					$dob = NULL;
				}

				if (!empty($joining_date)) {
					$joining_date = $joining_date->format('Y-m-d');
				} else {
					$joining_date = NULL;
				}

				if ($bus_incharge) {
					if (!$vehicle_id) {
						throw new Exception(esc_html__('Please select a vehicle.', 'school-management'));
					} else {
						$vehicle = WLSM_M_Staff_Transport::get_vehicle($school_id, $vehicle_id);

						if (!$vehicle) {
							throw new Exception(esc_html__('Vehicle not found.', 'school-management'));
						}
					}
				} else {
					$vehicle_id = NULL;
				}

				// Login Detail.
				if ('existing_user' === $new_or_existing) {
					if (!$user_id) {
						if (empty($existing_username)) {
							throw new Exception(esc_html__('Please provide existing username.', 'school-management'));
						}
					} else {
						if (empty($new_login_email)) {
							throw new Exception(esc_html__('Please provide login email.', 'school-management'));
						}
					}
				} elseif ('new_user' === $new_or_existing) {
					if (empty($username)) {
						throw new Exception(esc_html__('Please provide username.', 'school-management'));
					}
					if (empty($login_email)) {
						throw new Exception(esc_html__('Please provide login email.', 'school-management'));
					}
					if (!filter_var($login_email, FILTER_VALIDATE_EMAIL)) {
						throw new Exception(esc_html__('Please provide a valid email.', 'school-management'));
					}
					if (empty($password)) {
						throw new Exception(esc_html__('Please provide login password.', 'school-management'));
					}
				}
	
				if (isset($photo['tmp_name']) && !empty($photo['tmp_name'])) {
					if (!WLSM_Helper::is_valid_file($photo, 'image')) {
						throw new Exception(esc_html__('This file type is not allowed.', 'school-management'));
					}
				}

				$attachment_id = NULL;

				if (isset($photo) && is_array($photo)) {
					require_once ABSPATH . 'wp-admin/includes/file.php';
					require_once ABSPATH . 'wp-admin/includes/media.php';
					require_once ABSPATH . 'wp-admin/includes/image.php';

					if (isset($photo) && is_array($photo)) {
						if (!empty($_FILES['photo']['tmp_name'])) {
							$file_array = array(
								'name'     => $_FILES['photo']['name'],
								'type'     => $_FILES['photo']['type'],
								'tmp_name' => $_FILES['photo']['tmp_name'],
								'error'    => $_FILES['photo']['error'],
								'size'     => $_FILES['photo']['size'],
							);

							if (!WLSM_Helper::is_valid_file($file_array, 'image')) {
								throw new Exception(esc_html__('Invalid file format.', 'school-management'));
							}

							$_FILES['photo'] = $file_array;
							$attachment_id = media_handle_upload('photo', 0);

							if (is_wp_error($attachment_id)) {
								throw new Exception($attachment_id->get_error_message());
							}
						}
					}
				}

				if (! $photo) {
					$attachment_id = $admin->photo_id;
				}

				if ('existing_user' === $new_or_existing) {
					if (!$user_id) {
						// Existing user.
						$user = get_user_by('login', $existing_username);
						if (!$user) {
							throw new Exception(esc_html__('Username does not exist.', 'school-management'));
						}

						$user_id = $user->ID;

						if (user_can($user_id, WLSM_ADMIN_CAPABILITY)) {
							throw new Exception(esc_html__('User is a multi-school administrator.', 'school-management'));
						}

						// Check if user already has a staff record in the school.
						$user_has_staff_record = $wpdb->get_row($wpdb->prepare('SELECT sf.ID FROM ' . WLSM_STAFF . ' as sf WHERE sf.user_id = %d AND sf.school_id = %d AND sf.ID != %d', $user_id, $school_id, $staff_id));

						if ($user_has_staff_record) {
							throw new Exception(esc_html__('The user already has a staff record.', 'school-management'));
						}
					} else {
						$user_data = array(
							'ID'         => $user_id,
							'user_email' => $new_login_email,
						);

						if (!empty($new_password)) {
							$user_data['user_pass'] = $new_password;
						}

						$user_id = wp_update_user($user_data);
						if (is_wp_error($user_id)) {
							throw new Exception($user_id->get_error_message());
						}
					}
				} elseif ('new_user' === $new_or_existing) {
					// New user.
					$user_data = array(
						'user_email' => $login_email,
						'user_login' => $username,
						'user_pass'  => $password,
					);

					$user_id = wp_insert_user($user_data);
					if (is_wp_error($user_id)) {
						throw new Exception($user_id->get_error_message());
					}
				} else {
					$user_id = NULL;
				}

				// Admin data.
				$admin_data = array(
					'name'         => $name,
					'gender'       => $gender,
					'dob'          => $dob,
					'phone'        => $phone,
					'email'        => $email,
					'address'      => $address,
					'salary'       => $salary,
					'designation'  => $designation,
					'qualification'=> $qualification,
					'note'         => $note,
					'joining_date' => $joining_date,
					'vehicle_id'   => $vehicle_id,
					'role_id'      => NULL,
					'photo_id'     => $attachment_id,
					'is_active'    => $is_active,
				);

				$staff_data = array(
					'role'        => 'admin',
					'permissions' => serialize($admin_permissions),
					'user_id'     => $user_id,
				);

				// if User id exists then store then api keys
				if ($user_id) {
					update_user_meta( $user_id, 'api_key', $params['api_key'] );
					update_user_meta( $user_id, 'api_secret', $params['api_secret'] );
					update_user_meta( $user_id, 'redirect_url', $redirect_url );
					update_user_meta( $user_id, 'sdk_key', $params['sdk_key'] );
					update_user_meta( $user_id, 'sdk_secret', $params['sdk_secret'] );
				}

				$staff_data['updated_at'] = current_time('Y-m-d H:i:s');
				$success = $wpdb->update(WLSM_STAFF, $staff_data, array('ID' => $staff_id));

				$admin_data['updated_at'] = current_time('Y-m-d H:i:s');
				$success = $wpdb->update(WLSM_ADMINS, $admin_data, array('ID' => $id, 'staff_id' => $staff_id));

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$current_school_exists = false;
				if ($current_school_id = get_user_meta($user_id, 'wlsm_school_id', true)) {
					$staff_in_school = WLSM_M_Admin::user_in_school($current_school_id, $user_id);

					if ($staff_in_school) {
						$current_school_exists = true;
					}
				}

				if (!$current_school_exists) {
					update_user_meta($user_id, 'wlsm_school_id', $school_id);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Admin Updated Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage admins.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Delete admin.
	public static function delete_admin($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 		= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 	= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user  	= WLSM_M_Role::can('manage_admins');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {

			if ($current_user) {
				global $wpdb;

				$params = $request->get_params();
				$id 	= isset($params['id']) ? absint($params['id']) : 0;
				
				if ($id) {
					$admin = WLSM_M_Staff_General::get_staff($school_id, 'admin', $id);
					if (! $admin) {
						throw new Exception(esc_html__('Admin not found.', 'school-management'));
					}

					$staff_id = $admin->staff_id;
				} else {
					throw new Exception(esc_html__('Invalid admin ID.', 'school-management'));
				}

				$success = $wpdb->delete(WLSM_STAFF, array('ID' => $staff_id));

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Admin Deleted Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage admins.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - View roles.
	public static function view_roles($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user  		= WLSM_M_Role::can('manage_roles');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($current_user) {
				global $wpdb;

				$roles_query = WLSM_M_Staff_General::fetch_role_query($school_id);
				$group_by 	 = ' ' . WLSM_M_Staff_General::fetch_role_query_group_by();
				$roles_query .= $group_by;
				$roles 		 = $wpdb->get_results($roles_query);

				foreach ($roles as $role) {
					$data[] = array(
						'ID'   			=> isset($role->ID) ? absint($role->ID) : 0,
						'role'   		=> isset($role->name) ? WLSM_M_Staff_Class::get_name_text($role->name) : '',
					);
					$response_data['roles'] = $data;
				}

				$success = true;
				$message = esc_html__('Roles Retrieved Successfully.', 'school-management');
				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage roles.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Add new role.
	public static function add_new_role($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user  		= WLSM_M_Role::can('manage_roles');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 			= $request->get_params();
		$name 				= isset($params['name']) ? sanitize_text_field($params['name']) : '';
		$role_permissions 	= isset($params['permissions']) && is_array($params['permissions']) ? $params['permissions'] : '';

		try {

			if ($current_user) {
				global $wpdb;

				if (empty($name)) {
					throw new Exception(esc_html__('Please specify role name.', 'school-management'));
				}

				$role_exist = $wpdb->get_var($wpdb->prepare('SELECT COUNT(*) as count FROM ' . WLSM_ROLES . ' as r WHERE r.name = %s AND r.school_id = %d', $name, $school_id));
				if ($role_exist) {
					throw new Exception(esc_html__('Role already exists with this name.', 'school-management'));
				}

				$role_permissions = array_intersect($role_permissions, array_keys(WLSM_M_Role::get_permissions()));
				
				$data = array(
					'name' 	 		=> $name,
					'permissions'  	=> serialize($role_permissions),
					'school_id' 	=> $school_id,
				);
				$data['created_at'] = current_time('Y-m-d H:i:s');
				$success 			= $wpdb->insert(WLSM_ROLES, $data);

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Role Added Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage roles.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Role details.
	public static function role_details($request)
	{
		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user  		= WLSM_M_Role::can('manage_roles');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		try {
			if ($current_user) {
				global $wpdb;

				$params 	= $request->get_params();
				$id 		= isset($params['id']) ? absint($params['id']) : 0;

				$role	= WLSM_M_Staff_General::fetch_role($school_id, $id);

				if ($role) {
					$data = array(
						'ID'   	 		=> isset($role->ID) ? absint($role->ID) : 0,
						'name'   		=> isset($role->name) ? WLSM_M_Staff_Class::get_label_text($role->name) : '',
						'permissions'   => isset($role->permissions) ? unserialize($role->permissions) : '',
					);
					$response_data['role_details'] = $data;
				} else {
					throw new Exception(esc_html__('Role not found.', 'school-management'));
				}

				$success = true;
				$message = esc_html__('Role Retrieved Successfully.', 'school-management');

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage roles.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		if (isset($response_data)) {
			$response['data'] = $response_data;
		}

		return new WP_REST_Response($response, 200);
	}

	// Staff - Edit role.
	public static function edit_role($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user  		= WLSM_M_Role::can('manage_roles');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params 			= $request->get_params();
		$id 				= isset($params['id']) ? absint($params['id']) : 0;
		$name 				= isset($params['name']) ? sanitize_text_field($params['name']) : '';
		$role_permissions 	= isset($params['permissions']) && is_array($params['permissions']) ? $params['permissions'] : '';

		try {

			if ($current_user) {
				global $wpdb;

				$role 	= WLSM_M_Staff_General::get_role($school_id, $id);
				if (empty($role)) {
					throw new Exception(esc_html__('Role not found.', 'school-management'));
				}

				if (empty($name)) {
					throw new Exception(esc_html__('Please specify role name.', 'school-management'));
				}

				$role_exist = $wpdb->get_var($wpdb->prepare('SELECT COUNT(*) as count FROM ' . WLSM_ROLES . ' as r WHERE r.name = %s AND r.school_id = %d AND r.ID != %d', $name, $school_id, $id));
				if ($role_exist) {
					throw new Exception(esc_html__('Role already exists with this name.', 'school-management'));
				}

				$role_permissions = array_intersect($role_permissions, array_keys(WLSM_M_Role::get_permissions()));

				$data = array(
					'name' 	 		=> $name,
					'permissions'  	=> serialize($role_permissions),
					'school_id' 	=> $school_id,
				);

				$data['updated_at'] = current_time('Y-m-d H:i:s');
				$success = $wpdb->update(WLSM_ROLES, $data, array('ID' => $id, 'school_id' => $school_id));

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Role Updated Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage roles.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}

	// Staff - Delete role.
	public static function delete_role($request)
	{

		$user_id 	= get_current_user_id();
		$staff 		= WLSM_M::get_staff($user_id);

		if ($staff) {
			$school_id 			= isset($staff->school_id) ? absint($staff->school_id) : 0;
			$section_id 		= isset($staff->section_id) ? absint($staff->section_id) : 0;
			$current_user  		= WLSM_M_Role::can('manage_roles');
		} else {
			throw new Exception(esc_html__('Staff not found.', 'school-management'));
		}

		$params = $request->get_params();
		$id 	= isset($params['id']) ? absint($params['id']) : 0;

		try {

			if ($current_user) {
				global $wpdb;

				$role = WLSM_M_Staff_General::get_role($school_id, $id);
				if (empty($role)) {
					throw new Exception(esc_html__('Role not found.', 'school-management'));
				}

				$success = $wpdb->delete(WLSM_ROLES, array('ID' => $id));

				WLSM_Helper::check_buffer();

				if (false === $success) {
					throw new Exception($wpdb->last_error);
				}

				$wpdb->query('COMMIT;');

				$response_data = array();

				$success = true;
				$message = esc_html__('Role Deleted Successfully.', 'school-management');
			} else {
				$success = false;
				throw new Exception(esc_html__('You do not have permission to manage roles.', 'school-management'));
			}
		} catch (Exception $exception) {
			$success = false;
			$message = $exception->getMessage();
		}

		$response = array(
			'success' => (bool) $success,
			'message' => $message,
		);

		return new WP_REST_Response($response, 200);
	}
}